  box-shadow: 0 0 0 1px #7dd3fc, 0 0 18px rgba(125, 211, 252, .55), inset 0 0 14px rgba(255, 255, 255, .8), inset 0 -8px 14px rgba(56, 189, 248, .35);
}
.skin-ice .slot {
  background: linear-gradient(180deg, #ffffff 0%, #f0f9ff 45%, #bae6fd 70%, #7dd3fc 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 1px 0 #fff) drop-shadow(0 0 5px rgba(56, 189, 248, .7));
