.skin-ice .slot.spinning { opacity: .85; animation: ice-shiver .09s steps(2) infinite; }
@keyframes ice-shiver { 50% { transform: translateX(.03em); filter: drop-shadow(0 0 8px #e0f2fe); } }
.skin-ice .slot.revealed { animation: ice-freeze .65s ease-out backwards; }
@keyframes ice-freeze { 0% { transform: scale(1.5); filter: drop-shadow(0 0 16px #fff) brightness(2) blur(2px); opacity: .3; } 45% { transform: scale(.95); filter: drop-shadow(0 0 10px #e0f2fe) brightness(1.4); opacity: 1; } 100% { transform: none; } }
.side-ice { --side-border: #7dd3fc; --side-glow: 0 0 16px rgba(125, 211, 252, .35), inset 0 0 18px rgba(224, 242, 254, .25); --side-ink: #bae6fd; --side-ink-glow: 0 0 6px #e0f2fe;
  --side-bg: linear-gradient(125deg, transparent 35%, rgba(255, 255, 255, .16) 42%, transparent 48%), radial-gradient(60% 40% at 0% 0%, rgba(224, 242, 254, .3), transparent), radial-gradient(60% 40% at 100% 100%, rgba(186, 230, 253, .25), transparent), linear-gradient(180deg, rgba(224, 242, 254, .14), rgba(125, 211, 252, .1));
  --deco-a: '❄'; --deco-b: '❅ ❆'; }
.side-ice::before, .side-ice::after { font-size: 1.1rem; animation: snow-turn 6s linear infinite; }
@keyframes snow-turn { to { transform: rotate(360deg); } }

/* --- Circuit : carte électronique verte, pistes cuivrées, chiffres qui s'allument par impulsion électrique */
.num-card.skin-circuit {
  background:
    radial-gradient(circle at 8% 25%, #fbbf24 0 2px, #92400e 2.5px 3.5px, transparent 4px),
    radial-gradient(circle at 92% 75%, #fbbf24 0 2px, #92400e 2.5px 3.5px, transparent 4px),
    linear-gradient(90deg, transparent 0 8%, rgba(251, 191, 36, .45) 8% 9%, transparent 9%) 0 25% / 100% 2px no-repeat,
    linear-gradient(90deg, transparent 91%, rgba(251, 191, 36, .45) 91% 92%, transparent 92%) 0 75% / 100% 2px no-repeat,
    repeating-linear-gradient(0deg, rgba(34, 197, 94, .08) 0 1px, transparent 1px 12px),
    repeating-linear-gradient(90deg, rgba(34, 197, 94, .08) 0 1px, transparent 1px 12px),
    linear-gradient(135deg, #064e3b, #022c22);
  border: 2px solid #10b981; border-radius: .35rem;
  box-shadow: 0 0 0 2px #022c22, 0 0 14px rgba(16, 185, 129, .4);
}
.skin-circuit .slot { font-family: 'Share Tech Mono', monospace; font-weight: 400; color: #a7f3d0; text-shadow: 0 0 4px #34d399, 0 0 10px #10b981; }
.skin-circuit .slot.spinning { opacity: .9; color: #6ee7b7; animation: circuit-flicker .12s steps(2) infinite; }
@keyframes circuit-flicker { 50% { opacity: .35; text-shadow: none; } }
.skin-circuit .slot.revealed { animation: circuit-zap .55s ease-out backwards; }
@keyframes circuit-zap {
  0% { color: #fff; text-shadow: 0 0 6px #fff, 0 0 18px #22d3ee, 0 0 30px #22d3ee; transform: skewX(-12deg) scale(1.2); }
  20% { transform: skewX(10deg); } 35% { transform: skewX(-5deg); opacity: .6; } 50% { opacity: 1; }
  100% { transform: none; }
}
.side-circuit { --side-border: #10b981; --side-glow: 0 0 12px rgba(16, 185, 129, .3); --side-ink: #34d399; --side-ink-glow: 0 0 6px #10b981;
  --side-bg: linear-gradient(90deg, rgba(251, 191, 36, .25) 0 2px, transparent 2px) 18px 0 / 60px 100% no-repeat, linear-gradient(0deg, rgba(251, 191, 36, .22) 0 2px, transparent 2px) 0 30px / 100% 60px no-repeat, repeating-linear-gradient(0deg, rgba(16, 185, 129, .07) 0 1px, transparent 1px 14px), repeating-linear-gradient(90deg, rgba(16, 185, 129, .07) 0 1px, transparent 1px 14px), linear-gradient(135deg, rgba(6, 78, 59, .25), rgba(2, 44, 34, .15));
  --deco-a: '⚡'; --deco-b: '▣ ▢ ▣'; }
.side-circuit::before { animation: zap-blink 1.7s steps(1) infinite; }
@keyframes zap-blink { 0%, 60%, 70%, 100% { opacity: .9; } 65% { opacity: .1; } }
.side-circuit::after { font-family: 'Share Tech Mono', monospace; font-size: .8rem; }

/* --- Nixie : tubes de verre des années 50, filament orange, grille métallique */
.num-card.skin-nixie { background: linear-gradient(180deg, #1c1917, #0c0a09); border: 3px solid #44403c; border-radius: .5rem; box-shadow: inset 0 2px 6px rgba(0, 0, 0, .8), 0 6px 14px rgba(0, 0, 0, .4); }
.skin-nixie .slot {
  font-size: .62em; width: 1.2em; height: 1.75em; margin: 0 .06em; display: inline-flex; align-items: center; justify-content: center;
  font-family: 'Share Tech Mono', monospace; font-weight: 400; color: #ffb347;
  text-shadow: 0 0 2px #fff4e0, 0 0 6px #ff8c1a, 0 0 14px #ff6a00, 0 0 24px rgba(255, 106, 0, .6);
  border-radius: .55em .55em .2em .2em;
  background:
    radial-gradient(circle, rgba(120, 113, 108, .35) 0 .5px, transparent 1px) 0 0 / 4px 4px,
    radial-gradient(ellipse at 50% 55%, rgba(255, 120, 20, .22), transparent 70%),
    linear-gradient(90deg, rgba(255, 255, 255, .06), rgba(255, 255, 255, .18) 20%, transparent 35%, transparent 80%, rgba(255, 255, 255, .08));
  box-shadow: inset 0 0 0 1px rgba(214, 211, 209, .25), inset 0 -.25em .3em rgba(0, 0, 0, .6), 0 .1em 0 #292524;
}
.skin-nixie .slot.spinning { opacity: 1; color: rgba(255, 179, 71, .5); animation: nixie-cycle .1s steps(2) infinite; }
@keyframes nixie-cycle { 50% { text-shadow: 0 0 4px #ff8c1a; opacity: .6; } }
.skin-nixie .slot.revealed { animation: nixie-warm .8s ease-out backwards; }
@keyframes nixie-warm { 0% { color: #7c2d12; text-shadow: none; } 25% { color: #ffb347; text-shadow: 0 0 20px #ff6a00; } 35% { color: #9a3412; text-shadow: none; } 55% { color: #ffd199; text-shadow: 0 0 2px #fff, 0 0 12px #ff8c1a, 0 0 28px #ff6a00; } 100% {} }
.skin-nixie .slot.collapsed { width: 0; height: 0; margin: 0; box-shadow: none; background: none; }
.side-nixie { --side-border: #78716c; --side-glow: 0 0 14px rgba(255, 140, 26, .2); --side-ink: #ffb347; --side-ink-glow: 0 0 6px #ff6a00;
  --side-bg: radial-gradient(80% 60% at 50% 50%, rgba(255, 106, 0, .1), transparent 70%), repeating-linear-gradient(90deg, rgba(120, 113, 108, .08) 0 2px, transparent 2px 7px), linear-gradient(180deg, rgba(41, 37, 36, .25), rgba(12, 10, 9, .2));
  --deco-a: 'IN-14'; --deco-b: '170 V'; }
.side-nixie::before, .side-nixie::after { font-family: 'Share Tech Mono', monospace; font-size: .75rem; animation: nixie-hum 2.6s ease-in-out infinite; }
@keyframes nixie-hum { 50% { opacity: .45; } }

/* --- Vaporwave : coucher de soleil rayé, grille en perspective qui défile, chiffres chromés rose-cyan */
@keyframes grid-run { to { background-position: 0 0, 0 10px; } }

/* --- Diamond : gemme taillée, facettes, éclats prismatiques qui scintillent (le plus cher) */
.num-card.skin-diamond {
  background:
    conic-gradient(from 20deg at 30% 40%, rgba(255, 255, 255, .25), transparent 12%, rgba(165, 243, 252, .2) 25%, transparent 38%, rgba(233, 213, 255, .22) 55%, transparent 70%, rgba(255, 255, 255, .2) 85%, transparent),
    conic-gradient(from 200deg at 75% 65%, rgba(255, 255, 255, .2), transparent 15%, rgba(254, 205, 211, .2) 35%, transparent 50%, rgba(186, 230, 253, .22) 70%, transparent),
    linear-gradient(135deg, #0f172a, #1e293b 50%, #0f172a);
  border: 2px solid transparent; border-radius: .7rem;
  background-clip: padding-box;
  box-shadow: 0 0 0 2px #e0f2fe, 0 0 0 4px rgba(186, 230, 253, .35), 0 0 22px rgba(165, 243, 252, .45), 0 0 44px rgba(233, 213, 255, .25);
}
.skin-diamond .slot {
  background: linear-gradient(115deg, #fff 0%, #a5f3fc 18%, #fff 30%, #e9d5ff 44%, #fff 56%, #fecdd3 70%, #fff 82%, #bae6fd 100%);
  background-size: 300% 100%;
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 0 3px rgba(255, 255, 255, .9)) drop-shadow(0 0 10px rgba(165, 243, 252, .6));
  animation: prism-shift 3.5s linear infinite;
}
@keyframes prism-shift { to { background-position: 300% 0; } }
.skin-diamond .slot.spinning { opacity: 1; animation: prism-shift .5s linear infinite, diamond-spin .3s linear infinite; }
@keyframes diamond-spin { 0% { transform: perspective(200px) rotateY(0); } 100% { transform: perspective(200px) rotateY(360deg); } }
.skin-diamond .slot.revealed { animation: diamond-flash .7s ease-out backwards, prism-shift 3.5s .7s linear infinite; }
@keyframes diamond-flash { 0% { transform: scale(1.8) rotate(-20deg); filter: brightness(3) drop-shadow(0 0 20px #fff); opacity: 0; } 40% { transform: scale(.92) rotate(3deg); filter: brightness(1.8) drop-shadow(0 0 14px #a5f3fc); opacity: 1; } 100% { transform: none; } }
.side-diamond { --side-border: #e0f2fe; --side-glow: 0 0 18px rgba(165, 243, 252, .35), 0 0 32px rgba(233, 213, 255, .2); --side-ink: #fff; --side-ink-glow: 0 0 6px #a5f3fc, 0 0 12px #e9d5ff;
  --side-bg: conic-gradient(from 30deg at 20% 30%, rgba(165, 243, 252, .12), transparent 20%, rgba(233, 213, 255, .12) 45%, transparent 65%, rgba(254, 205, 211, .1) 85%, transparent), conic-gradient(from 210deg at 80% 75%, rgba(186, 230, 253, .12), transparent 25%, rgba(255, 255, 255, .1) 55%, transparent), linear-gradient(135deg, rgba(15, 23, 42, .2), rgba(30, 41, 59, .15));
  --deco-a: '✦'; --deco-b: '💎'; }
.side-diamond::before { animation: gold-sparkle 1.6s ease-in-out infinite; }
.side-diamond::after { font-size: 1.1rem; animation: gem-glint 2.4s ease-in-out infinite; }
@keyframes gem-glint { 0%, 70%, 100% { filter: none; transform: none; } 80% { filter: brightness(1.8) drop-shadow(0 0 6px #fff); transform: scale(1.2) rotate(-10deg); } }

/* ================================================================== Bakery : pain et cookies tout juste sortis du four (2026-10-13)
   Une plaque de cuisson et son papier sulfurisé ; les chiffres en pâte dorée, croûte plus foncée sur les bords,
   pépites de chocolat et graines de sésame ; ils lèvent en cuisant. La vapeur qui monte à la fin de la révélation
   est dessinée par js/skinfx.js. */
.num-card.skin-bakery {
  background:
    linear-gradient(97deg, transparent 38%, rgba(160, 120, 70, .08) 39%, transparent 41%),
    linear-gradient(8deg, transparent 62%, rgba(160, 120, 70, .07) 63%, transparent 65%),
    radial-gradient(ellipse 80% 70% at 50% 40%, #fbf3e2, #f1e2c4 75%, #e6d1a8);
  border: 3px solid #3b2a1e; border-radius: .7rem;
  box-shadow: 0 0 0 2px #6b4f3a, inset 0 0 0 4px #2f2219, inset 0 0 0 5px rgba(255, 255, 255, .12), inset 0 0 18px rgba(120, 80, 40, .35), 0 0 18px rgba(245, 158, 11, .25), 0 10px 18px rgba(0, 0, 0, .35);
}
.skin-bakery .slot {
  position: relative; font-family: 'Inter', system-ui, sans-serif; font-weight: 900; width: .66em; color: transparent;
  background:
    radial-gradient(ellipse .05em .035em at 30% 30%, #3b1f0e 60%, transparent 75%) 0 0 / .41em .37em,
    radial-gradient(ellipse .04em .03em at 70% 60%, #4a2812 60%, transparent 75%) .19em .11em / .53em .44em,
    radial-gradient(ellipse .022em .012em, #fff6dc 60%, transparent 80%) .07em .24em / .29em .31em,
    linear-gradient(180deg, #ffe2a3 0%, #f2b15a 26%, #d98a34 55%, #b5651d 82%, #8a4513 100%);
  -webkit-background-clip: text; background-clip: text;
  -webkit-text-stroke: .018em rgba(110, 52, 14, .85);
  filter: drop-shadow(0 .04em 0 #6b3410) drop-shadow(0 .09em .1em rgba(60, 30, 10, .4));
}
.skin-bakery .slot.ghost { opacity: .25; }
/* Pendant le tirage : la pâte est pétrie (s'écrase, s'étire). */
.skin-bakery .slot.spinning { opacity: .85; animation: bakery-knead .2s var(--ease-in-out) infinite alternate; }
@keyframes bakery-knead { from { transform: scale(1.1, .88) translateY(.04em); filter: saturate(.4) brightness(1.2); } to { transform: scale(.92, 1.08) translateY(-.03em); filter: saturate(.55) brightness(1.15); } }
/* Il se pose : pâte crue et pâle, qui lève puis dore. */
.skin-bakery .slot.revealed { animation: bakery-rise .6s var(--ease-out) backwards; }
@keyframes bakery-rise {
  0% { transform: scale(.9, .72) translateY(.12em); filter: saturate(.25) brightness(1.3); }
  55% { transform: scale(1.04, 1.08) translateY(-.03em); filter: saturate(.8) brightness(1.12) drop-shadow(0 0 .2em rgba(255, 179, 71, .8)); }
  100% { transform: none; }
}
.side-bakery { --side-border: #b5651d; --side-glow: 0 0 14px rgba(245, 158, 11, .25); --side-ink: #b5651d;
  --side-bg: repeating-linear-gradient(0deg, rgba(220, 38, 38, .09) 0 10px, transparent 10px 20px), repeating-linear-gradient(90deg, rgba(220, 38, 38, .09) 0 10px, transparent 10px 20px), linear-gradient(180deg, rgba(251, 243, 226, .25), rgba(230, 209, 168, .18));
  --deco-a: '🥖'; --deco-b: '🍪 🥐'; }
.side-bakery::before { font-size: 1.15rem; animation: bakery-wobble 3s ease-in-out infinite; }
@keyframes bakery-wobble { 0%, 100% { transform: rotate(-6deg); } 50% { transform: rotate(6deg) translateY(-1px); } }

/* ================================================================== duels à 3 joueurs ou plus : plus léger (2026-09-28)
   Avec 10 cartes animées (bots aux skins au hasard), les décors en boucle font saccader les petites machines :
   on garde les cartes et leurs révélations, on coupe les animations de décor permanentes des cadres. */
.room-stage.many .room-side[class*="side-"],
.room-stage.many .room-side[class*="side-"]::before,
.room-stage.many .room-side[class*="side-"]::after { animation: none; }
.room-stage.many .side-embers { display: none; }
.room-stage.many .num-card::after { animation: none; opacity: 0; }
.room-stage.many .num-card.skin-vaporwave::before, .room-stage.many .num-card.skin-ocean { animation: none; }
.room-stage.many .room-side { transition: box-shadow .3s ease, border-color .3s ease; }

/* ================================================================== Blocks : blocs de voxels herbe-terre (2026-09-28)
   Chaque chiffre est gravé dans un bloc pixelisé (dessus d'herbe dentelé, terre mouchetée) ; pendant le tirage les blocs
   sont « minés » (fissures qui s'agrandissent), puis le bloc se pose en rebondissant. */
.num-card.skin-blocks {
  background:
    linear-gradient(0deg, rgba(0, 0, 0, .25) 0 3px, transparent 3px) 0 0 / 100% 12px,
    linear-gradient(180deg, #7dd3fc, #bae6fd 70%, #86efac 70%, #4ade80);
  border: 3px solid #1f2937; border-radius: 0; box-shadow: 4px 4px 0 rgba(0, 0, 0, .45);
  image-rendering: pixelated;
}
.skin-blocks .slot {
  --px: .07em;
  font-family: 'Press Start 2P', monospace; font-size: .52em; width: 1.7em; height: 1.7em; margin: 0 .05em;
  display: inline-flex; align-items: center; justify-content: center; position: relative;
  color: #fef3c7; text-shadow: .09em .09em 0 #3f2a14;
  background:
    /* herbe dentelée qui déborde sur la terre */
    linear-gradient(90deg, #5fa83a 0 12%, transparent 12% 25%, #5fa83a 25% 37%, transparent 37% 62%, #5fa83a 62% 75%, transparent 75% 88%, #5fa83a 88%) 0 22% / 100% 10% no-repeat,
    linear-gradient(180deg, #7cc450 0 8%, #6ab43e 8% 16%, #5fa83a 16% 22%, transparent 22%),
    /* mouchetures de terre (carrés de pixels) */
    linear-gradient(90deg, rgba(0, 0, 0, .16) 0 12.5%, transparent 12.5% 50%, rgba(255, 255, 255, .08) 50% 62.5%, transparent 62.5%) 0 0 / 100% 25%,
    linear-gradient(90deg, transparent 0 25%, rgba(0, 0, 0, .14) 25% 37.5%, transparent 37.5% 75%, rgba(0, 0, 0, .12) 75% 87.5%, transparent 87.5%) 0 12.5% / 100% 25%,
    #8b5a2b;
  box-shadow: inset calc(-1 * var(--px)) calc(-1 * var(--px)) 0 rgba(0, 0, 0, .35), inset var(--px) var(--px) 0 rgba(255, 255, 255, .18), 0 0 0 var(--px) #2a1a0c;
}
/* fissures de minage, par-dessus le bloc */
.skin-blocks .slot::after { content: ''; position: absolute; inset: 0; pointer-events: none; opacity: 0;
  background:
    linear-gradient(45deg, transparent 46%, rgba(20, 12, 4, .8) 46% 54%, transparent 54%) 30% 30% / 50% 50% no-repeat,
    linear-gradient(-45deg, transparent 46%, rgba(20, 12, 4, .8) 46% 54%, transparent 54%) 70% 60% / 45% 45% no-repeat,
    linear-gradient(90deg, transparent 45%, rgba(20, 12, 4, .7) 45% 55%, transparent 55%) 40% 80% / 40% 30% no-repeat; }
.skin-blocks .slot.spinning { opacity: 1; color: rgba(254, 243, 199, .55); animation: mine-hit .18s steps(2) infinite; }
.skin-blocks .slot.spinning::after { animation: crack-grow .9s steps(4) infinite; }
@keyframes mine-hit { 50% { transform: translate(.04em, .04em) scale(.96); } }
@keyframes crack-grow { 0% { opacity: 0; transform: scale(.4); } 100% { opacity: 1; transform: scale(1); } }
.skin-blocks .slot.revealed { animation: block-place .5s steps(5) backwards; }
@keyframes block-place { 0% { transform: translateY(-1.2em); opacity: 0; } 60% { transform: translateY(.08em); opacity: 1; } 80% { transform: translateY(-.05em); } 100% { transform: none; } }
.skin-blocks .slot.collapsed { width: 0; height: 0; margin: 0; box-shadow: none; background: none; }
.side-blocks { --side-border: #3f2a14; --side-glow: 4px 4px 0 rgba(0, 0, 0, .35); --side-ink: #fef3c7; border-radius: 0 !important;
  --side-bg:
    linear-gradient(180deg, rgba(125, 196, 80, .35) 0 10px, transparent 10px),
    conic-gradient(rgba(0, 0, 0, .1) 25%, transparent 0 50%, rgba(0, 0, 0, .06) 0 75%, transparent 0) 0 0 / 16px 16px,
    conic-gradient(transparent 25%, rgba(255, 255, 255, .05) 0 50%, transparent 0) 8px 8px / 24px 24px,
    linear-gradient(180deg, rgba(139, 90, 43, .3), rgba(90, 58, 28, .38));
  --deco-a: '⛏️'; --deco-b: '🟫🟫'; }
.side-blocks::before { font-size: 1.2rem; transform-origin: 80% 80%; animation: pickaxe-swing 1.1s ease-in-out infinite; }
@keyframes pickaxe-swing { 0%, 100% { transform: rotate(0); } 40% { transform: rotate(-35deg); } 55% { transform: rotate(8deg); } }
.room-stage.many .skin-blocks .slot::after { display: none; }

/* ================================================================== passe 3D et style sur tous les skins (2026-09-28)
   Relief seulement quand la matière s'y prête : chiffres extrudés (couches d'ombre décalées d'1 px vers le bas-droite),
   cartes épaisses (tranche visible), vraie perspective pour les dés et les blocs. LCD, Scoreboard, Matrix, Circuit et
   Fire restent plats : ce sont des écrans ou de la lumière. */

/* Décors texte des cadres de duel : en bas, pour ne jamais chevaucher le nom du joueur (en haut, au centre). */
.room-side[class*="side-"]::before { top: auto; bottom: .5rem; left: .6rem; }
.side-neon::before, .side-scoreboard::before, .side-nixie::before, .side-lcd::before, .side-circuit::after { font-size: .65rem; }

/* --- Neon : tubes de verre fixés sur un panneau (petites attaches), profondeur par l'ombre portée du halo */
.num-card.skin-neon { box-shadow: 0 0 14px rgba(255, 79, 216, .55), inset 0 0 12px rgba(255, 79, 216, .25), 0 10px 18px -6px rgba(0, 0, 0, .6); }
.skin-neon .slot { text-shadow: 0 0 2px #fff, 0 0 6px #fff, 0 0 12px #ff4fd8, 0 0 26px #ff4fd8, .06em .12em .1em rgba(255, 79, 216, .35); }

/* --- Pixel : chiffres en voxels (extrusion en marches d'escalier) */
.skin-pixel .slot { text-shadow: .06em .06em 0 #ff004d, .12em .12em 0 #b0003a, .18em .18em 0 #6b0023; }
.num-card.skin-pixel { box-shadow: 4px 4px 0 #0e1a3a, 8px 8px 0 #000; }

/* --- Jersey : numéro brodé en relief (fil blanc, bord noir, ombre de tissu), maillot en plis */
.num-card.skin-jersey {
  background: linear-gradient(90deg, rgba(0, 0, 0, .18), transparent 18%, transparent 82%, rgba(0, 0, 0, .18)),
    repeating-linear-gradient(90deg, #d7263d 0 14px, #b81d31 14px 28px);
  box-shadow: inset 0 -8px 12px rgba(0, 0, 0, .25), 0 6px 0 #7f1422, 0 10px 16px rgba(0, 0, 0, .35);
}
.skin-jersey .slot { text-shadow: -2px -2px 0 #111, 2px -2px 0 #111, -2px 2px 0 #111, 2px 2px 0 #111, 3px 4px 0 #111, 4px 6px 4px rgba(0, 0, 0, .45); }

/* --- Slots : machine épaisse (tranche dorée), rouleaux cylindriques plus marqués */
.num-card.skin-slots { box-shadow: 0 0 0 2px #78350f, 0 7px 0 #92400e, 0 12px 18px rgba(0, 0, 0, .4), inset 0 2px 6px rgba(0, 0, 0, .4); }
.skin-slots .slot { box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .35), inset 0 .45em .35em -.2em rgba(0, 0, 0, .45), inset 0 -.45em .35em -.2em rgba(0, 0, 0, .45), 0 .06em 0 rgba(255, 255, 255, .25); }

/* --- Dice : dés en cubes avec tranche, tapis creusé */
.num-card.skin-dice { box-shadow: 0 6px 0 #5b2c0b, 0 12px 18px rgba(0, 0, 0, .45), inset 0 0 22px rgba(0, 0, 0, .45); }
.skin-dice .slot { box-shadow: .08em .12em 0 #9ca3af, .14em .18em 0 #6b7280, 0 .3em .35em rgba(0, 0, 0, .35); }

/* --- Chrome : lettres de métal extrudées */
.skin-chrome .slot { filter: drop-shadow(1px 1px 0 #4b5563) drop-shadow(1px 1px 0 #374151) drop-shadow(1px 2px 0 #1f2937) drop-shadow(0 4px 4px rgba(0, 0, 0, .5)); }
.num-card.skin-chrome { box-shadow: inset 0 1px 0 rgba(255, 255, 255, .35), inset 0 -2px 0 rgba(0, 0, 0, .4), 0 5px 0 #0b0f17, 0 10px 16px rgba(0, 0, 0, .45); }

/* --- Gold : lingot épais, chiffres frappés en relief */
.num-card.skin-gold { box-shadow: 0 0 14px rgba(212, 160, 23, .4), 0 5px 0 #7a5a00, 0 10px 16px rgba(0, 0, 0, .45), inset 0 1px 0 rgba(255, 226, 122, .35); }
.skin-gold .slot { filter: drop-shadow(1px 1px 0 #a16207) drop-shadow(1px 1px 0 #854d0e) drop-shadow(1px 2px 0 #713f12) drop-shadow(0 4px 4px rgba(0, 0, 0, .5)); }

/* --- Galaxy : défilement en vitesse lumière (traînées) au lieu d'un flou, étoiles en profondeur */
.skin-galaxy .slot.spinning { opacity: 1; filter: none; animation: warp-streak .14s linear infinite; }
@keyframes warp-streak {
  0% { transform: scaleX(1.25) translateX(-.05em); text-shadow: -.25em 0 .06em rgba(196, 181, 253, .6), -.5em 0 .1em rgba(139, 92, 246, .35); }
  100% { transform: scaleX(1.1) translateX(.05em); text-shadow: -.18em 0 .05em rgba(196, 181, 253, .5), -.4em 0 .1em rgba(139, 92, 246, .3); }
}

/* --- Rainbow : lettres extrudées sombres, pour que les couleurs ressortent */
.skin-rainbow .slot { filter: drop-shadow(1px 1px 0 #3b0764) drop-shadow(1px 1px 0 #1e1b4b) drop-shadow(0 3px 4px rgba(0, 0, 0, .6)); }

/* --- Candy : bonbons épais et brillants (reflet en haut de chaque chiffre) */
.skin-candy .slot { position: relative; }
.skin-candy .slot::after { content: ''; position: absolute; left: 22%; top: 16%; width: 30%; height: 14%; border-radius: 50%; background: rgba(255, 255, 255, .7); filter: blur(.5px); pointer-events: none; }
.num-card.skin-candy { box-shadow: 0 0 0 3px #f472b6, 0 7px 0 #be185d, 0 12px 18px rgba(236, 72, 153, .35), inset 0 -6px 10px rgba(236, 72, 153, .25), inset 0 6px 8px rgba(255, 255, 255, .8); }

/* --- Ocean : chiffres vus sous l'eau (légère réfraction bleutée en profondeur) */
.skin-ocean .slot { text-shadow: 0 0 6px rgba(125, 211, 252, .9), 1px 2px 0 #0c4a6e, 2px 4px 0 rgba(8, 47, 73, .7), 0 8px 10px rgba(2, 20, 40, .6); }

/* --- Ice : bloc de glace épais, chiffres taillés dans la glace */
.num-card.skin-ice { box-shadow: 0 0 0 1px #7dd3fc, 0 6px 0 #0c4a6e, 0 0 18px rgba(125, 211, 252, .55), 0 12px 16px rgba(0, 0, 0, .35), inset 0 0 14px rgba(255, 255, 255, .5); }
.skin-ice .slot { filter: drop-shadow(1px 1px 0 #7dd3fc) drop-shadow(1px 1px 0 #38bdf8) drop-shadow(0 0 5px rgba(56, 189, 248, .7)); }

/* --- Blocks : vrais cubes (face du dessus en perspective) */
.skin-blocks .slot::before { content: ''; position: absolute; left: 0; right: 0; bottom: 100%; height: .28em; pointer-events: none;
  background: linear-gradient(90deg, #bef264 0 25%, #a3e635 25% 50%, #bef264 50% 75%, #84cc16 75%);
  transform: skewX(-45deg); transform-origin: 0 100%; box-shadow: inset 0 0 0 var(--px) rgba(40, 70, 10, .45); height: .36em; }
/* face de droite, dans l'ombre */
.skin-blocks .slot:not(.collapsed) { box-shadow: inset calc(-1 * var(--px)) calc(-1 * var(--px)) 0 rgba(0, 0, 0, .35), inset var(--px) var(--px) 0 rgba(255, 255, 255, .18), 0 0 0 var(--px) #2a1a0c, .18em -.09em 0 #5b3a1a, .18em -.09em 0 var(--px) #2a1a0c; margin-right: .22em; }
.num-card.skin-blocks { padding-top: .85rem; }

/* --- Nixie : socle épais et reflet de verre sur chaque tube */
.num-card.skin-nixie { box-shadow: inset 0 2px 6px rgba(0, 0, 0, .8), 0 6px 0 #0c0a09, 0 12px 18px rgba(0, 0, 0, .5); }

/* --- Vaporwave : lettres chromées extrudées vers le soleil */

/* --- Diamond : gemme épaisse (tranche facettée) et chiffres qui brillent en relief */
.num-card.skin-diamond { box-shadow: 0 0 0 2px #e0f2fe, 0 0 0 4px rgba(186, 230, 253, .35), 0 6px 0 #334155, 0 0 22px rgba(165, 243, 252, .45), 0 12px 20px rgba(0, 0, 0, .45); }
.skin-diamond .slot { filter: drop-shadow(1px 1px 0 #93c5fd) drop-shadow(1px 1px 0 #6366f1) drop-shadow(0 0 3px rgba(255, 255, 255, .9)) drop-shadow(0 0 10px rgba(165, 243, 252, .6)); }

/* Gold et Diamond : la pièce/gemme oscille sur elle-même au lieu de faire un tour complet (chiffres jamais à l'envers). */
@keyframes gold-coin { 0% { transform: perspective(200px) rotateY(-55deg); filter: brightness(.8); } 50% { transform: perspective(200px) rotateY(0); filter: brightness(1.7); } 100% { transform: perspective(200px) rotateY(55deg); filter: brightness(.8); } }
.skin-gold .slot.spinning { animation: gold-coin .26s ease-in-out infinite alternate; }
@keyframes diamond-spin { 0% { transform: perspective(200px) rotateY(-50deg) scale(.95); } 100% { transform: perspective(200px) rotateY(50deg) scale(1.05); } }
.skin-diamond .slot.spinning { animation: prism-shift .5s linear infinite, diamond-spin .22s ease-in-out infinite alternate; }

/* Dice : assez de hauteur pour que les dés qui roulent (diagonale plus haute que le côté) ne soient pas coupés. */
.num-card.skin-dice { padding-top: .75rem; padding-bottom: .85rem; }

/* ================================================================== mouvement v2 : sobre et « pro » (2026-09-28)
   Une seule signature pour tous les skins : départ proche (≤ .3em), échelle ≤ 1.12, flou ≤ 1.5px, bref éclat de
   lumière à l'impact puis arrêt net ; révélations 380-520 ms ; défilements fins comme un compteur mécanique.
   Chaque skin garde son idée (matière), en plus retenu. Ces règles viennent après toutes les autres : elles priment. */
:root { --ease-out: cubic-bezier(.22, 1, .36, 1); --ease-snap: cubic-bezier(.34, 1.36, .64, 1); --ease-in-out: cubic-bezier(.65, 0, .35, 1); }

/* Classic (et base de tous) : le chiffre descend d'un cran, se pose avec une légère surimpulsion. */
.slot.spinning { animation: m2-reel .11s linear infinite; }
@keyframes m2-reel { 0% { transform: translateY(-.1em); filter: blur(.6px); opacity: .55; } 50% { transform: translateY(.1em); filter: blur(.35px); opacity: .7; } 100% { transform: translateY(-.1em); filter: blur(.6px); opacity: .55; } }
.slot.revealed { animation: m2-lock .42s var(--ease-snap) backwards; }
@keyframes m2-lock { 0% { transform: translateY(-.28em) scale(1.08); opacity: 0; filter: blur(1.2px) brightness(1.5); } 55% { transform: translateY(.03em); opacity: 1; filter: brightness(1.15); } 100% { transform: none; filter: none; } }

/* Neon : un seul raté du tube, puis le néon s'allume et son halo s'épanouit. */
.skin-neon .slot.spinning { animation: m2-neon-hum .16s steps(2) infinite; }
@keyframes m2-neon-hum { 0% { opacity: .35; } 50% { opacity: .55; } }
.skin-neon .slot.revealed { animation: m2-neon-on .5s linear backwards; }
@keyframes m2-neon-on { 0% { opacity: 0; text-shadow: none; } 12% { opacity: .9; } 20% { opacity: .2; text-shadow: none; } 32% { opacity: 1; text-shadow: 0 0 2px #fff, 0 0 18px #ff4fd8, 0 0 40px #ff4fd8; } 100% {} }

/* LCD : les segments éteints restent visibles, le chiffre s'affiche en 3 paliers de contraste (écran lent). */
.skin-lcd .slot.revealed { animation: m2-lcd .3s steps(3, jump-start) backwards; }
@keyframes m2-lcd { 0% { opacity: .2; } 100% { opacity: 1; } }

/* Pixel : pas de flou (c'est du pixel) ; le chiffre tombe de 2 « pixels » en 4 images et rebondit d'un. */
.skin-pixel .slot.spinning { animation: m2-pixel-tick .16s steps(2) infinite; }
@keyframes m2-pixel-tick { 50% { transform: translateY(-.08em); } }
.skin-pixel .slot.revealed { animation: m2-pixel-drop .36s steps(4) backwards; }
@keyframes m2-pixel-drop { 0% { transform: translateY(-.3em); opacity: 0; } 50% { transform: translateY(.06em); opacity: 1; } 75% { transform: translateY(-.03em); } 100% { transform: none; } }

/* Jersey : le numéro thermocollé est pressé sur le maillot (appui, puis relâche). */
.skin-jersey .slot.spinning { animation: m2-cloth .3s var(--ease-in-out) infinite alternate; transform-origin: 50% 0; }
@keyframes m2-cloth { from { transform: skewX(-4deg) scaleY(.97); opacity: .75; } to { transform: skewX(4deg) scaleY(1.01); opacity: .85; } }
.skin-jersey .slot.revealed { animation: m2-press .45s var(--ease-snap) backwards; }
@keyframes m2-press { 0% { transform: scale(1.12); opacity: 0; } 45% { transform: scale(.96); opacity: 1; } 100% { transform: none; } }

/* Slots : le rouleau freine, dépasse d'un cheveu et revient (butée mécanique). */
.skin-slots .slot.revealed { animation: m2-reel-stop .48s var(--ease-snap) backwards; }
@keyframes m2-reel-stop { 0% { transform: translateY(-.3em); filter: blur(1.2px); } 60% { transform: translateY(.05em); filter: none; } 100% { transform: none; } }

/* Scoreboard : les LED s'allument en balayage rapide, gauche → droite. */
.skin-scoreboard .slot.revealed { animation: m2-led .32s steps(5) backwards; }
@keyframes m2-led { from { clip-path: inset(0 100% 0 0); filter: brightness(1.8); } to { clip-path: inset(0); filter: none; } }

/* Dice : le dé roule encore d'un quart de tour et se pose (un seul petit rebond). */
.skin-dice .slot.spinning { animation: m2-dice-roll .26s linear infinite; }
@keyframes m2-dice-roll { 0% { transform: rotate(0); } 25% { transform: rotate(90deg) translateY(-.04em); } 50% { transform: rotate(180deg); } 75% { transform: rotate(270deg) translateY(-.04em); } 100% { transform: rotate(360deg); } }
.skin-dice .slot.revealed { animation: m2-dice-land .5s var(--ease-snap) backwards; }
@keyframes m2-dice-land { 0% { transform: translateY(-.25em) rotate(-24deg); opacity: 0; } 55% { transform: translateY(.03em) rotate(3deg); opacity: 1; } 100% { transform: none; } }

/* Chrome : un reflet de lumière balaie le métal au moment où le chiffre se fige. */
.skin-chrome .slot.revealed { animation: m2-chrome-glint .5s var(--ease-out) backwards, chrome-sheen 4s .5s ease-in-out infinite; }
@keyframes m2-chrome-glint { 0% { transform: translateY(-.2em); opacity: 0; background-position: 100% 0; } 40% { transform: none; opacity: 1; filter: brightness(1.5); } 100% { background-position: 0 0; filter: none; } }

/* Gold : frappe de la pièce — petit écrasement et éclat doré bref. */
.skin-gold .slot.spinning { animation: m2-coin .22s var(--ease-in-out) infinite alternate; }
@keyframes m2-coin { from { transform: perspective(200px) rotateY(-35deg); filter: brightness(.85); } to { transform: perspective(200px) rotateY(35deg); filter: brightness(1.35); } }
.skin-gold .slot.revealed { animation: m2-strike .46s var(--ease-snap) backwards; }
@keyframes m2-strike { 0% { transform: scale(1.12); opacity: 0; } 35% { transform: scale(.97); opacity: 1; filter: brightness(1.9) drop-shadow(0 0 6px #ffe27a); } 100% { transform: none; } }

/* Matrix : le chiffre se décrypte (éclat blanc) puis retombe au vert, sans grossir. */
.skin-matrix .slot.revealed { animation: m2-decode .45s var(--ease-out) backwards; }
@keyframes m2-decode { 0% { color: #fff; text-shadow: 0 0 10px #fff, 0 0 22px #00ff41; transform: scale(1.06); } 50% { color: #caffd5; } 100% { color: #00ff41; transform: none; } }

/* Fire : la flamme monte vite du bas du chiffre (pas de temps mort), puis brûle. */
.skin-fire .slot.spinning { transform-origin: 50% 100%; animation: m2-lick .18s var(--ease-in-out) infinite alternate, fire-flicker .5s linear infinite alternate; }
@keyframes m2-lick { from { transform: scaleY(.96) skewX(-2deg); } to { transform: scaleY(1.05) skewX(2deg); filter: brightness(1.25); } }
.skin-fire .slot.revealed { animation: m2-ignite .38s var(--ease-out) backwards, fire-flicker 1.1s .38s ease-in-out infinite alternate; }
@keyframes m2-ignite { 0% { clip-path: inset(70% 0 0 0); filter: brightness(1.8); transform: translateY(.06em); } 100% { clip-path: inset(0); filter: none; transform: none; } }

/* Galaxy : traînée d'étoile courte, puis le chiffre s'allume avec un halo. */
.skin-galaxy .slot.revealed { animation: m2-star .48s var(--ease-out) backwards; }
@keyframes m2-star { 0% { transform: translate(.25em, -.25em); opacity: 0; text-shadow: -.25em .25em 4px rgba(255, 255, 255, .8); } 55% { opacity: 1; text-shadow: 0 0 10px #fff, 0 0 18px #a78bfa; } 100% { transform: none; } }

/* Rainbow : entrée nette, les couleurs défilent une fois vite puis reprennent leur rythme. */
.skin-rainbow .slot.spinning { animation: rainbow-slide .6s linear infinite, m2-reel .11s linear infinite; }
.skin-rainbow .slot.revealed { animation: m2-lock .42s var(--ease-snap) backwards, rainbow-slide 3s .42s linear infinite; }

/* Candy : gelée — écrasement mesuré, deux rebonds amortis. */
.skin-candy .slot.spinning { animation: m2-jelly .2s var(--ease-in-out) infinite alternate; }
@keyframes m2-jelly { from { transform: scale(1.05, .95); } to { transform: scale(.96, 1.04); } }
.skin-candy .slot.revealed { animation: m2-jelly-pop .52s var(--ease-out) backwards; }
@keyframes m2-jelly-pop { 0% { transform: scale(.6); opacity: 0; } 35% { transform: scale(1.12, .9); opacity: 1; } 60% { transform: scale(.96, 1.05); } 80% { transform: scale(1.02, .98); } 100% { transform: none; } }

/* Ocean : le chiffre remonte à la surface, la réfraction se stabilise. */
.skin-ocean .slot.spinning { animation: m2-sway .5s var(--ease-in-out) infinite alternate; }
@keyframes m2-sway { from { transform: translate(-.03em, .03em); filter: blur(.4px); opacity: .7; } to { transform: translate(.03em, -.03em); filter: blur(.3px); opacity: .85; } }
.skin-ocean .slot.revealed { animation: m2-surface .5s var(--ease-out) backwards; }
@keyframes m2-surface { 0% { transform: translateY(.28em); opacity: 0; filter: blur(1.5px); } 60% { transform: translateY(-.03em); opacity: 1; filter: none; } 100% { transform: none; } }

/* Ice : le givre se forme — net, froid, un éclat bleu-blanc. */
.skin-ice .slot.revealed { animation: m2-freeze .45s var(--ease-out) backwards; }
@keyframes m2-freeze { 0% { transform: scale(1.08); opacity: 0; filter: blur(1.5px) brightness(1.6); } 45% { opacity: 1; filter: brightness(1.3) drop-shadow(0 0 6px #e0f2fe); } 100% { transform: none; } }

/* Circuit : impulsion électrique brève (un seul décalage), éclat cyan. */
.skin-circuit .slot.revealed { animation: m2-zap .4s var(--ease-out) backwards; }
@keyframes m2-zap { 0% { opacity: 0; transform: translateX(-.04em); color: #fff; text-shadow: 0 0 8px #22d3ee, 0 0 18px #22d3ee; } 20% { opacity: 1; transform: translateX(.03em); } 35% { opacity: .5; } 50% { opacity: 1; transform: none; } 100% {} }

/* Nixie : le filament chauffe — orange sombre, un scintillement, puis pleine lueur. */
.skin-nixie .slot.revealed { animation: m2-warm .55s linear backwards; }
@keyframes m2-warm { 0% { color: #7c2d12; text-shadow: none; } 30% { color: #ffb347; text-shadow: 0 0 14px #ff6a00; } 40% { color: #c2410c; text-shadow: 0 0 4px #ff6a00; } 70% { color: #ffd199; } 100% {} }

/* Blocks : le bloc tombe en 4 images et se cale (style pixel, pas de flou). */
.skin-blocks .slot.revealed { animation: m2-block .4s steps(4) backwards; }
@keyframes m2-block { 0% { transform: translateY(-.5em); opacity: 0; } 50% { transform: translateY(.05em); opacity: 1; } 75% { transform: translateY(-.02em); } 100% { transform: none; } }

/* Vaporwave : glissement court avec aberration chromatique qui se referme. */

/* Diamond : la gemme capte la lumière — éclat bref et scintillement, sans tourner. */
.skin-diamond .slot.spinning { animation: prism-shift .5s linear infinite, m2-facet .2s var(--ease-in-out) infinite alternate; }
@keyframes m2-facet { from { transform: perspective(200px) rotateY(-25deg); filter: brightness(.9) drop-shadow(0 0 3px #fff); } to { transform: perspective(200px) rotateY(25deg); filter: brightness(1.3) drop-shadow(0 0 6px #a5f3fc); } }
.skin-diamond .slot.revealed { animation: m2-sparkle .5s var(--ease-snap) backwards, prism-shift 3.5s .5s linear infinite; }
@keyframes m2-sparkle { 0% { transform: scale(1.1); opacity: 0; } 35% { transform: scale(.98); opacity: 1; filter: brightness(2) drop-shadow(0 0 10px #fff); } 100% { transform: none; } }
/* v2, retouche : défilement moins terne (les textes en dégradé perdaient trop à .55 d'opacité). */
@keyframes m2-reel { 0% { transform: translateY(-.1em); filter: blur(.6px); opacity: .72; } 50% { transform: translateY(.1em); filter: blur(.35px); opacity: .88; } 100% { transform: translateY(-.1em); filter: blur(.6px); opacity: .72; } }
@keyframes m2-neon-hum { 0% { opacity: .55; } 50% { opacity: .75; } }

/* ================================================================== interface Candy / Blocks, retouche (2026-09-28) */
/* Candy : bonbons pleins et brillants — plus de double contour blanc ; relief par l'épaisseur (bord foncé dessous),
   reflet discret ; zéros de tête sans reflet. */
.skin-candy .slot { -webkit-text-stroke: 0; font-weight: 400;
  text-shadow: 0 .05em 0 #be185d, 0 .09em 0 rgba(157, 23, 77, .55), 0 .14em .12em rgba(190, 24, 93, .3); }
.skin-candy .slot:nth-child(3n+2) { text-shadow: 0 .05em 0 #0f766e, 0 .09em 0 rgba(17, 94, 89, .55), 0 .14em .12em rgba(15, 118, 110, .3); }
.skin-candy .slot:nth-child(3n) { text-shadow: 0 .05em 0 #7e22ce, 0 .09em 0 rgba(107, 33, 168, .55), 0 .14em .12em rgba(126, 34, 206, .3); }
.skin-candy .slot::after { left: 26%; top: 20%; width: 22%; height: 10%; background: rgba(255, 255, 255, .6); }
.skin-candy .slot.ghost::after, .skin-blocks .slot.ghost::before { display: none; }
/* Cadre Candy : boutique de bonbons — berry profond en sombre, rose poudré en clair, pois discrets. */
.side-candy { --side-border: #f472b6; --side-ink: #f9a8d4; --side-ink-glow: 0 0 6px rgba(244, 114, 182, .6);
  --side-bg: radial-gradient(circle at 20% 30%, rgba(244, 114, 182, .18) 0 3px, transparent 4px) 0 0 / 52px 52px,
    radial-gradient(circle at 70% 75%, rgba(45, 212, 191, .16) 0 2.5px, transparent 3.5px) 0 0 / 52px 52px,
    radial-gradient(120% 90% at 50% 0%, rgba(236, 72, 153, .22), transparent 70%),
    linear-gradient(180deg, rgba(80, 7, 36, .35), rgba(59, 7, 100, .25)); }
.room-side.side-candy .room-name { color: #fbcfe8; }
@media (prefers-color-scheme: light) { :root:not([data-theme="dark"]) .room-side.side-candy .room-name { color: #9d174d; } }
:root[data-theme="light"] .room-side.side-candy .room-name { color: #9d174d; }

/* Blocks : ciel propre (dégradé + deux nuages pixel), plus de lignes horizontales. */
.num-card.skin-blocks {
  background:
    linear-gradient(#fff 0 0) 12% 18% / 22px 6px no-repeat, linear-gradient(#fff 0 0) calc(12% + 6px) calc(18% - 6px) / 10px 6px no-repeat,
    linear-gradient(#fff 0 0) 84% 12% / 18px 5px no-repeat, linear-gradient(#fff 0 0) calc(84% + 4px) calc(12% - 5px) / 8px 5px no-repeat,
    linear-gradient(180deg, #5eb8ff 0%, #9fd8ff 62%, #74c043 62%, #5fa83a 74%, #8b5a2b 74%);
}
