@media (prefers-color-scheme: light) { :root:not([data-theme="dark"]) .room-side.side-blocks .room-name { color: #3f2a14; text-shadow: none; } }
:root[data-theme="light"] .room-side.side-blocks .room-name { color: #3f2a14; text-shadow: none; }
/* retouche : ciel Blocks sans nuages (ils touchaient le dessus des blocs) ; cadre Candy rose poudré en thème clair */
.num-card.skin-blocks { background: linear-gradient(180deg, #5eb8ff 0%, #9fd8ff 62%, #74c043 62%, #5fa83a 74%, #8b5a2b 74%); }
@media (prefers-color-scheme: light) { :root:not([data-theme="dark"]) .side-candy { --side-bg: radial-gradient(circle at 20% 30%, rgba(244, 114, 182, .22) 0 3px, transparent 4px) 0 0 / 52px 52px, radial-gradient(circle at 70% 75%, rgba(45, 212, 191, .2) 0 2.5px, transparent 3.5px) 0 0 / 52px 52px, linear-gradient(180deg, #fff1f7, #fce7f3); } }
