.skin-blocks .slot:not(.collapsed) { margin-right: .18em; }

/* ================================================================== Dice / Circuit / Vaporwave, version détaillée (2026-09-28) */

/* --- Dice : dés de casino en ivoire (arêtes arrondies, ombre interne, deux points discrets en coin),
   tapis de feutre surpiqué dans un rebord en bois ; chaque dé roule à son propre rythme et se pose à son tour. */
.num-card.skin-dice {
  border: 4px solid #6b3410; border-radius: .9rem;
  background:
    repeating-linear-gradient(45deg, rgba(255, 255, 255, .025) 0 2px, transparent 2px 5px),
    radial-gradient(ellipse 80% 90% at 50% 45%, #178a4a, #0e5a33 70%, #0a4427);
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, .06), inset 0 0 0 5px rgba(0, 0, 0, .12), inset 0 0 0 6px rgba(253, 230, 138, .22),
    inset 0 0 26px rgba(0, 0, 0, .5), 0 5px 0 #4a230a, 0 12px 18px rgba(0, 0, 0, .45);
}
.skin-dice .slot {
  color: #1f2937; border-radius: .26em;
  background:
    radial-gradient(circle at 18% 18%, rgba(185, 28, 28, .55) 0 .045em, transparent .06em),
    radial-gradient(circle at 82% 82%, rgba(185, 28, 28, .55) 0 .045em, transparent .06em),
    radial-gradient(ellipse at 35% 25%, #ffffff, #f5f0e6 55%, #e3d9c6);
  box-shadow: inset 0 -.06em .08em rgba(120, 100, 70, .35), inset 0 .05em .05em rgba(255, 255, 255, .9),
    .06em .09em 0 #cbbfa8, .1em .14em 0 #a8997e, 0 .26em .3em rgba(0, 0, 0, .4);
}
.skin-dice .slot:nth-child(2) { animation-delay: -.07s; } .skin-dice .slot:nth-child(3) { animation-delay: -.15s; }
.skin-dice .slot:nth-child(4) { animation-delay: -.04s; } .skin-dice .slot:nth-child(5) { animation-delay: -.19s; }
.skin-dice .slot:nth-child(6) { animation-delay: -.11s; } .skin-dice .slot:nth-child(7) { animation-delay: -.02s; }
.skin-dice .slot.spinning { animation-duration: .3s; }
.skin-dice .slot.spinning:nth-child(2n) { animation-duration: .36s; animation-direction: reverse; }
.skin-dice .slot.revealed { animation-delay: 0s; }
.side-dice { --side-border: #6b3410; --side-glow: inset 0 0 0 2px rgba(253, 230, 138, .12), 0 0 0 1px rgba(107, 52, 16, .5);
  --side-bg: repeating-linear-gradient(45deg, rgba(255, 255, 255, .02) 0 2px, transparent 2px 5px), radial-gradient(ellipse 90% 80% at 50% 40%, rgba(23, 138, 74, .32), rgba(10, 68, 39, .3));
  --deco-a: '♠ ♥'; --deco-b: '♣ ♦'; --side-ink: #fde68a; }
.side-dice::before, .side-dice::after { font-size: .8rem; letter-spacing: .2em; opacity: .55; }

/* --- Circuit : carte électronique — fenêtre d'affichage en verre noir incrustée, pistes cuivrées, composants CMS,
   une impulsion de courant qui court le long de la piste du bas. */
.num-card.skin-circuit {
  border: 2px solid #059669; border-radius: .4rem;
  background:
    /* composants CMS (petits rectangles) */
    linear-gradient(#1f2937 0 0) 6% 22% / 10px 5px no-repeat, linear-gradient(#d6d3d1 0 0) 6% 22% / 3px 5px no-repeat,
    linear-gradient(#1f2937 0 0) 94% 80% / 10px 5px no-repeat, linear-gradient(#d6d3d1 0 0) 94% 80% / 3px 5px no-repeat,
    /* pastilles et pistes */
    radial-gradient(circle at 4% 78%, #fbbf24 0 2px, #92400e 2.5px 3.5px, transparent 4px),
    radial-gradient(circle at 96% 20%, #fbbf24 0 2px, #92400e 2.5px 3.5px, transparent 4px),
    linear-gradient(90deg, transparent 4%, rgba(217, 119, 6, .55) 4% 96%, transparent 96%) 0 88% / 100% 2px no-repeat,
    linear-gradient(90deg, transparent 4%, rgba(217, 119, 6, .45) 4% 96%, transparent 96%) 0 12% / 100% 2px no-repeat,
    repeating-linear-gradient(0deg, rgba(16, 185, 129, .06) 0 1px, transparent 1px 10px),
    repeating-linear-gradient(90deg, rgba(16, 185, 129, .06) 0 1px, transparent 1px 10px),
    linear-gradient(135deg, #065f46, #064e3b 50%, #022c22);
  box-shadow: 0 0 0 2px #022c22, 0 5px 0 #01241b, 0 10px 16px rgba(0, 0, 0, .45), 0 0 14px rgba(16, 185, 129, .25);
}
/* l'impulsion : un point lumineux qui file sur la piste du bas */
.num-card.skin-circuit::before { content: ''; position: absolute; left: -10%; bottom: calc(12% - 3px); width: 18%; height: 6px; pointer-events: none;
  background: radial-gradient(ellipse at 70% 50%, #fef08a, rgba(34, 211, 238, .8) 30%, transparent 70%); filter: blur(1px); animation: m2-current 2.4s linear infinite; }
@keyframes m2-current { from { transform: translateX(0); } to { transform: translateX(650%); } }
.skin-circuit .slot { position: relative; z-index: 1; margin: 0 .01em; padding: 0 .04em;
  background: linear-gradient(180deg, rgba(0, 0, 0, .78), rgba(2, 20, 15, .88));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .08), inset 0 -1px 0 rgba(0, 0, 0, .6);
  color: #a7f3d0; text-shadow: 0 0 3px #34d399, 0 0 9px rgba(16, 185, 129, .8); }
.skin-circuit .slot:first-child { border-radius: .12em 0 0 .12em; } .skin-circuit .slot:last-child { border-radius: 0 .12em .12em 0; }
.room-stage.many .num-card.skin-circuit::before { animation: none; opacity: 0; }

/* --- Vaporwave : coucher de soleil outrun — soleil rayé jaune→rose posé sur l'horizon, étoiles, halo d'horizon,
   grille néon ; chiffres chromés cernés de sombre pour rester lisibles sur le soleil. */
/* retouche : fenêtre Circuit d'un seul tenant ; soleil Vaporwave plus grand et plus doux derrière les chiffres */
.skin-circuit .slot { margin: 0; padding: 0 .05em; box-shadow: none; border-radius: 0; }
.skin-circuit .slot:first-child { border-radius: .14em 0 0 .14em; padding-left: .12em; box-shadow: inset 1px 0 0 rgba(255, 255, 255, .06); }
.skin-circuit .slot:last-child { border-radius: 0 .14em .14em 0; padding-right: .12em; }
/* Chiffres colorés par un dégradé (background-clip: text) : le dégradé ne peint que la case du chiffre, donc tout ce
   qui dépasse (italique, chiffres larges) devenait invisible — le 8 de Vaporwave s'affichait comme un 6.
   On agrandit la case peinte sans changer l'espacement (padding compensé par une marge négative). */
.skin-gold .slot, .skin-chrome .slot, .skin-diamond .slot, .skin-ice .slot, .skin-rainbow .slot, .skin-fire .slot { padding: 0 .06em; margin: 0 -.06em; }
/* Chiffres coupés en haut pendant l'affichage : chemin vertical plus court et un peu plus d'air dans la carte
   (la carte coupe ce qui dépasse, overflow: hidden, pour garder ses reflets et décors à l'intérieur). */
.num-card { padding-top: .7rem; padding-bottom: .7rem; }
.num-card.sm { padding-top: .15rem; padding-bottom: .15rem; }
@keyframes m2-reel { 0% { transform: translateY(-.06em); filter: blur(.6px); opacity: .72; } 50% { transform: translateY(.06em); filter: blur(.35px); opacity: .88; } 100% { transform: translateY(-.06em); filter: blur(.6px); opacity: .72; } }
@keyframes m2-lock { 0% { transform: translateY(-.14em) scale(1.06); opacity: 0; filter: blur(1.2px) brightness(1.5); } 55% { transform: translateY(.02em); opacity: 1; filter: brightness(1.15); } 100% { transform: none; filter: none; } }
@keyframes m2-reel-stop { 0% { transform: translateY(-.16em); filter: blur(1.2px); } 60% { transform: translateY(.03em); filter: none; } 100% { transform: none; } }
@keyframes m2-pixel-drop { 0% { transform: translateY(-.16em); opacity: 0; } 50% { transform: translateY(.04em); opacity: 1; } 75% { transform: translateY(-.02em); } 100% { transform: none; } }
@keyframes m2-dice-land { 0% { transform: translateY(-.14em) rotate(-24deg); opacity: 0; } 55% { transform: translateY(.02em) rotate(3deg); opacity: 1; } 100% { transform: none; } }
@keyframes m2-chrome-glint { 0% { transform: translateY(-.12em); opacity: 0; background-position: 100% 0; } 40% { transform: none; opacity: 1; filter: brightness(1.5); } 100% { background-position: 0 0; filter: none; } }
@keyframes m2-surface { 0% { transform: translateY(.14em); opacity: 0; filter: blur(1.5px); } 60% { transform: translateY(-.02em); opacity: 1; filter: none; } 100% { transform: none; } }
@keyframes m2-star { 0% { transform: translate(.18em, -.14em); opacity: 0; text-shadow: -.2em .2em 4px rgba(255, 255, 255, .8); } 55% { opacity: 1; text-shadow: 0 0 10px #fff, 0 0 18px #a78bfa; } 100% { transform: none; } }
@keyframes m2-block { 0% { transform: translateY(-.25em); opacity: 0; } 50% { transform: translateY(.04em); opacity: 1; } 75% { transform: translateY(-.02em); } 100% { transform: none; } }

/* ================================================================== trailer (2026-10-02)
   Bouton discret sur l'accueil, affiche cliquable sur la page d'explication, vidéo dans une fenêtre large. */
.trailer-btn { margin-top: .5rem; color: var(--prose-3); }
.trailer-btn:hover { color: var(--prose); }
/* La fenêtre prend la largeur qui fait tenir la vidéo entière dans l'écran (pas de bandes noires, pas de défilement).
   Hauteur laissée à la vidéo : l'écran, moins les marges du fond (2 × 4vh), moins l'habillage de la fenêtre (2,4 + 0,7 rem et ses bordures). */
.modal.wide { --video-h: calc(92vh - 3.3rem); width: min(100%, 60rem, calc(var(--video-h) * 16 / 9 + 1.5rem)); padding: 2.4rem .7rem .7rem; }
.modal.wide.tall { width: min(100%, calc(var(--video-h) * 9 / 16 + 1.5rem)); }
.trailer-video { display: block; width: 100%; height: auto; aspect-ratio: 16 / 9; border-radius: .5rem; background: #000; outline: none; }
.trailer-video.tall { aspect-ratio: 9 / 16; }
.trailer-thumb { position: relative; display: block; width: 100%; margin: 1rem 0 1.4rem; padding: 0; border: 1px solid var(--outline); border-radius: .7rem; overflow: hidden; background: #000; cursor: pointer; }
.trailer-thumb img { display: block; width: 100%; height: auto; transition: transform .35s var(--ease-out), filter .35s ease; }
.trailer-thumb:hover img { transform: scale(1.02); filter: brightness(1.08); }
.trailer-play { position: absolute; left: 50%; bottom: 1rem; transform: translateX(-50%); display: inline-flex; align-items: center; gap: .45rem; padding: .55rem 1rem; border-radius: 999px;
  background: rgba(10, 10, 10, .78); border: 1px solid rgba(255, 255, 255, .25); color: #fff; font-size: .78rem; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; white-space: nowrap; }

/* ================================================================== séquences des skins (js/skinfx.js, 2026-10-02)
   Pendant un tirage : un canvas dans la carte, derrière les chiffres, et un autour d'elle, par-dessus. */
.skin-fx-in { position: absolute; inset: 0; width: 100%; height: 100%; z-index: 0; border-radius: inherit; pointer-events: none; }
.num-card.has-fx .slot { position: relative; z-index: 1; }
.num-card.has-fx::after { z-index: 2; }
.skin-fx-out { position: absolute; z-index: 3; pointer-events: none; }
/* Fire : les chiffres passent devant de vraies flammes, un liseré sombre les garde lisibles. */
.skin-fire.has-fx .slot { filter: drop-shadow(0 0 2px rgba(24, 6, 0, .95)) drop-shadow(0 1px 1px rgba(24, 6, 0, .8)); }

/* ================================================================== skins à matière, plus beaux (2026-10-02)
