.skin-blocks .slot::before { display: none; }
.skin-blocks .slot { font-size: .5em; color: #fffbe6; text-shadow: .11em .11em 0 #2b1a08, -.06em 0 0 #2b1a08, 0 -.06em 0 #2b1a08, .06em 0 0 #2b1a08; }
.skin-blocks .slot::after { inset: 25% 25% 0 0; }
.skin-blocks .slot.ghost { opacity: .28; }
.skin-blocks .slot.collapsed { padding: 0; opacity: 0; filter: none; }

/* Dons : l'adresse du portefeuille, entière et copiable. */
.tip-wallet { display: flex; align-items: center; gap: .5rem; }
.tip-wallet code { flex: 1; min-width: 0; padding: .5rem .6rem; border: 1px solid var(--outline); border-radius: .45rem; background: var(--surface-dim); font-family: var(--font-mono); font-size: .68rem; overflow-wrap: anywhere; user-select: all; }

/* Bouton de don : le pendant du bouton GitHub, en bas à droite. */
.gh-corner.coffee-corner { left: auto; right: 14px; font-size: 1.05rem; line-height: 1; cursor: pointer; }

/* ================================================================== le rubis du créateur (2026-10-02)
   Réservé au compte Owner, à la place de son skin : une carte en verre grenat marbré, des chiffres taillés dans le rubis
   (du rose pâle au bordeaux, avec un reflet qui glisse), comme les finitions Ruby des skins de CS. */
.num-card.owner-ruby {
  border: 2px solid #e11d48; border-radius: .8rem; color: #ff4d6d;
  background:
    radial-gradient(ellipse 60% 80% at 22% 20%, rgba(255, 77, 109, .35), transparent 60%),
    radial-gradient(ellipse 50% 70% at 82% 85%, rgba(159, 18, 57, .65), transparent 62%),
    radial-gradient(ellipse 40% 50% at 60% 30%, rgba(255, 180, 195, .14), transparent 60%),
    linear-gradient(135deg, #2a0410, #4c0519 45%, #1c0209);
  box-shadow: 0 0 0 1px rgba(255, 228, 233, .25) inset, 0 0 22px rgba(225, 29, 72, .6), 0 0 46px rgba(159, 18, 57, .35), 0 10px 20px rgba(0, 0, 0, .5), inset 0 10px 18px rgba(255, 120, 150, .14), inset 0 -12px 18px rgba(0, 0, 0, .45);
}
.owner-ruby .slot {
  font-weight: 800; color: transparent; -webkit-background-clip: text; background-clip: text;
  background-image: linear-gradient(115deg, transparent 40%, rgba(255, 255, 255, .85) 50%, transparent 60%), linear-gradient(165deg, #ffe4e9 0%, #ff8fa3 14%, #ff2d55 34%, #c1121f 56%, #7f0f2c 76%, #ff5c7a 100%);
  background-size: 300% 100%, 100% 100%; background-position: 150% 0, 0 0;
  filter: drop-shadow(0 1px 0 #3b0613) drop-shadow(0 0 6px rgba(255, 45, 85, .75)) drop-shadow(0 0 16px rgba(225, 29, 72, .45));
  animation: ruby-shine 3.6s ease-in-out infinite; padding: 0 .05em; margin: 0 -.05em;
}
.owner-ruby .slot:nth-child(2n) { animation-delay: -.5s; }
@keyframes ruby-shine { 0%, 55% { background-position: 150% 0, 0 0; } 100% { background-position: -150% 0, 0 0; } }
.owner-ruby .slot.spinning { opacity: .8; animation: ruby-shine 3.6s ease-in-out infinite, m2-reel .11s linear infinite; }
.owner-ruby .slot.ghost { opacity: .22; }
.num-card.owner-ruby.neutral, .num-card.owner-ruby[data-tier] { --t-border: #e11d48; }
@media (prefers-reduced-motion: reduce) { .owner-ruby .slot { animation: none; } }
/* Rubis : fond plus sombre et chiffres plus clairs, pour qu'ils se lisent d'un coup d'œil. */
.num-card.owner-ruby { background: radial-gradient(ellipse 60% 80% at 20% 15%, rgba(255, 77, 109, .2), transparent 60%), radial-gradient(ellipse 50% 70% at 85% 90%, rgba(159, 18, 57, .4), transparent 62%), linear-gradient(135deg, #17020a, #2b0410 50%, #0e0105); }
.owner-ruby .slot { -webkit-text-stroke: .6px rgba(255, 214, 222, .7);
  background-image: linear-gradient(115deg, transparent 40%, rgba(255, 255, 255, .9) 50%, transparent 60%), linear-gradient(170deg, #fff0f3 0%, #ff9db0 16%, #ff3b63 40%, #e11d48 62%, #a30f33 82%, #ff6b8a 100%);
  filter: drop-shadow(0 1px 0 #2b0410) drop-shadow(0 0 5px rgba(255, 45, 85, .8)) drop-shadow(0 0 14px rgba(225, 29, 72, .4)); }
.owner-ruby .skin-fx-in { opacity: .45; }

/* Duel : demande d'entrée en cours de partie, côté hôte. */
.room-ask { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: .5rem; margin-top: .7rem; padding: .5rem .7rem; border: 1px solid var(--outline); border-radius: .6rem; background: var(--surface-dim); font-size: .8rem; }

/* ================================================================== quêtes, caisses, amis (2026-10-06) */
.quests-card { width: min(100%, 26rem); margin: 1.2rem auto 0; padding: .9rem 1rem; border: 1px solid var(--outline); border-radius: .8rem; background: var(--surface); text-align: left; }
.quests-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: .5rem; }
.quest { display: flex; align-items: center; gap: .7rem; padding: .55rem 0; border-top: 1px solid var(--outline); }
.quest.done { opacity: .55; }
.quest-emoji { font-size: 1.15rem; width: 1.6rem; text-align: center; }
.quest-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: .2rem; font-size: .84rem; }
.quest-bar { display: block; height: .4rem; border-radius: 999px; background: var(--surface-raised); overflow: hidden; }
.quest-bar > span { display: block; height: 100%; border-radius: 999px; background: linear-gradient(90deg, #10b981, #3b82f6); transition: width .6s var(--ease-out); }
.quest-reward { font-size: .78rem; color: var(--ep-text); white-space: nowrap; }
.quest-state { font-size: .72rem; font-weight: 700; color: var(--success); white-space: nowrap; }
.quests-foot { margin: .5rem 0 0; text-align: center; }
.quest .btn-roll.small { white-space: nowrap; }

.case-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(13rem, 1fr)); gap: .8rem; }
.case-tile { display: flex; flex-direction: column; align-items: center; gap: .45rem; padding: 1rem .8rem; border: 1px solid var(--outline); border-radius: .8rem; background: var(--surface-dim); text-align: center; }
.case-box { font-size: 2.6rem; line-height: 1; filter: drop-shadow(0 6px 8px rgba(0, 0, 0, .35)); transition: transform .25s var(--ease-snap); }
.case-tile:hover .case-box { transform: translateY(-4px) rotate(-6deg) scale(1.06); }
.case-odds { font-size: .7rem; color: var(--prose-3); cursor: help; text-decoration: underline dotted; }
.case-reel { position: relative; overflow: hidden; margin: 1rem 0; padding: .6rem 0; border: 1px solid var(--outline); border-radius: .7rem; background: var(--surface-dim);
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent); mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent); }
.case-strip { display: flex; gap: .5rem; width: max-content; will-change: transform; }
.case-cell { display: flex; flex-direction: column; align-items: center; gap: .3rem; width: 6.2rem; padding: .5rem .3rem; border: 1px solid var(--outline); border-radius: .6rem; background: var(--surface); font-size: .66rem; font-weight: 700; white-space: nowrap; transition: transform .3s var(--ease-snap), box-shadow .3s, border-color .3s; }
.case-cell .num-card.sm { min-width: 0; }
.case-cell.won { transform: scale(1.08); border-color: var(--ep-outline); box-shadow: 0 0 0 2px var(--ep-outline), 0 0 18px rgba(245, 158, 11, .45); }
.case-marker { position: absolute; left: 50%; top: 0; bottom: 0; width: 2px; margin-left: -1px; background: var(--ep-text); z-index: 2; box-shadow: 0 0 8px var(--ep-text); }
.case-result { text-align: center; animation: m2-lock .42s var(--ease-snap) backwards; }
.case-result p { margin: .7rem 0; }

.friend-row { display: flex; align-items: center; gap: .7rem; padding: .6rem 0; border-top: 1px solid var(--outline); }
.friend-row:first-of-type { border-top: 0; }
.friend-info { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: .1rem; }
.friend-row > .player-link { flex: 1; }
.friend-actions { display: flex; gap: .4rem; align-items: center; }
.add-friend { font-size: .7rem; vertical-align: middle; margin-left: .5rem; }
@media (max-width: 560px) { .nav a span { display: none; } }
.friend-actions a, .friend-row a.btn-roll { text-decoration: none; }
/* Pièces offertes à un ami (2026-10-13) : fenêtre « Give coins » ; sur téléphone, le bouton ne garde que 🎁. */
.gift-presets { margin-bottom: .6rem; }
.gift-presets .chip:disabled { opacity: .4; cursor: not-allowed; }
.gift-left { margin: .5rem 0 0; }
@media (max-width: 560px) { .friend-actions .gift-label { display: none; } }
.case-cell { justify-content: flex-end; min-height: 5.2rem; }
.case-cell .num-card.sm { font-size: .8rem; max-width: 5.4rem; }

/* ================================================================== création de duel en questions (2026-10-07) */
.duel-layout { display: grid; grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr); gap: 1rem; align-items: start; }
@media (max-width: 760px) { .duel-layout { grid-template-columns: 1fr; } }
.setup-step { padding: .85rem 0; border-top: 1px solid var(--outline); }
.setup-step:first-child { border-top: 0; padding-top: .2rem; }
.setup-q { font-size: .8rem; font-weight: 800; letter-spacing: .02em; margin-bottom: .55rem; }
.setup-q .panel-note { font-weight: 500; margin-left: .3rem; }
.choice-row { display: grid; grid-template-columns: 1fr 1fr; gap: .5rem; }
@media (max-width: 420px) { .choice-row { grid-template-columns: 1fr; } }
.choice { display: flex; align-items: center; gap: .6rem; padding: .6rem .7rem; text-align: left; border: 1.5px solid var(--outline-mid); border-radius: .6rem; background: var(--surface); color: var(--prose-2); transition: border-color .15s, background .15s, transform .12s var(--ease-snap); }
.choice:hover { border-color: var(--outline-strong); transform: translateY(-1px); }
.choice.on { border-color: var(--prose); background: var(--surface-raised); color: var(--prose); box-shadow: inset 0 0 0 1px var(--prose); }
.choice-emoji { font-size: 1.25rem; line-height: 1; }
.choice-text { display: flex; flex-direction: column; min-width: 0; }
.choice-text b { font-size: .82rem; }
.choice-text span { font-size: .7rem; color: var(--prose-3); }
.setup-line { display: flex; align-items: center; gap: .6rem; flex-wrap: wrap; margin-top: .55rem; }
.setup-step > .setup-line:first-of-type:not(:only-of-type) { margin-top: .55rem; }
.stepper { display: inline-flex; align-items: center; border: 1.5px solid var(--outline-mid); border-radius: .6rem; overflow: hidden; }
.stepper button { width: 2.2rem; height: 2.2rem; border: 0; background: var(--surface); color: var(--prose); font-size: 1.1rem; font-weight: 700; }
.stepper button:hover:not(:disabled) { background: var(--surface-raised); }
.stepper button:disabled { opacity: .3; cursor: default; }
.stepper b { min-width: 2.4rem; text-align: center; font-size: 1rem; }
.chips-row { display: flex; flex-wrap: wrap; gap: .4rem; }
.chip { padding: .4rem .7rem; border: 1.5px solid var(--outline-mid); border-radius: 999px; background: var(--surface); color: var(--prose-2); font-size: .74rem; font-weight: 700; white-space: nowrap; }
.chip:hover { border-color: var(--outline-strong); }
.chip.on { border-color: var(--prose); background: var(--prose); color: var(--site-bg); }
.setup-help { margin: .5rem 0 0; }
.setup-summary { display: flex; align-items: center; justify-content: space-between; gap: .8rem; flex-wrap: wrap; margin-top: .4rem; padding: .8rem .9rem; border-radius: .7rem; background: var(--surface-dim); border: 1px solid var(--outline); font-size: .8rem; font-weight: 600; }

/* Choix de la langue (FR / EN), à côté du thème. */
.lang-switch { display: inline-flex; align-items: center; gap: .15rem; font-size: .66rem; font-weight: 800; letter-spacing: .04em; color: var(--prose-3); }
.lang-switch button { border: 0; background: none; padding: .3rem .2rem; color: var(--prose-3); font: inherit; }
.lang-switch button:hover { color: var(--prose); }
.lang-switch button[aria-pressed="true"] { color: var(--prose); text-decoration: underline; text-underline-offset: 3px; text-decoration-thickness: 2px; }

/* ================================================================== ouverture de caisse, version « caisses de FPS » (2026-10-07)
   Bande large qui file puis ralentit longuement, repère jaune qui tique à chaque skin, couleur de rareté sous chaque
   skin, puis révélation dans la couleur de la rareté gagnée. */
.modal:has(.case-open) { width: min(94vw, 54rem); max-width: none; }
.case-open h2 { margin-bottom: .2rem; }
.case-reel { position: relative; overflow: hidden; margin: 1rem 0 .6rem; padding: .9rem 0; border: 1px solid var(--outline); border-radius: .5rem;
  background: linear-gradient(180deg, #0b0d12, #151922);
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 9%, #000 91%, transparent); mask-image: linear-gradient(90deg, transparent, #000 9%, #000 91%, transparent); }
.case-strip { display: flex; gap: .4rem; width: max-content; will-change: transform; }
.case-cell { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: flex-end; gap: .35rem; width: 7.4rem; min-height: 6.4rem; padding: .6rem .3rem .55rem;
  border: 0; border-radius: .3rem; font-size: .68rem; font-weight: 700; color: #e5e7eb; white-space: nowrap;
  background: linear-gradient(180deg, #2a2f3a 0%, #1b1f28 55%, color-mix(in srgb, var(--rar) 55%, #1b1f28) 100%);
  box-shadow: inset 0 -4px 0 var(--rar), inset 0 0 0 1px rgba(255, 255, 255, .05); transition: opacity .5s, filter .5s, transform .45s var(--ease-snap), box-shadow .45s; }
.case-cell .num-card.sm { font-size: .82rem; max-width: 6.6rem; min-width: 0; }
.case-marker { position: absolute; left: 50%; top: 0; bottom: 0; width: 3px; margin-left: -1.5px; z-index: 2; background: #facc15; box-shadow: 0 0 10px #facc15, 0 0 22px rgba(250, 204, 21, .6); transform-origin: 50% 50%; }
.case-marker::before, .case-marker::after { content: ''; position: absolute; left: 50%; margin-left: -7px; border: 7px solid transparent; }
.case-marker::before { top: 0; border-top-color: #facc15; }
.case-marker::after { bottom: 0; border-bottom-color: #facc15; }
.case-marker.tick { animation: case-tick .09s ease-out; }
@keyframes case-tick { 0% { transform: scaleX(2.4); filter: brightness(1.8); } 100% { transform: none; filter: none; } }
/* À l'arrêt : tout s'efface autour du skin gagné, qui s'allume dans sa couleur. */
.case-reel.stopped .case-cell:not(.won) { opacity: .28; filter: saturate(.4); }
.case-cell.won { transform: scale(1.07); z-index: 1; box-shadow: inset 0 -4px 0 var(--rar), 0 0 0 2px var(--rar), 0 0 26px var(--rar); animation: case-won 1.1s ease-in-out infinite alternate; }
@keyframes case-won { to { box-shadow: inset 0 -4px 0 var(--rar), 0 0 0 2px var(--rar), 0 0 44px var(--rar); } }
.case-result { position: relative; text-align: center; padding: .9rem 0 .2rem; animation: case-reveal .5s var(--ease-snap) backwards; isolation: isolate; }
@keyframes case-reveal { 0% { opacity: 0; transform: translateY(.6rem) scale(.92); } 60% { opacity: 1; } 100% { transform: none; } }
.case-glow { position: absolute; left: 50%; top: 2.6rem; width: 22rem; height: 9rem; margin-left: -11rem; z-index: -1; pointer-events: none;
  background: radial-gradient(ellipse, color-mix(in srgb, var(--rar) 55%, transparent), transparent 68%); filter: blur(6px); animation: case-pulse 1.6s ease-in-out infinite alternate; }
@keyframes case-pulse { from { opacity: .55; transform: scale(.94); } to { opacity: 1; transform: scale(1.06); } }
.case-rarity { display: inline-block; margin-bottom: .6rem; padding: .15rem .7rem; border-radius: 999px; font-size: .66rem; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; color: #fff; background: var(--rar); box-shadow: 0 0 14px var(--rar); }
.case-result p { margin: .8rem 0; }
.case-contents { display: flex; gap: 3px; justify-content: center; flex-wrap: wrap; max-width: 9rem; }
.case-contents i { width: 12px; height: 5px; border-radius: 2px; background: var(--rar); }
@media (max-width: 560px) { .case-cell { width: 6rem; min-height: 5.6rem; } }
/* Caisse de fonds d'écran : des mini-aperçus de fonds dans la bande, un plus grand au résultat. */
.wall-preview.case-wall { width: 100%; height: 4.3rem; margin: 0; align-self: stretch; }
.wall-preview.case-wall.md { width: min(20rem, 100%); height: 9rem; margin: 0 auto; box-shadow: 0 0 0 2px var(--rar), 0 0 28px color-mix(in srgb, var(--rar) 60%, transparent); }
/* Caisse de boutons (idée de shadow2, 2026-10-27) : un vrai bouton Generate en miniature dans chaque case de la bande,
   inerte (aucun survol ni clic), et en taille normale au résultat. */
.case-btn { display: grid; place-items: center; align-self: stretch; min-height: 3.6rem; pointer-events: none; }
.case-btn .btn-roll { display: inline-block; font-size: .6rem; padding: .45rem .75rem; letter-spacing: .08em; white-space: nowrap; }
.case-btn.md { min-height: 5.5rem; }
.case-btn.md .btn-roll { font-size: 1.05rem; padding: .7rem 1.8rem; }
.case-rarity { display: block; width: max-content; margin: 0 auto .7rem; }
.room-noreward { max-width: 30rem; margin: .2rem auto .6rem; text-align: center; }

/* ================================================================== suggestions, page Owner, accueil (2026-10-07) */
.gh-corner.idea-corner { bottom: 60px; font-size: 1rem; }
.idea-text { width: 100%; min-height: 6.5rem; resize: vertical; font: inherit; font-size: .9rem; line-height: 1.45; padding: .7rem .8rem; text-transform: none; letter-spacing: 0; text-align: left; }
.idea-foot { display: flex; justify-content: space-between; align-items: center; margin: .5rem 0 .4rem; }
.idea-row { padding: .7rem 0; border-top: 1px solid var(--outline); }
.idea-head { display: flex; align-items: center; gap: .6rem; flex-wrap: wrap; }
.idea-body { margin: .35rem 0 0; font-size: .86rem; line-height: 1.45; white-space: pre-wrap; overflow-wrap: anywhere; }
.idea-status { padding: .1rem .5rem; border-radius: 999px; font-size: .62rem; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; border: 1px solid var(--outline-mid); color: var(--prose-2); }
.idea-status[data-status="seen"] { border-color: #3b82f6; color: #3b82f6; }
.idea-status[data-status="planned"] { border-color: #a855f7; color: #a855f7; }
.idea-status[data-status="done"] { border-color: var(--success); color: var(--success); }
.idea-status[data-status="declined"] { opacity: .6; }
.idea-reply { margin: .45rem 0 0; padding: .5rem .7rem; border-left: 3px solid var(--ep-outline); border-radius: 0 .4rem .4rem 0; background: var(--surface-dim); font-size: .82rem; }
.idea-reply b { display: block; font-size: .64rem; letter-spacing: .06em; text-transform: uppercase; color: var(--ep-text); margin-bottom: .15rem; }
.o-bar { display: grid; grid-template-columns: minmax(0, 11rem) 1fr auto; align-items: center; gap: .6rem; padding: .28rem 0; font-size: .8rem; }
.o-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.o-track { height: .45rem; border-radius: 999px; background: var(--surface-raised); overflow: hidden; }
.o-track > span { display: block; height: 100%; border-radius: 999px; background: linear-gradient(90deg, #3b82f6, #a855f7); }
.o-table { font-size: .78rem; font-family: var(--font-mono); overflow-x: auto; }
.o-tr { display: grid; grid-template-columns: 7rem repeat(5, minmax(3.5rem, 1fr)); gap: .4rem; padding: .3rem 0; border-top: 1px solid var(--outline); text-align: right; }
.o-tr span:first-child { text-align: left; }
.o-tr.head { border-top: 0; font-family: inherit; font-size: .64rem; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; color: var(--prose-3); }
.o-status { width: auto; padding: .25rem .4rem; font-size: .72rem; margin-left: auto; text-transform: none; letter-spacing: 0; }
.o-reply { display: flex; gap: .4rem; margin-top: .5rem; }
.o-reply .input { flex: 1; min-width: 0; font-size: .8rem; text-transform: none; letter-spacing: 0; text-align: left; }

.intro { text-align: center; padding: .3rem .2rem 0; }
.intro-visual { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: .6rem; min-height: 9.5rem; margin: .4rem 0 1rem; padding: 1.1rem .8rem; border-radius: .8rem; background: radial-gradient(ellipse at 50% 0%, var(--surface-raised), var(--surface-dim)); border: 1px solid var(--outline); }
.intro-vs { display: flex; align-items: center; justify-content: center; gap: .7rem; flex-wrap: wrap; }
.intro-vs b { font-size: .8rem; letter-spacing: .1em; color: var(--prose-3); }
.intro-vs .num-card.sm { font-size: 1.25rem; padding: .3rem .7rem; }
.intro h2 { margin: 0 0 .5rem; }
.intro-text { margin: 0 auto; max-width: 27rem; font-size: .9rem; line-height: 1.55; color: var(--prose-2); min-height: 5.6rem; }
.intro-dots { display: flex; justify-content: center; gap: .4rem; margin: .9rem 0; }
.intro-dots i { width: .45rem; height: .45rem; border-radius: 50%; background: var(--outline-strong); transition: width .25s var(--ease-out), background .25s; }
.intro-dots i.on { width: 1.3rem; border-radius: 999px; background: var(--prose); }
.intro-buttons { display: flex; justify-content: center; align-items: center; gap: .5rem; flex-wrap: wrap; }

/* En-tête : 7 onglets, c'est large. On retire dans l'ordre ce qui se règle aussi dans « Player & settings »
   (le thème), puis les libellés des onglets, pour que rien ne se chevauche entre 720 et 1180 px. */
@media (max-width: 1280px) { .theme-switch { display: none; } .player-btn { max-width: 8rem; } }
@media (max-width: 1110px) { .nav a span { display: none; } .nav { margin-left: .2rem; } }

/* Téléphone : 7 onglets + langue + joueur doivent tenir sur 360 px de large ; en dessous, les onglets défilent
   plutôt que de pousser la page de côté. */
@media (max-width: 560px) {
  .topbar { padding: .5rem .6rem; gap: .3rem; }
  .topbar-left { flex: 1; gap: .3rem; }
  .topbar-right { gap: .3rem; flex: none; }
  .nav { margin-left: 0; gap: 0; min-width: 0; overflow-x: auto; scrollbar-width: none; }
  .nav::-webkit-scrollbar { display: none; }
  .nav a { padding: .42rem .26rem; flex: none; }
  .player-btn { padding: 0 .5rem; }
  .player-btn span { display: none; }
  .lang-switch { gap: .05rem; }
  .lang-switch button { padding: .3rem .12rem; }
}

/* Boutique sur téléphone : deux colonnes égales qui ne s'élargissent plus avec leur contenu (les cartes larges
   poussaient la page de côté). */
@media (max-width: 560px) {
  .skin-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .skin-tile { min-width: 0; padding-inline: .35rem; }
}
@media (max-width: 380px) { .skin-tile > .num-card, .skin-tile > .lever-wrap { zoom: .9; } }
@media (max-width: 340px) { .skin-tile > .num-card, .skin-tile > .lever-wrap { zoom: .76; } }

/* ------------------------------------------------------------------ chat du duel */
.chat-panel { margin-top: 1rem; }
.chat-list { display: flex; flex-direction: column; gap: .3rem; max-height: 12.5rem; min-height: 3.2rem; overflow-y: auto; overscroll-behavior: contain; padding: .2rem .1rem .3rem; scrollbar-width: thin; }
.chat-list .empty { padding: .9rem 0; }
.chat-msg { display: flex; align-items: baseline; gap: .5rem; font-size: .84rem; line-height: 1.35; animation: chat-in .22s var(--ease-out) backwards; }
.chat-name { flex: none; max-width: 9rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: .72rem; font-weight: 800; letter-spacing: .02em; text-transform: uppercase; color: var(--prose-2); }
.chat-msg.mine .chat-name { color: var(--ep-text, var(--prose)); }
.chat-text { min-width: 0; overflow-wrap: anywhere; }
.chat-hide, .chat-show { flex: none; margin-left: auto; border: 0; background: none; padding: 0 .2rem; font: inherit; font-size: .64rem; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: var(--prose-3); cursor: pointer; }
.chat-hide { opacity: 0; transition: opacity .15s ease; }
.chat-msg:hover .chat-hide, .chat-hide:focus-visible { opacity: 1; }
.chat-hide:hover, .chat-show:hover { color: var(--prose); }
.chat-show { margin-left: 0; text-decoration: underline; text-underline-offset: 2px; }
.chat-hidden:empty { display: none; }
.chat-hidden { margin: .3rem 0 0; }
.chat-form { display: flex; gap: .5rem; margin-top: .55rem; }
.chat-form .input { flex: 1; min-width: 0; }
@keyframes chat-in { from { opacity: 0; transform: translateY(4px); } }
@media (hover: none) { .chat-hide { opacity: .7; } }

/* Tirage fait hors ligne : gardé dans l'historique, non compté. */
.offline-tag { font-size: .58rem; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; color: var(--prose-3); border: 1px dashed var(--outline-strong); border-radius: 999px; padding: .05rem .4rem; }

/* ------------------------------------------------------------------ 🌴 Vaporwave — refonte du 2026-10-07
   Un coucher de soleil synthwave, net : un grand soleil rayé posé sur l'horizon derrière les chiffres (::before), un
   ciel en dégradé lisse, un sol quadrillé en perspective, des chiffres chromés barrés par la ligne d'horizon.
   Peu d'éléments, tous grands : l'ancienne version empilait un petit soleil, des étoiles et des glitchs. */
.num-card.skin-vaporwave {
  border: 2px solid #f0abfc; border-radius: .55rem; color: #fff;
  background:
    linear-gradient(180deg, #170a3a 0%, #4c1d95 40%, #c026d3 72%, #fb7185 90%, #fdba74 100%) 0 0 / 100% 66% no-repeat,
    linear-gradient(180deg, transparent 0 65.4%, #fff 65.4% 66.6%, rgba(240, 171, 252, .7) 66.6% 68.5%, transparent 71%),
    linear-gradient(180deg, transparent 0 73%, rgba(34, 211, 238, .55) 73% 74.2%, transparent 74.2% 82%, rgba(34, 211, 238, .55) 82% 83.6%, transparent 83.6% 93.4%, rgba(34, 211, 238, .55) 93.4% 95.4%, transparent 95.4%),
    repeating-conic-gradient(from 94deg at 50% 66%, transparent 0 8deg, rgba(34, 211, 238, .5) 8deg 8.8deg),
    linear-gradient(180deg, #1a0638, #0d0221);
  box-shadow: 0 0 0 1px #2e1065, 0 0 0 3px rgba(34, 211, 238, .3), 0 .16em 0 #3b0764, 0 0 22px rgba(232, 121, 249, .45), 0 12px 20px rgba(0, 0, 0, .5);
}
/* Le soleil : un disque dont on ne garde que la moitié du haut, fendu de trois bandes près de l'horizon. */
.num-card.skin-vaporwave::before {
  content: ''; position: absolute; left: 50%; top: 66%; width: 1.36em; height: 1.36em; margin: -.68em 0 0 -.68em; border-radius: 50%; pointer-events: none;
  background:
    linear-gradient(180deg, transparent 0 27%, #3b0f66 27% 29.5%, transparent 29.5% 35%, #3b0f66 35% 38.5%, transparent 38.5% 43.5%, #3b0f66 43.5% 48%, transparent 48%),
    linear-gradient(180deg, #fff59d 0%, #fde047 14%, #fb923c 32%, #f43f5e 50%);
  clip-path: inset(0 0 50% 0);
  filter: drop-shadow(0 0 .18em rgba(251, 146, 60, .7));
}
.skin-vaporwave .slot {
  /* Italique : la zone remplie (padding) déborde de chaque côté pour couvrir les jambages penchés, sinon le chiffre perdait
     un morceau ; un peu plus large pour que le 4 et le 1 ne se chevauchent plus (signalé par A Dude, 2026-10-18). */
  position: relative; z-index: 1; width: .8em; padding: 0 .1em; margin: 0 -.03em; font-size: .86em;
  font-family: var(--font-sans); font-weight: 800; font-style: italic; font-variant-numeric: tabular-nums;
  background: linear-gradient(180deg, #ffffff 0%, #a5f3fc 22%, #e0f7ff 40%, #ffffff 46%, #312e81 49.5%, #f5d0fe 55%, #f472b6 76%, #fdba74 100%) 0 50% / 100% 170%;
  -webkit-background-clip: text; background-clip: text; color: transparent;
  -webkit-text-stroke: .02em rgba(23, 10, 58, .92); paint-order: stroke fill;
  filter: drop-shadow(0 .05em 0 #2e1065) drop-shadow(0 0 .16em rgba(34, 211, 238, .55));
}
.skin-vaporwave .slot.ghost { opacity: .32; }
/* En route : le chiffre tangue doucement et la ligne d'horizon glisse dans son chrome (rien ne saccade). */
.skin-vaporwave .slot.spinning { opacity: .95; animation: vw-cruise .3s var(--ease-in-out) infinite alternate; }
@keyframes vw-cruise {
  from { transform: translateY(.05em) skewX(-7deg) scale(.96); background-position: 0 8%; }
  to { transform: translateY(-.05em) skewX(5deg) scale(1.03); background-position: 0 92%; }
}
/* Il arrive de l'horizon : petit et blanc, il grossit d'un coup, puis un trait de laser passe sous lui. */
.skin-vaporwave .slot.revealed { animation: vw-arrive .46s var(--ease-out) backwards; }
@keyframes vw-arrive {
  0% { transform: translateY(.1em) scale(.42); filter: brightness(3.2) saturate(.3) drop-shadow(0 0 .3em #fff); }
  45% { transform: translateY(-.03em) scale(1.12) skewX(-3deg); filter: brightness(1.7) drop-shadow(0 .045em 0 #3b0764) drop-shadow(0 0 .3em rgba(34, 211, 238, .9)); }
  100% { transform: none; }
}
.skin-vaporwave .slot.revealed::after {
  content: ''; position: absolute; left: -30%; right: -30%; bottom: .13em; height: .045em; pointer-events: none;
  background: linear-gradient(90deg, transparent, #22d3ee 28%, #fff 50%, #f472b6 72%, transparent); transform: scaleX(0); opacity: 0;
  animation: vw-laser .46s var(--ease-out) backwards;
}
@keyframes vw-laser { 0% { transform: scaleX(0); opacity: 1; } 50% { transform: scaleX(1); opacity: 1; } 100% { transform: scaleX(1.2); opacity: 0; } }
.side-vaporwave { --side-border: #f0abfc; --side-glow: 0 0 18px rgba(232, 121, 249, .35); --side-ink: #fdf4ff; --side-ink-glow: 0 0 8px rgba(34, 211, 238, .8);
  --side-bg: linear-gradient(180deg, transparent 0 73%, rgba(34, 211, 238, .34) 73% 73.7%, transparent 73.7% 82%, rgba(34, 211, 238, .3) 82% 82.8%, transparent 82.8% 93%, rgba(34, 211, 238, .28) 93% 94%, transparent 94%), linear-gradient(180deg, transparent 0 66%, rgba(240, 171, 252, .75) 66% 66.5%, rgba(13, 2, 33, .9) 66.5% 100%), radial-gradient(circle 3.6rem at 50% 66%, rgba(253, 224, 71, .5) 0, rgba(251, 146, 60, .42) 48%, rgba(244, 63, 94, .34) 96%, transparent 100%), linear-gradient(180deg, rgba(23, 10, 58, .8) 0%, rgba(76, 29, 149, .6) 36%, rgba(192, 38, 211, .4) 56%, rgba(251, 113, 133, .34) 66%, transparent 66%);
  --deco-a: '🌴'; --deco-b: '🌴'; }
.side-vaporwave::before, .side-vaporwave::after { top: auto; bottom: .4rem; font-size: 1.25rem; transform-origin: 50% 100%; animation: vw-sway 3.4s ease-in-out infinite alternate; }
.side-vaporwave::after { animation-delay: -1.4s; }
@keyframes vw-sway { from { transform: rotate(-5deg); } to { transform: rotate(5deg); } }

/* ------------------------------------------------------------------ Gamble : roulette et blackjack */
.gamble-grid { align-items: start; }
.rwheel { width: 7.5rem; height: 7.5rem; margin: .4rem auto .9rem; display: grid; place-items: center; border-radius: 50%; font-size: 2.6rem; font-weight: 700; color: #fff; border: .35rem solid #a16207; box-shadow: 0 0 0 3px #1c1917, inset 0 0 0 .3rem rgba(0, 0, 0, .25), 0 10px 22px rgba(0, 0, 0, .4); background: #27272a; transition: background-color .08s linear; }
.rwheel[data-color="red"] { background: #b91c1c; } .rwheel[data-color="black"] { background: #111113; } .rwheel[data-color="green"] { background: #15803d; }
.rwheel.landed { animation: pill-pop .5s cubic-bezier(.34, 1.56, .64, 1); }
.gchips { display: flex; justify-content: center; gap: .45rem; margin-bottom: .8rem; }
.gchip { width: 2.7rem; height: 2.7rem; border-radius: 50%; border: 3px dashed rgba(255, 255, 255, .7); background: #1d4ed8; color: #fff; font: 700 .74rem var(--font-mono); cursor: pointer; box-shadow: 0 3px 0 rgba(0, 0, 0, .4); transition: transform .12s var(--ease-out); }
.gchip[data-chip="10"] { background: #475569; } .gchip[data-chip="100"] { background: #b91c1c; } .gchip[data-chip="250"] { background: #7e22ce; }
.gchip.on { transform: translateY(-4px) scale(1.08); box-shadow: 0 7px 0 rgba(0, 0, 0, .35), 0 0 0 2px var(--prose); }
.rbets { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: .4rem; }
.rbet { display: flex; align-items: center; justify-content: space-between; gap: .3rem; min-height: 2.5rem; padding: .35rem .6rem; border: 1px solid var(--outline); border-radius: .5rem; background: var(--surface-dim); color: var(--prose); font: 700 .74rem var(--font-sans); text-transform: uppercase; letter-spacing: .03em; cursor: pointer; }
.rbet.red { background: #7f1d1d; color: #fff; border-color: #b91c1c; } .rbet.black { background: #111113; color: #fff; border-color: #3f3f46; }
.rbet.on { box-shadow: 0 0 0 2px var(--ep-outline, #eab308); }
.rbet b { color: #fde047; font-size: .72rem; }
.rbet.number { grid-column: 1 / -1; cursor: default; justify-content: flex-start; flex-wrap: wrap; }
.rbet.number .input { width: 5.2rem; }
.bj-table { min-height: 11rem; display: grid; gap: .8rem; align-content: center; padding: .9rem; border-radius: .7rem; background: radial-gradient(ellipse at center, #15803d, #0f5132 80%); border: 3px solid #92400e; }
.bj-table .empty { color: rgba(255, 255, 255, .8); }
.bj-row .eyebrow { color: rgba(255, 255, 255, .85); }
.bj-cards { display: flex; flex-wrap: wrap; gap: .35rem; margin-top: .3rem; min-height: 4rem; }
.pcard { width: 2.7rem; height: 3.8rem; display: grid; place-items: center; align-content: center; border-radius: .4rem; background: #fff; color: #111; border: 1px solid #d4d4d4; box-shadow: 0 3px 6px rgba(0, 0, 0, .35); font-family: var(--font-sans); animation: chat-in .25s var(--ease-out) backwards; }
.pcard b { font-size: 1.05rem; line-height: 1; } .pcard i { font-style: normal; font-size: 1.05rem; line-height: 1.1; }
.pcard.red { color: #dc2626; }
.pcard.back { background: repeating-linear-gradient(45deg, #1d4ed8 0 5px, #1e3a8a 5px 10px); border: 3px solid #fff; }
#g-coins { margin-left: .4rem; }
@media (max-width: 760px) { .gamble-grid { grid-template-columns: 1fr; } }

/* Journal des mises à jour : au-dessus du lien GitHub ; pastille rouge tant que la dernière entrée n'est pas lue. */
.gh-corner.news-corner { bottom: 60px; font-size: 1rem; cursor: pointer; }
.news-corner.unread::after, .idea-corner.unread::after, .gc-corner.unread::after { content: ''; position: absolute; top: 2px; right: 2px; width: 10px; height: 10px; border-radius: 50%; background: #ef4444; box-shadow: 0 0 0 2px var(--site-bg); animation: news-pulse 1.8s ease-in-out infinite; }
@keyframes news-pulse { 50% { transform: scale(1.25); } }
.news-list { display: grid; gap: .9rem; max-height: 60vh; overflow-y: auto; }
.news-item ul { margin: .3rem 0 0; padding-left: 1.1rem; font-size: .86rem; line-height: 1.5; }
/* Annonces du créateur (idée de jaxoncool43, 2026-10-26) : en tête de What's new, et l'onglet Announce de la page Owner */
.ann-list { max-height: none; overflow: visible; margin-bottom: .9rem; padding-bottom: .9rem; border-bottom: 1px solid var(--outline); }
.ann-item { padding: .6rem .75rem; border-radius: .6rem; background: var(--surface); border-left: 3px solid #6366f1; }
.ann-item.ann-important { border-left-color: #ef4444; }
.ann-title { margin: .2rem 0 .25rem; font-size: .98rem; overflow-wrap: anywhere; }
.ann-text { margin: 0; font-size: .86rem; line-height: 1.5; white-space: pre-line; overflow-wrap: anywhere; }
.ann-form { display: grid; gap: .5rem; }
.ann-form textarea { resize: vertical; }
.ann-opts { display: flex; flex-wrap: wrap; gap: .4rem 1rem; font-size: .86rem; }
.ann-foot { display: flex; justify-content: space-between; align-items: center; gap: .5rem; }
.ann-row .ann-text { margin: .3rem 0 .4rem; }
/* Feuille de route publique #/roadmap (idée de Phong67, 2026-10-26) */
.rm-intro { margin: -.4rem 0 1rem; }
.rm-panel { margin-bottom: 1rem; }
.rm-list { list-style: none; margin: 0; padding: 0; display: grid; gap: .55rem; }
.rm-item { padding: .55rem .7rem; border-radius: .55rem; background: var(--surface); border: 1px solid var(--outline); min-width: 0; }
.rm-text { margin: 0 0 .25rem; font-size: .9rem; line-height: 1.45; overflow-wrap: anywhere; }
.rm-by { font-size: .76rem; color: var(--muted, inherit); opacity: .8; }
.idea-roadmap, .rm-about { margin: 0 0 .6rem; font-size: .86rem; }
.idea-roadmap a, .rm-about a { font-weight: 600; }

/* ------------------------------------------------------------------ Casino : onglets des jeux, mise, Crash, Mines, Plinko */
.g-tabs { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: .5rem; margin: .4rem 0 .8rem; }
.g-tab { display: grid; justify-items: center; gap: .15rem; padding: .7rem .3rem .6rem; border-radius: .8rem; border: 1px solid var(--outline); background: linear-gradient(180deg, var(--surface-raised), var(--surface)); color: var(--prose-2); font: 800 .72rem var(--font-sans); letter-spacing: .05em; text-transform: uppercase; cursor: pointer; transition: transform .14s var(--ease-out), box-shadow .2s ease, border-color .2s ease; }
.g-tab i { font-style: normal; font-size: 1.5rem; line-height: 1; filter: grayscale(.5); transition: transform .2s var(--ease-snap), filter .2s ease; }
.g-tab:hover { transform: translateY(-2px); border-color: var(--outline-strong); }
.g-tab.on { color: #fde68a; border-color: #eab308; background: linear-gradient(180deg, rgba(234, 179, 8, .18), rgba(234, 179, 8, .04)), var(--surface); box-shadow: 0 0 0 1px rgba(234, 179, 8, .35), 0 0 22px rgba(234, 179, 8, .18); }
.g-tab.on i { filter: none; transform: scale(1.15); }
/* Ordre des onglets (idée de jia jun, 2026-10-24) : mode « Reorder », flèches dans chaque onglet, glisser-déposer. */
.g-order-row { display: flex; justify-content: flex-end; gap: .5rem; margin: -.45rem 0 .7rem; }
.g-order-btn, .g-order-reset { padding: .2rem .55rem; border: 1px solid var(--outline); border-radius: 999px; background: none; color: var(--prose-3); font: 700 .7rem var(--font-sans); cursor: pointer; }
.g-order-btn:hover, .g-order-reset:hover { color: var(--prose); border-color: var(--outline-strong); }
.g-order-btn[aria-pressed="true"] { color: #a16207; border-color: #eab308; }
.dark .g-order-btn[aria-pressed="true"], :root[data-theme="dark"] .g-order-btn[aria-pressed="true"] { color: #fde68a; }
/* pas de tremblement : les flèches doivent rester immobiles sous le doigt */
.g-tabs.editing .g-tab { position: relative; cursor: grab; border-style: dashed; border-color: color-mix(in srgb, #eab308 55%, var(--outline)); }
.g-tabs.editing .g-tab:hover { transform: none; }
/* les flèches ont leur propre ligne sous le nom : rien ne les recouvre, même dans un onglet de 55 px */
.g-moves { display: flex; justify-content: center; gap: .25rem; width: 100%; margin-top: .2rem; }
.g-move { flex: 1 1 0; max-width: 2rem; height: 1.5rem; padding: 0; border: 0; border-radius: .4rem; background: color-mix(in srgb, var(--prose) 12%, transparent); color: var(--prose-2); font-size: .72rem; line-height: 1; cursor: pointer; }
.g-move:hover { background: color-mix(in srgb, #eab308 30%, transparent); color: var(--prose); }
.g-tabs.editing .g-tab:first-child .g-move[data-move="-1"], .g-tabs.editing .g-tab:last-child .g-move[data-move="1"] { visibility: hidden; }
.g-bet { display: flex; align-items: center; justify-content: center; gap: .8rem; margin-bottom: .9rem; }
.g-bet .gchips { margin: 0; }
.gchip[data-chip="500"] { background: #b45309; } .gchip[data-chip="1000"] { background: #111113; border-color: #eab308; color: #fde68a; }
.g-stage { max-width: 44rem; margin: 0 auto; }
.g-game { border-color: rgba(234, 179, 8, .28); background: radial-gradient(ellipse 120% 80% at 50% 0%, rgba(234, 179, 8, .07), transparent 60%), var(--surface); }
.g-result { min-height: 1.3rem; text-align: center; font-weight: 700; margin-top: .6rem; }
.g-result[data-won="yes"] { color: #4ade80; } .g-result[data-won="no"] { color: #f87171; }
.crash-screen { position: relative; border-radius: .8rem; overflow: hidden; background: radial-gradient(ellipse at 20% 100%, rgba(251, 191, 36, .12), transparent 60%), linear-gradient(180deg, #0b0f1c, #090b12); border: 1px solid rgba(255, 255, 255, .08); margin-bottom: .8rem; }
.crash-screen canvas { display: block; width: 100%; height: auto; }
.crash-screen b { position: absolute; left: 50%; top: 42%; transform: translate(-50%, -50%); font-size: clamp(2.2rem, 9vw, 3.6rem); color: #fff; text-shadow: 0 0 24px rgba(251, 191, 36, .6); }
.crash-screen[data-state="crash"] b { color: #f87171; text-shadow: 0 0 24px rgba(239, 68, 68, .7); animation: shake .5s ease; }
.crash-screen[data-state="cash"] b { color: #4ade80; text-shadow: 0 0 24px rgba(34, 197, 94, .7); }
.mn-setup { display: flex; align-items: center; justify-content: center; gap: .7rem; margin-bottom: .7rem; }
.mn-setup b { min-width: 8.5rem; color: #fde68a; font-size: .85rem; }
.mn-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: .45rem; max-width: 22rem; margin: 0 auto .8rem; }
.mn-cell { aspect-ratio: 1; border-radius: .6rem; border: 1px solid rgba(255, 255, 255, .1); background: linear-gradient(180deg, #334155, #1e293b); box-shadow: 0 4px 0 #0f172a; font-size: 1.5rem; cursor: pointer; transition: transform .12s var(--ease-out), filter .15s ease; }
.mn-cell:not(:disabled):hover { transform: translateY(-3px); filter: brightness(1.25); }
.mn-cell:disabled { cursor: default; }
.mn-cell.gem { background: linear-gradient(180deg, #065f46, #064e3b); box-shadow: 0 2px 0 #022c22, 0 0 14px rgba(52, 211, 153, .35); animation: pill-pop .35s cubic-bezier(.34, 1.56, .64, 1); }
.mn-cell.bomb { background: linear-gradient(180deg, #7f1d1d, #450a0a); box-shadow: 0 2px 0 #1c0505; opacity: .75; }
.mn-cell.bomb.hit { opacity: 1; box-shadow: 0 0 0 2px #ef4444, 0 0 22px rgba(239, 68, 68, .7); animation: shake .5s ease; }
.pk-board { border-radius: .8rem; background: radial-gradient(ellipse at 50% 0%, rgba(99, 102, 241, .25), transparent 70%), linear-gradient(180deg, #111827, #0b1020); border: 1px solid rgba(255, 255, 255, .08); }
.pk-board canvas { display: block; width: 100%; height: auto; }
.pk-slots { display: grid; grid-template-columns: repeat(13, 1fr); gap: 3px; margin: .4rem 0 .8rem; }
.pk-slots span { padding: .35rem 0; border-radius: .35rem; text-align: center; font: 700 .6rem var(--font-mono); color: #111; background: #fbbf24; transition: transform .2s var(--ease-snap); }
.pk-slots span[data-m="hi"] { background: #ef4444; color: #fff; } .pk-slots span[data-m="lo"] { background: #64748b; color: #fff; }
.pk-slots span.hit { transform: translateY(5px) scale(1.12); box-shadow: 0 0 14px currentColor; }
@media (max-width: 560px) { .g-tab span { font-size: .58rem; letter-spacing: 0; } .gchip { width: 2.3rem; height: 2.3rem; } .g-bet { gap: .4rem; } .g-bet .eyebrow { display: none; } .pk-slots span { font-size: .46rem; } }

/* ------------------------------------------------------------------ Casino : l'intérieur des jeux, façon vraie table */
/* Roulette : la roue est dessinée à plat puis couchée par la perspective ; le numéro sorti s'affiche à côté. */
.rw-scene { position: relative; display: grid; place-items: center; height: 15.5rem; margin: 0 0 .6rem; perspective: 900px; }
.rw-tilt { width: min(19rem, 86%); aspect-ratio: 1; transform: rotateX(52deg); transform-style: preserve-3d; filter: drop-shadow(0 34px 22px rgba(0, 0, 0, .65)); }
.rw-tilt canvas { display: block; width: 100%; height: 100%; border-radius: 50%; box-shadow: 0 0 0 6px #2a1406, 0 0 0 9px #a16207, inset 0 0 40px rgba(0, 0, 0, .5); }
.rw-readout { position: absolute; right: 4%; top: 6%; width: 3.6rem; height: 3.6rem; display: grid; place-items: center; border-radius: .7rem; font-size: 1.6rem; font-weight: 700; color: #fff; background: #27272a; border: 2px solid #a16207; box-shadow: 0 6px 14px rgba(0, 0, 0, .45); }
.rw-readout[data-color="red"] { background: #b91c1c; } .rw-readout[data-color="black"] { background: #111113; } .rw-readout[data-color="green"] { background: #15803d; }
.rw-readout.landed { animation: pill-pop .5s cubic-bezier(.34, 1.56, .64, 1); }
/* Blackjack : tapis, sabot, cartes à deux faces qui glissent du sabot et se retournent. */
.bj-table { position: relative; min-height: 15rem; perspective: 900px; background: radial-gradient(ellipse 120% 90% at 50% 0%, #1c9a52, #0f5132 62%, #0a3a24); border: 6px solid #5b3311; border-radius: 1rem 1rem 6rem 6rem / 1rem 1rem 2.4rem 2.4rem; box-shadow: inset 0 0 0 2px #a16207, inset 0 0 40px rgba(0, 0, 0, .45), 0 10px 22px rgba(0, 0, 0, .4); }
.bj-shoe { position: absolute; right: .8rem; top: .7rem; width: 2.7rem; height: 3.7rem; border-radius: .35rem; background: repeating-linear-gradient(45deg, #991b1b 0 5px, #7f1d1d 5px 10px); border: 3px solid #fff; box-shadow: 3px 3px 0 #e5e5e5, 6px 6px 0 #d4d4d4, 8px 10px 12px rgba(0, 0, 0, .45); transform: rotate(8deg); }
.bj-felt-text { text-align: center; font: 700 .58rem var(--font-sans); letter-spacing: .32em; color: rgba(253, 230, 138, .5); }
.bj-row { position: relative; }
.bj-cards { min-height: 5.2rem; gap: .4rem; }
.bj-stack { position: absolute; right: .2rem; bottom: .2rem; width: 2.5rem; height: 2.5rem; display: grid; place-items: center; border-radius: 50%; font: 700 .62rem var(--font-mono); color: #fff; background: #b91c1c; border: 3px dashed rgba(255, 255, 255, .8); box-shadow: 0 3px 0 #7f1d1d, 0 6px 0 #991b1b, 0 9px 0 #7f1d1d, 0 12px 10px rgba(0, 0, 0, .45); }
.pcard { width: 3.3rem; height: 4.7rem; display: block; background: none; border: 0; box-shadow: none; animation: none; perspective: 600px; }
.pc-in { position: relative; display: block; width: 100%; height: 100%; transform-style: preserve-3d; transition: transform .45s var(--ease-out); }
.pcard.down .pc-in { transform: rotateY(180deg); }
.pc-front, .pc-back { position: absolute; inset: 0; border-radius: .42rem; backface-visibility: hidden; box-shadow: 0 4px 9px rgba(0, 0, 0, .4); }
.pc-front { display: grid; place-items: center; background: linear-gradient(160deg, #fff, #f1f1f1); border: 1px solid #d4d4d4; color: #111; font-family: var(--font-sans); }
.pcard.red .pc-front { color: #dc2626; }
.pc-front b { position: absolute; left: .28rem; top: .2rem; display: grid; justify-items: center; font-size: .82rem; line-height: 1; font-weight: 800; }
.pc-front b i { font-style: normal; font-size: .7rem; }
.pc-front b.low { left: auto; top: auto; right: .28rem; bottom: .2rem; transform: rotate(180deg); }
.pc-front em { font-style: normal; font-size: 1.7rem; font-weight: 800; line-height: 1; }
.pc-back { transform: rotateY(180deg); background: repeating-linear-gradient(45deg, #991b1b 0 5px, #7f1d1d 5px 10px); border: 3px solid #fff; }
.pcard.deal { animation: pc-deal .5s var(--ease-out) backwards; animation-delay: calc(var(--i) * 170ms); }
.pcard.deal .pc-in { animation: pc-flip .5s var(--ease-out) backwards; animation-delay: calc(var(--i) * 170ms); }
.pcard.deal.down .pc-in { animation: none; }
@keyframes pc-deal { from { transform: translate(12rem, -7rem) rotate(24deg); opacity: 0; } }
@keyframes pc-flip { from { transform: rotateY(180deg); } }
/* Plinko : le plateau penche légèrement vers nous. */
.pk-board { perspective: 900px; overflow: hidden; }
.pk-board canvas { transform: rotateX(14deg); transform-origin: 50% 100%; }
/* Mines : la case bascule et montre une pierre taillée, ou la mine. */
.mn-grid { perspective: 700px; }
.mn-cell { display: grid; place-items: center; background: linear-gradient(160deg, #475569, #1e293b); box-shadow: 0 5px 0 #0f172a, inset 0 2px 0 rgba(255, 255, 255, .18), inset 0 -6px 10px rgba(0, 0, 0, .3); }
.mn-cell.flip { animation: mn-flip .42s var(--ease-out); }
@keyframes mn-flip { 0% { transform: rotateY(90deg) scale(.9); filter: brightness(2); } 60% { transform: rotateY(-8deg) scale(1.06); } 100% { transform: none; } }
.mn-gem { width: 56%; aspect-ratio: 1; clip-path: polygon(50% 0, 100% 36%, 80% 100%, 20% 100%, 0 36%); background: linear-gradient(135deg, #a7f3d0 0 28%, #34d399 28% 52%, #059669 52% 76%, #064e3b 76%); filter: drop-shadow(0 0 6px rgba(52, 211, 153, .9)); animation: gem-glint 2.4s ease-in-out infinite; }
.mn-bomb { font-size: 1.6rem; filter: drop-shadow(0 2px 3px rgba(0, 0, 0, .6)); }
.mn-cell.bomb.hit::after { content: ''; position: absolute; inset: -30%; border-radius: 50%; background: radial-gradient(circle, rgba(254, 240, 138, .9), rgba(249, 115, 22, .7) 40%, transparent 70%); animation: mn-boom .6s ease-out forwards; pointer-events: none; }
.mn-cell { position: relative; }
@keyframes mn-boom { from { transform: scale(.2); opacity: 1; } to { transform: scale(1.6); opacity: 0; } }
@media (max-width: 560px) { .rw-scene { height: 12.5rem; } .pcard { width: 2.7rem; height: 3.9rem; } .pc-front em { font-size: 1.3rem; } .bj-shoe { display: none; } }

/* Classement des pièces, solde dans le duel et au casino. */
.lb-coins { font-weight: 700; color: var(--ep-text, #fbbf24); white-space: nowrap; }
.d-wallet { margin: .45rem 0 0; font-weight: 700; color: var(--prose); }
.g-head { display: flex; align-items: center; justify-content: space-between; gap: 1rem; flex-wrap: wrap; }
.g-wallet { display: grid; justify-items: end; padding: .45rem .9rem; border-radius: .7rem; border: 1px solid #eab308; background: linear-gradient(180deg, rgba(234, 179, 8, .16), rgba(234, 179, 8, .04)); box-shadow: 0 0 18px rgba(234, 179, 8, .15); }
.g-wallet b { font-size: 1.25rem; color: #fde68a; }
@media (max-width: 560px) { .lb-tabs button { font-size: .6rem; padding-inline: .1rem; } }

/* Les quatre ronds (nouveautés, GitHub, idée, café) : fixes dans les coins sur grand écran, où les marges sont vides ;
   en dessous de 900 px ils recouvraient des boutons en défilant, donc ils se rangent en bas de page. */
.corners { display: contents; }
@media (max-width: 900px) {
  .corners { display: flex; flex-wrap: wrap; justify-content: center; gap: .7rem; padding: 0 0 1.4rem; position: relative; z-index: 1; }
  .corners .gh-corner { position: relative; inset: auto; opacity: .9; }
  .app { padding-bottom: 2rem; }
}
/* Très petit téléphone (320 px) : huit onglets, la langue et le joueur tiennent sans se chevaucher. */
@media (max-width: 350px) {
  .topbar .icon-link { display: none; }
  .logo { letter-spacing: 0; font-size: .92rem; }
  .nav a { padding: .42rem .17rem; }
  .topbar { padding-inline: .45rem; }
}

/* Fenêtres : un titre long passe à la ligne avant la croix au lieu de glisser dessous ; sur un écran de 320 px,
   marges resserrées pour que le bouton Google (largeur imposée par Google) tienne dedans. */
.modal h2 { padding-right: 1.9rem; }
@media (max-width: 350px) {
  .modal-backdrop { padding-inline: .5rem; }
  .modal { padding-inline: .8rem; }
}
/* Casino sur petit téléphone : « BLACKJACK » débordait de son onglet. */
@media (max-width: 400px) { .g-tabs { gap: .3rem; } .g-tab { padding-inline: .1rem; } .g-tab span { font-size: .5rem; } }
/* Casino : le texte d'introduction remontait sous la boîte « Your coins » (marge négative prévue pour un titre seul). */
.g-head + .profile-sub { margin-top: .4rem; }
/* Annonce cliquable (quête terminée : ramène à l'accueil pour récupérer les pièces). */
.toast.link { cursor: pointer; }
@media (max-width: 560px) { .toast { max-width: calc(100vw - 1.5rem); width: max-content; text-align: center; } }
/* Carte de tirage à partager : aperçu dans la fenêtre de partage. */
.share-card { display: block; width: 100%; height: auto; aspect-ratio: 1200 / 630; border-radius: .6rem; background: #0d0b14; box-shadow: 0 10px 30px rgba(0, 0, 0, .35); }
.share-actions { justify-content: center; margin-top: .9rem; }
.share-note { text-align: center; margin: .7rem 0 0; }
.modal:has(.share-card) { width: min(100%, 40rem); }

/* ------------------------------------------------------------------ raretés au-dessus de Mythic (cartes seulement)
   Celestial : glace et ciel. Divine : or blanc. Godlike : or rose (idée de MAYO, 2026-10-16). Infinite : blanc prismatique dont le halo fait le tour des couleurs. */
[data-tier="celestial"] {
  --t-from: #cffafe; --t-via: #f0f9ff; --t-to: #e0e7ff; --t-border: #67e8f9;
  --t-glow: 0 0 18px rgba(34, 211, 238, .35), 0 0 34px rgba(129, 140, 248, .18);
  --t-text: #0e7490; --t-pill-text: #0e7490; --t-pill-bg: #ecfeff; --t-pill-border: #67e8f9;
  --t-hl: #a5f3fc; --t-hl-border: #0891b2; --t-accent: #0891b2; --t-shimmer: 1;
}
[data-tier="divine"] {
  --t-from: #fef9c3; --t-via: #fffef5; --t-to: #fde68a; --t-border: #facc15;
  --t-glow: 0 0 20px rgba(250, 204, 21, .45), 0 0 40px rgba(245, 158, 11, .2);
  --t-text: #854d0e; --t-pill-text: #854d0e; --t-pill-bg: #fefce8; --t-pill-border: #facc15;
  --t-hl: #fef08a; --t-hl-border: #ca8a04; --t-accent: #ca8a04; --t-shimmer: 1;
}
[data-tier="godlike"] {
  --t-from: #ffe4e6; --t-via: #fffbeb; --t-to: #fef08a; --t-border: #fb7185;
  --t-glow: 0 0 22px rgba(251, 113, 133, .5), 0 0 44px rgba(250, 204, 21, .3);
  --t-text: #9f1239; --t-pill-text: #9f1239; --t-pill-bg: #fff1f2; --t-pill-border: #fb7185;
  --t-hl: #fecdd3; --t-hl-border: #e11d48; --t-accent: #e11d48; --t-shimmer: 1;
}
[data-tier="infinite"] {
  --t-from: #fce7f3; --t-via: #ffffff; --t-to: #dbeafe; --t-border: #c084fc;
  --t-glow: 0 0 22px rgba(192, 132, 252, .5), 0 0 46px rgba(96, 165, 250, .25);
  --t-text: #111827; --t-pill-text: #6d28d9; --t-pill-bg: #faf5ff; --t-pill-border: #c084fc;
  --t-hl: #f5d0fe; --t-hl-border: #7c3aed; --t-accent: #7c3aed; --t-shimmer: 1;
}
.dark [data-tier="celestial"] {
  --t-from: rgba(14, 116, 144, .55); --t-via: rgba(30, 41, 59, .7); --t-to: rgba(55, 48, 163, .5); --t-border: #22d3ee;
  --t-glow: 0 0 22px rgba(34, 211, 238, .5), 0 0 44px rgba(129, 140, 248, .25);
  --t-text: #ecfeff; --t-pill-text: #67e8f9; --t-pill-bg: rgba(8, 51, 68, .5); --t-pill-border: rgba(34, 211, 238, .6);
}
.dark [data-tier="divine"] {
  --t-from: rgba(133, 77, 14, .6); --t-via: rgba(66, 32, 6, .6); --t-to: rgba(161, 98, 7, .55); --t-border: #facc15;
  --t-glow: 0 0 24px rgba(250, 204, 21, .55), 0 0 50px rgba(245, 158, 11, .28);
  --t-text: #fefce8; --t-pill-text: #fde047; --t-pill-bg: rgba(66, 32, 6, .5); --t-pill-border: rgba(250, 204, 21, .6);
}
.dark [data-tier="godlike"] {
  --t-from: rgba(159, 18, 57, .6); --t-via: rgba(66, 32, 6, .6); --t-to: rgba(161, 98, 7, .5); --t-border: #fb7185;
  --t-glow: 0 0 26px rgba(251, 113, 133, .55), 0 0 52px rgba(250, 204, 21, .3);
  --t-text: #fff1f2; --t-pill-text: #fda4af; --t-pill-bg: rgba(76, 5, 25, .5); --t-pill-border: rgba(251, 113, 133, .65);
}
.dark [data-tier="infinite"] {
  --t-from: rgba(131, 24, 67, .5); --t-via: rgba(49, 46, 129, .55); --t-to: rgba(6, 78, 59, .45); --t-border: #f5d0fe;
  --t-glow: 0 0 26px rgba(255, 255, 255, .45), 0 0 56px rgba(192, 132, 252, .4);
  --t-text: #ffffff; --t-pill-text: #f5d0fe; --t-pill-bg: rgba(59, 7, 100, .5); --t-pill-border: rgba(245, 208, 254, .65);
}
[data-tier="celestial"] .card-stage.lit .rays { opacity: .55; animation-duration: 7s; }
[data-tier="divine"] .card-stage.lit .rays { opacity: .62; animation-duration: 6s; }
[data-tier="godlike"] .card-stage.lit .rays { opacity: .66; animation-duration: 5s; }
[data-tier="infinite"] .card-stage.lit .rays { opacity: .7; animation-duration: 4.5s; }
/* Les pastilles des trois raretés brillent ; celle d'Infinite fait défiler un arc-en-ciel. */
.pill[data-tier="celestial"], .pill[data-tier="divine"], .pill[data-tier="godlike"], .pill[data-tier="infinite"] { font-weight: 800; box-shadow: 0 0 10px color-mix(in srgb, var(--t-pill-border) 60%, transparent); }
.pill[data-tier="infinite"] {
  color: #fff; border-color: transparent; text-shadow: 0 1px 2px rgba(0, 0, 0, .45);
  background: linear-gradient(90deg, #ec4899, #a855f7, #3b82f6, #10b981, #eab308, #f97316, #ec4899) 0 0 / 300% 100%;
  animation: tier-rainbow 5s linear infinite;
}
@keyframes tier-rainbow { to { background-position: 300% 0; } }
@media (prefers-reduced-motion: reduce) { .pill[data-tier="infinite"] { animation: none; } }

/* Shop : niveaux de vitesse du tirage. */
.speed-row { display: flex; align-items: center; gap: .9rem; flex-wrap: wrap; }
.speed-pips { display: flex; gap: .3rem; }
.speed-pips i { width: 1.5rem; height: .6rem; border-radius: .3rem; background: var(--surface-dim); border: 1px solid var(--outline); transform: skewX(-18deg); }
.speed-pips i.on { background: linear-gradient(90deg, #f472b6, #818cf8); border-color: transparent; box-shadow: 0 0 10px rgba(192, 132, 252, .5); }
.speed-text { display: grid; gap: .1rem; flex: 1 1 10rem; min-width: 0; }
.speed-note { margin: .7rem 0 0; }

/* Shop : onglets de catégorie (une seule catégorie affichée à la fois). */
.shop-tabs { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: .45rem; margin: 0 0 1rem; }
.shop-tabs button { display: flex; align-items: center; justify-content: center; gap: .45rem; padding: .7rem .4rem; border-radius: .7rem; border: 1px solid var(--outline); background: var(--surface); color: var(--prose-2); font: 800 .78rem var(--font-sans); letter-spacing: .04em; text-transform: uppercase; cursor: pointer; transition: transform .15s ease, border-color .15s ease, color .15s ease; }
.shop-tabs button i { font-style: normal; font-size: 1.1rem; line-height: 1; filter: grayscale(.6); }
.shop-tabs button:hover { transform: translateY(-1px); border-color: var(--outline-strong); color: var(--prose); }
.shop-tabs button.on { color: var(--prose); border-color: transparent; background: linear-gradient(var(--surface), var(--surface)) padding-box, linear-gradient(120deg, #f472b6, #c084fc, #818cf8) border-box; box-shadow: 0 0 18px rgba(192, 132, 252, .22); }
.shop-tabs button.on i { filter: none; }
.shop-pane > .panel + .panel { margin-top: 1rem; }
.shop-more { grid-column: 1 / -1; margin: .4rem 0 0; text-align: center; }
@media (max-width: 560px) {
  .shop-tabs { gap: .3rem; }
  .shop-tabs button { flex-direction: column; gap: .2rem; padding: .55rem .1rem; font-size: .56rem; letter-spacing: 0; }
  .shop-tabs button i { font-size: 1.25rem; }
}

/* ------------------------------------------------------------------ duel : score compact, bouton de tirage toujours à l'écran
   Avant : une ligne par joueur (223 px à six) poussait les cartes et le bouton sous l'écran. Le score devient une
   bande de pastilles, et le bloc du bouton reste collé en bas de l'écran tant qu'on n'a pas défilé jusqu'à lui. */
.room-board { display: grid; grid-template-columns: repeat(auto-fit, minmax(11rem, 1fr)); gap: .4rem; padding: 0; border: 0; background: none; margin-bottom: .8rem; }
.room-board .board-row { min-width: 0; gap: .4rem; padding: .34rem .6rem; border: 1px solid var(--outline); border-radius: .6rem; background: var(--surface); font-size: .78rem; }
.room-board .board-row:first-child { border-top: 1px solid var(--outline); }
.room-board .board-row.me { border-color: color-mix(in srgb, var(--chart-accent) 55%, var(--outline)); }
.room-board .board-row .rank { width: auto; }
.board-who { display: flex; align-items: center; gap: .3rem; min-width: 0; overflow: hidden; white-space: nowrap; }
.board-who > a, .board-who > .bot-name { overflow: hidden; text-overflow: ellipsis; }
.board-who > .muted { display: none; }
.room-board .board-metric { gap: .4rem; }
.room-board .board-metric > .mono, .room-board .board-metric > .board-wins { min-width: 0; }
.room-board .xp-bar { width: 3rem; }
.room-actions {
  position: sticky; bottom: .6rem; z-index: 15; width: fit-content; max-width: 100%; margin: 1rem auto .6rem; padding: .6rem .9rem .5rem;
  border: 1px solid var(--outline); border-radius: 1rem; background: color-mix(in srgb, var(--site-bg) 90%, transparent); backdrop-filter: blur(10px);
  box-shadow: 0 10px 30px rgba(0, 0, 0, .35);
}
.room-actions .hint { margin: .35rem 0 0; }
.room-actions .hint:empty { display: none; }
.room-actions .room-wait { margin: .2rem 0; }
@media (max-width: 560px) {
  .room-board { grid-template-columns: repeat(auto-fit, minmax(7.2rem, 1fr)); gap: .3rem; }
  .room-board .board-row { padding: .28rem .45rem; font-size: .72rem; }
  .room-board .board-xp, .room-board .xp-bar, .room-board .board-who .title-chip { display: none; }
  .room-actions { bottom: .4rem; padding: .45rem .6rem .4rem; }
  .room-actions .btn-roll { padding-block: .7rem; font-size: 1rem; }
  .room-actions .hint kbd, .room-actions .hint { font-size: .7rem; }
}
/* Téléphone : pas de clavier, donc pas de « press Space » ; la pastille de score garde la place pour le nom. */
@media (pointer: coarse) { .room-actions .hint:has(kbd) { display: none; } }
@media (max-width: 560px) { .room-board .board-row .rank { display: none; } .room-board .board-wins { word-spacing: -.35em; } }

/* Casino : bandeau « en direct » de la maison (donné / pris, dernières manches), sur une ligne, discret. */
.g-live { display: flex; align-items: center; gap: .55rem .8rem; flex-wrap: wrap; margin: 0 0 .7rem; padding: .4rem .7rem; border: 1px solid var(--outline); border-radius: .6rem; background: var(--surface); font-size: .72rem; color: var(--prose-2); overflow: hidden; }
.g-live .eyebrow { font-size: .62rem; margin: 0 0 0 -.3rem; }
.g-live-dot { width: .45rem; height: .45rem; border-radius: 50%; background: #ef4444; box-shadow: 0 0 0 0 rgba(239, 68, 68, .6); animation: g-live-pulse 1.8s ease-out infinite; }
@keyframes g-live-pulse { to { box-shadow: 0 0 0 .5rem rgba(239, 68, 68, 0); } }
.g-live .up { color: #34d399; }
.g-live .down { color: #f87171; }
.g-live-feed { display: flex; gap: .4rem; flex: 1 1 12rem; min-width: 0; overflow: hidden; white-space: nowrap; justify-content: flex-end; mask-image: linear-gradient(90deg, #000 85%, transparent); }
.g-live-row { display: inline-flex; align-items: center; gap: .25rem; padding: .12rem .45rem; border-radius: 999px; background: var(--surface-dim); color: var(--prose-2); }
.g-live-row b { font-size: .7rem; }
@media (max-width: 560px) { .g-live-feed { flex-basis: 100%; justify-content: flex-start; } }
@media (prefers-reduced-motion: reduce) { .g-live-dot { animation: none; } }

/* Roulette : la roue inclinée en 3D déborde de sa zone et captait les clics des mises placées dessous (sur téléphone,
   Red, Black et Even étaient inatteignables). Elle n'a rien de cliquable : elle laisse passer les clics. */
.rw-scene, .rw-scene * { pointer-events: none; }
/* … et elle passait aussi visuellement sur la première rangée de mises : la zone de la roue est agrandie. */
.rw-scene { height: 16.5rem; margin-bottom: 1.4rem; }
@media (max-width: 560px) { .rw-scene { height: 14rem; margin-bottom: 1.8rem; } }

/* ------------------------------------------------------------------ casino : machine à sous (préfixe sm-)
   Un meuble rouge et or : fronton à ampoules, vitre à trois rouleaux, ligne de gain, levier sur le côté, bac à pièces. */
.g-tabs { grid-template-columns: repeat(6, minmax(0, 1fr)); }
@media (max-width: 560px) { .g-tabs { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.sm-machine { --c: 5.4rem; position: relative; width: fit-content; max-width: 100%; margin: .4rem auto .9rem; padding: .7rem .9rem .8rem; border-radius: 1.4rem 1.4rem 1rem 1rem;
  background: linear-gradient(180deg, #b91c1c, #7f1d1d 55%, #450a0a); border: 3px solid #fbbf24;
  box-shadow: 0 0 0 4px #78350f, 0 18px 40px rgba(0, 0, 0, .55), inset 0 2px 0 rgba(255, 255, 255, .25), inset 0 -10px 24px rgba(0, 0, 0, .35); }
.sm-crown { display: flex; align-items: center; justify-content: center; gap: .6rem; margin-bottom: .6rem; }
.sm-name { font: 900 1.25rem var(--font-sans); letter-spacing: .14em; color: #fde68a; text-shadow: 0 0 12px rgba(253, 224, 71, .8), 0 2px 0 #78350f; white-space: nowrap; }
.sm-bulbs { display: flex; gap: .3rem; flex: 1 1 0; justify-content: space-between; min-width: 0; overflow: hidden; }
.sm-bulbs i { flex: 0 0 auto; width: .5rem; height: .5rem; border-radius: 50%; background: #fde047; box-shadow: 0 0 8px #fde047; animation: sm-bulb 1.4s steps(1) infinite; }
.sm-bulbs i:nth-child(odd) { animation-delay: -.7s; }
@keyframes sm-bulb { 0%, 49% { opacity: 1; } 50%, 100% { opacity: .22; box-shadow: none; } }
.sm-machine[data-state="spin"] .sm-bulbs i { animation-duration: .5s; }
.sm-machine[data-state="tease"] .sm-bulbs i { animation-duration: .16s; background: #fb923c; box-shadow: 0 0 10px #fb923c; }
.sm-machine[data-state="win"] .sm-bulbs i, .sm-machine[data-state="jackpot"] .sm-bulbs i { animation-duration: .22s; background: #4ade80; box-shadow: 0 0 10px #4ade80; }
.sm-machine[data-state="jackpot"] { animation: sm-jackpot .5s ease-in-out 5; }
@keyframes sm-jackpot { 50% { box-shadow: 0 0 0 4px #78350f, 0 0 60px rgba(253, 224, 71, .9), inset 0 2px 0 rgba(255, 255, 255, .25); transform: scale(1.012); } }
.sm-body { display: flex; align-items: center; gap: .7rem; }
.sm-window { position: relative; display: grid; grid-template-columns: repeat(3, var(--c)); gap: .35rem; height: calc(var(--c) * 3); padding: .35rem; border-radius: .7rem; overflow: hidden;
  background: #0b0b10; border: 3px solid #fbbf24; box-shadow: inset 0 0 22px rgba(0, 0, 0, .9); box-sizing: content-box; }
.sm-reel { position: relative; height: calc(var(--c) * 3); overflow: hidden; border-radius: .4rem; background: linear-gradient(180deg, #d4d4d8, #fafafa 22%, #ffffff 50%, #fafafa 78%, #d4d4d8); }
.sm-strip { display: flex; flex-direction: column; will-change: transform; }
.sm-strip.blur { filter: blur(1.6px); }
.sm-cell { display: grid; place-items: center; height: var(--c); flex: 0 0 var(--c); }
.sm-cell svg { width: 72%; height: 72%; filter: drop-shadow(0 2px 2px rgba(0, 0, 0, .25)); }
.sm-reel.stopped { animation: sm-stop .28s ease-out; }
@keyframes sm-stop { 30% { transform: translateY(5px); } 65% { transform: translateY(-2px); } }
.sm-cell.win { animation: sm-win 0.55s ease-in-out infinite alternate; }
@keyframes sm-win { from { transform: scale(1); filter: none; } to { transform: scale(1.16); filter: drop-shadow(0 0 10px #facc15) brightness(1.1); } }
.sm-payline { position: absolute; left: 0; right: 0; top: 50%; height: calc(var(--c) + 2px); transform: translateY(-50%); border-block: 2px solid rgba(239, 68, 68, .75); pointer-events: none; box-shadow: 0 0 12px rgba(239, 68, 68, .35); }
.sm-machine[data-state="win"] .sm-payline, .sm-machine[data-state="jackpot"] .sm-payline { border-color: #4ade80; box-shadow: 0 0 18px rgba(74, 222, 128, .7); }
.sm-glass { position: absolute; inset: 0; pointer-events: none; background: linear-gradient(180deg, rgba(0, 0, 0, .55), transparent 26%, transparent 74%, rgba(0, 0, 0, .55)), linear-gradient(115deg, rgba(255, 255, 255, .16), transparent 30%); }
.sm-lever { position: relative; flex: 0 0 1.5rem; width: 1.5rem; height: calc(var(--c) * 2.4); padding: 0; border: 0; background: none; cursor: pointer; }
.sm-lever::before { content: ''; position: absolute; left: 50%; bottom: 8%; width: 1.3rem; height: 2.2rem; transform: translateX(-50%); border-radius: .4rem; background: linear-gradient(90deg, #52525b, #d4d4d8, #52525b); box-shadow: 0 3px 6px rgba(0, 0, 0, .5); }
.sm-arm { position: absolute; left: 50%; bottom: 22%; width: .42rem; height: 68%; margin-left: -.21rem; border-radius: .2rem; background: linear-gradient(90deg, #a1a1aa, #f4f4f5, #71717a); transform-origin: 50% 100%; }
.sm-arm i { position: absolute; left: 50%; top: -1rem; width: 1.5rem; height: 1.5rem; margin-left: -.75rem; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #fecaca, #dc2626 55%, #7f1d1d); box-shadow: 0 3px 6px rgba(0, 0, 0, .5); }
.sm-lever:hover .sm-arm i { filter: brightness(1.15); }
.sm-lever.pull .sm-arm { animation: sm-pull .7s cubic-bezier(.3, .1, .3, 1); }
@keyframes sm-pull { 35% { transform: scaleY(.28); } 100% { transform: scaleY(1); } }
.sm-tray { height: 2rem; margin-top: .65rem; border-radius: .5rem; background: linear-gradient(180deg, #18181b, #27272a); border: 2px solid #78350f; display: grid; place-items: center; box-shadow: inset 0 4px 10px rgba(0, 0, 0, .7); }
.sm-win { font-size: 1.15rem; font-weight: 700; color: #4ade80; text-shadow: 0 0 12px rgba(74, 222, 128, .7); }
.sm-pays { display: flex; flex-wrap: wrap; justify-content: center; gap: .35rem .5rem; margin-top: .8rem; }
.sm-pay { display: inline-flex; align-items: center; gap: .35rem; padding: .2rem .5rem; border-radius: 999px; border: 1px solid var(--outline); background: var(--surface-dim); font-size: .72rem; }
.sm-pay-icons { display: inline-flex; gap: 1px; }
.sm-pay-icons svg { width: 1.05rem; height: 1.05rem; }
.sm-pay b { color: #fde68a; }
@media (max-width: 560px) { .sm-machine { --c: 4.2rem; padding: .55rem .6rem .65rem; } .sm-name { font-size: .95rem; letter-spacing: .08em; } .sm-body { gap: .45rem; } .sm-bulbs i:nth-child(n+7) { display: none; } }
@media (max-width: 350px) { .sm-machine { --c: 3.5rem; } }
@media (prefers-reduced-motion: reduce) { .sm-bulbs i, .sm-cell.win, .sm-machine[data-state="jackpot"], .sm-reel.stopped { animation: none; } .sm-strip.blur { filter: none; } }
.g-game[data-game="slots"] .actions { display: flex; }

/* ------------------------------------------------------------------ page Owner : carte, heures, casino, joueurs */
.o-section { margin: 1.8rem 0 .7rem; font-size: 1.05rem; font-weight: 800; text-transform: uppercase; letter-spacing: .03em; }
.o-map-wrap { display: grid; grid-template-columns: minmax(0, 1fr) 15rem; gap: 1rem; align-items: start; }
.o-map { display: block; width: 100%; height: auto; border-radius: .6rem; background: radial-gradient(ellipse at 50% 40%, rgba(129, 140, 248, .08), transparent 70%), var(--surface-dim); }
.o-map path { fill: var(--surface-raised); stroke: var(--site-bg); stroke-width: .5; transition: filter .15s ease; }
.o-map path:hover { filter: brightness(1.5); }
.o-dot { fill: rgba(244, 114, 182, .75); stroke: #fff; stroke-width: .4; }
.o-ping { fill: #f472b6; stroke: #fff; stroke-width: .5; transform-box: fill-box; transform-origin: center; animation: o-ping 1.8s ease-out infinite; }
@keyframes o-ping { 0% { transform: scale(.7); opacity: 1; } 70% { transform: scale(2.1); opacity: .15; } 100% { transform: scale(.7); opacity: 1; } }
.o-countries { display: grid; gap: .1rem; font-size: .78rem; }
.o-country { display: grid; grid-template-columns: minmax(0, 1fr) auto 3.2rem; gap: .5rem; align-items: baseline; padding: .22rem 0; border-top: 1px solid var(--outline); }
.o-country:first-child { border-top: 0; }
.o-country > span:first-child { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.o-country .panel-note { text-align: right; }
.o-hours { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); gap: 2px; height: 8rem; align-items: end; padding-bottom: 1.1rem; }
.o-hour { position: relative; height: 100%; display: flex; align-items: flex-end; }
.o-hour i { display: block; width: 100%; border-radius: 3px 3px 0 0; background: linear-gradient(180deg, #a855f7, #3b82f6); }
.o-hour em { position: absolute; left: 0; right: 0; bottom: -1.1rem; text-align: center; font: 500 .6rem var(--font-mono); color: var(--prose-3); }
.o-tr.c5 { grid-template-columns: minmax(6.5rem, 1.4fr) repeat(4, minmax(3rem, 1fr)); }
.o-tr.c4 { grid-template-columns: minmax(6.5rem, 1.6fr) repeat(3, minmax(3rem, 1fr)); }
.o-up { color: #34d399; } .o-down { color: #f87171; }
@media (max-width: 760px) { .o-map-wrap { grid-template-columns: 1fr; } .o-countries { grid-template-columns: 1fr 1fr; column-gap: 1rem; } }
@media (prefers-reduced-motion: reduce) { .o-ping { animation: none; } }
.o-tr.c6 { grid-template-columns: 3.2rem repeat(4, minmax(2.6rem, 1fr)) minmax(5.6rem, 1.5fr); }
.o-tr.c6 span, .o-tr.c5 span, .o-tr.c4 span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
@media (max-width: 560px) { .o-countries { grid-template-columns: 1fr; } }

/* Plinko : pièces de 1 et 5 visibles seulement sur ce jeu ; bouton qu'on peut marteler ou maintenir. */
.gchip.pk-only { display: none; }
.gchips[data-game="plinko"] .gchip.pk-only { display: inline-block; }
.gchip[data-chip="1"] { background: #e4e4e7; color: #18181b; border-color: rgba(0, 0, 0, .45); }
.gchip[data-chip="5"] { background: #0f766e; }
.pk-hint { text-align: center; margin: .4rem 0 0; font-size: .7rem; }
#pk-go { touch-action: manipulation; user-select: none; -webkit-user-select: none; -webkit-touch-callout: none; }
.g-game[data-game="plinko"] .actions { display: flex; }

/* Shop, onglet Améliorations : progression vers « Skip known badges ». */
.up-progress { display: grid; gap: .25rem; flex: 0 0 9rem; }
.up-progress .quest-bar { height: .6rem; }
.up-progress .quest-bar > span { display: block; height: 100%; border-radius: 999px; background: linear-gradient(90deg, #f472b6, #818cf8); }

/* Sous le bouton Google : le bonus d'association. */
.google-promo { display: inline-block; margin: .1rem 0; padding: .2rem .6rem; border-radius: 999px; border: 1px solid #eab308; background: rgba(234, 179, 8, .12); color: #fde68a; font-size: .74rem; font-weight: 700; }
:root:not(.dark) .google-promo { color: #854d0e; }

/* ------------------------------------------------------------------ cagnotte du serveur */
[data-fund-slot]:empty { display: none; }
.fund-card { margin: 1rem auto; max-width: 34rem; padding: .7rem .9rem .75rem; border-radius: .8rem; border: 1px solid #e8a798; text-align: left;
  background: radial-gradient(120% 100% at 0% 0%, rgba(251, 113, 133, .14), transparent 60%), var(--surface); }
.shop-pane ~ .fund-card, .page-wide > [data-fund-slot] .fund-card { max-width: none; margin: 0 0 1rem; }
.fund-head { display: flex; justify-content: space-between; align-items: baseline; gap: .6rem; flex-wrap: wrap; }
.fund-head b { color: #fda4af; }
.fund-bar { display: block; height: .6rem; margin: .45rem 0 .55rem; border-radius: 999px; background: var(--surface-raised); overflow: hidden; }
.fund-bar > span { display: block; height: 100%; border-radius: 999px; background: linear-gradient(90deg, #fb7185, #f9a8d4, #fde68a); transition: width .8s ease; }
.fund-card.reached { box-shadow: 0 0 18px rgba(251, 113, 133, .3); }
.fund-foot { display: flex; align-items: center; justify-content: space-between; gap: .8rem; flex-wrap: wrap; }
.fund-foot .panel-note { flex: 1 1 14rem; margin: 0; }
.fund-perk { display: flex; align-items: center; gap: .9rem; flex-wrap: wrap; padding: .8rem; margin-bottom: .8rem; border-radius: .7rem; border: 1px solid var(--outline); background: var(--surface-dim); }
.fund-perk > div:last-child { display: grid; gap: .2rem; flex: 1 1 12rem; }
.fund-steps { margin: 0 0 .8rem; padding-left: 1.2rem; display: grid; gap: .3rem; font-size: .86rem; }
.supporter-tile { border-color: rgba(232, 167, 152, .55); background: radial-gradient(120% 80% at 50% 0%, rgba(251, 113, 133, .1), transparent 60%), var(--surface); }
.o-fund-forms { display: grid; grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr)); gap: 1rem; margin: .4rem 0 1rem; }
.o-fund-form { display: grid; gap: .45rem; align-content: start; }
.o-fund-form .input { text-align: left; text-transform: none; letter-spacing: 0; font-size: .85rem; }
.o-tr.c3 { grid-template-columns: minmax(4.5rem, 1fr) minmax(5rem, 1.6fr) minmax(4rem, 1fr); }

/* Accueil : la cagnotte se range à droite des quêtes du jour (dessous quand l'écran est trop étroit). */
.home-row { display: flex; justify-content: center; align-items: flex-start; gap: 1rem; flex-wrap: wrap; margin-top: 1.2rem; }
.home-row > #quests-slot { flex: 0 1 26rem; min-width: 0; }
.home-row > #quests-slot:empty { display: none; }
.home-row .quests-card { width: 100%; margin: 0; }
.home-row > [data-fund-slot] { flex: 0 1 17rem; min-width: 0; }
.home-row .fund-card { margin: 0; max-width: none; }
.home-row .fund-foot { flex-direction: column; align-items: stretch; gap: .6rem; }
.home-row .fund-foot .panel-note { flex: none; }
.home-row .fund-foot .btn { width: 100%; }
@media (max-width: 760px) { .home-row > [data-fund-slot] { flex-basis: 26rem; } .home-row .fund-foot { flex-direction: row; align-items: center; } .home-row .fund-foot .btn { width: auto; } .home-row .fund-foot .panel-note { flex: 1 1 12rem; } }
/* Grand écran : les quêtes restent centrées sous le bouton, la cagnotte se pose à leur droite (la rangée dépasse
   alors la colonne de la page, sans sortir de l'écran). */
@media (min-width: 1180px) {
  .home-row { display: grid; grid-template-columns: minmax(0, 1fr) 26rem minmax(0, 1fr); width: min(64rem, 100vw - 9rem); align-self: center; } /* la colonne de la page centre déjà ses blocs */
  .home-row > #quests-slot { grid-column: 2; }
  .home-row > [data-fund-slot] { grid-column: 3; justify-self: start; width: min(17rem, 100%); }
  .home-row > #quests-slot:empty + [data-fund-slot] { grid-column: 2; justify-self: center; width: 100%; }
  /* l'événement de la semaine, sous la cagnotte */
  .home-row { grid-template-rows: auto 1fr; }
  .home-row > #quests-slot { grid-row: 1 / span 2; }
  .home-row > #event-side { grid-column: 3; grid-row: 2; justify-self: start; width: min(17rem, 100%); }
  .home-row > #event-side .event-quest { margin: 0; padding: .8rem .9rem; display: grid; grid-template-columns: auto 1fr; align-items: center; gap: .3rem .6rem; text-align: left; background-color: var(--panel, #15151c); border-top: 1px solid color-mix(in srgb, #f59e0b 55%, transparent); }
  .home-row > #event-side .event-quest > .quest-emoji { grid-row: 1; grid-column: 1; }
  .home-row > #event-side .event-quest > :last-child { grid-row: 1; grid-column: 2; justify-self: end; }
  .home-row > #event-side .event-quest > .quest-text { grid-row: 2; grid-column: 1 / -1; text-align: left; }
}
#event-side:empty { display: none; }

/* Page Owner : dons arrivés sans pseudo reconnu, à attribuer. */
.o-fund-auto { margin: .2rem 0 .8rem; }
.o-fund-pending { display: grid; gap: .5rem; margin-bottom: 1rem; padding: .7rem .8rem; border-radius: .7rem; border: 1px solid #eab308; background: rgba(234, 179, 8, .07); }
.o-pending { display: grid; grid-template-columns: minmax(0, 1fr) 11rem auto auto auto; gap: .5rem; align-items: center; }
.o-pending-what { display: grid; gap: .1rem; min-width: 0; font-size: .82rem; }
.o-pending-what em { font-style: normal; color: var(--prose-2); overflow-wrap: anywhere; }
.o-pending .input { text-align: left; text-transform: none; letter-spacing: 0; font-size: .82rem; }
@media (max-width: 700px) { .o-pending { grid-template-columns: 1fr 1fr; } .o-pending-what, .o-pending .input { grid-column: 1 / -1; } }

.fund-perk-card { display: grid; justify-items: center; gap: .4rem; }

/* Duel : objectif tapé à la main (manches, XP). */
.step-input { width: 3.2rem; padding: .2rem .1rem; border: 1px solid var(--outline); border-radius: .4rem; background: var(--surface-dim); color: var(--prose); font-size: 1rem; font-weight: 700; text-align: center; }
.step-input:focus, .setup-input:focus { outline: 2px solid var(--chart-accent); outline-offset: 1px; }
.setup-custom { margin-top: .45rem; }
.setup-input { width: 8.5rem; padding: .4rem .6rem; font-size: .85rem; text-transform: none; letter-spacing: 0; text-align: left; }
.setup-input.on { border-color: var(--prose); box-shadow: 0 0 0 1px var(--prose); }

/* ---------------------------------------------------------------- page Owner : onglets, graphiques, cohortes */
.o-tabs { position: sticky; top: .4rem; z-index: 5; display: flex; gap: .35rem; margin: 0 0 1rem; padding: .35rem; border: 1px solid var(--outline); border-radius: .85rem; background: var(--surface); overflow-x: auto; scrollbar-width: none; box-shadow: 0 6px 18px rgba(0, 0, 0, .18); }
.o-tabs::-webkit-scrollbar { display: none; }
.o-tabs button { position: relative; flex: 1 0 auto; display: flex; align-items: center; justify-content: center; gap: .4rem; padding: .55rem .8rem; border: 0; border-radius: .6rem; background: none; color: var(--prose-2); font: 800 .76rem var(--font-sans); letter-spacing: .02em; cursor: pointer; white-space: nowrap; }
.o-tabs button i { font-style: normal; font-size: 1rem; line-height: 1; filter: grayscale(.6); }
.o-tabs button:hover { color: var(--prose); background: var(--surface-raised); }
.o-tabs button.on { color: #fff; background: linear-gradient(120deg, #6366f1, #a855f7); }
.o-tabs button.on i { filter: none; }
.o-badge { min-width: 1.15rem; padding: 0 .3rem; border-radius: 999px; background: #ef4444; color: #fff; font: 800 .62rem/1.15rem var(--font-mono); text-align: center; }
.o-pane > .tiles:first-child, .o-pane > .panel:first-child { margin-top: 0; }
@media (min-width: 900px) { .o-pane .tiles { grid-template-columns: repeat(4, minmax(0, 1fr)); } .o-pane[data-pane="retention"] .tiles { grid-template-columns: repeat(6, minmax(0, 1fr)); } }
.o-todo { display: flex; flex-wrap: wrap; gap: .45rem; margin: 0 0 .8rem; }
.o-todo:empty { display: none; }
.o-chip { display: inline-flex; align-items: center; gap: .35rem; padding: .4rem .75rem; border-radius: 999px; border: 1px solid var(--outline); background: var(--surface); color: var(--prose-2); font: 700 .76rem var(--font-sans); }
button.o-chip { cursor: pointer; }
.o-chip.warn { border-color: rgba(251, 191, 36, .55); background: rgba(251, 191, 36, .12); color: var(--prose); }
.o-chip.warn:hover { background: rgba(251, 191, 36, .2); }
.o-link { padding: 0; border: 0; background: none; color: #818cf8; font: inherit; font-weight: 700; text-decoration: underline; cursor: pointer; }
.o-share { font-style: normal; font-size: .68rem; color: var(--prose-3); }
.o-read { margin: 0; padding: 0 0 0 1.1rem; display: grid; gap: .55rem; font-size: .84rem; line-height: 1.45; color: var(--prose-2); }
.o-read b { color: var(--prose); }
/* Joueurs par jour : une colonne par jour, les nouveaux empilés sur les revenus. */
.o-days { display: grid; grid-template-columns: repeat(30, minmax(0, 1fr)); gap: 3px; height: 11rem; padding-bottom: 1.1rem; }
.o-day { position: relative; height: 100%; display: flex; flex-direction: column; justify-content: flex-end; }
.o-day i { display: block; width: 100%; }
.o-day i.new, .o-legend i.new { background: #f472b6; }
.o-day i.back, .o-legend i.back { background: #6366f1; }
.o-day i:first-of-type { border-radius: 3px 3px 0 0; }
.o-day i.new[style*="height:0%"] + i.back { border-radius: 3px 3px 0 0; }
.o-day.partial i { opacity: .55; }
.o-day:hover i { filter: brightness(1.25); }
.o-day em { position: absolute; left: -.4rem; right: -.4rem; bottom: -1.1rem; text-align: center; font: 500 .6rem var(--font-mono); font-style: normal; color: var(--prose-3); }
.o-legend { display: flex; flex-wrap: wrap; align-items: center; gap: .4rem 1rem; margin-top: .6rem; font-size: .74rem; color: var(--prose-2); }
.o-legend span { display: inline-flex; align-items: center; gap: .35rem; }
.o-legend i { width: .7rem; height: .7rem; border-radius: 2px; }
/* Parcours : libellé, barre, nombre, part gardée. */
.o-funnel { display: grid; gap: .1rem; }
.o-step { display: grid; grid-template-columns: minmax(0, 12.5rem) 1fr 3rem 3.2rem; align-items: center; gap: .6rem; padding: .3rem 0; font-size: .8rem; }
.o-step .mono, .o-step .o-share { text-align: right; }
.o-step .o-name { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.o-funnel + .panel-note { margin-top: .6rem; }
/* Cohortes : une case par jour de retour, plus verte quand plus de joueurs sont revenus. */
.o-cohort { display: grid; grid-template-columns: 3.6rem 2.6rem repeat(9, minmax(2.5rem, 1fr)); gap: 3px; padding: 2px 0; min-width: 31rem; text-align: center; align-items: center; }
.o-cohort > span:first-child { text-align: left; }
.o-cohort.head { font-family: var(--font-sans); font-size: .64rem; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; color: var(--prose-3); padding-bottom: .3rem; }
.o-cell { padding: .32rem 0; border-radius: 4px; }
.o-cell.none { color: var(--prose-3); background: none; }
.o-tr.c7 { grid-template-columns: 3.2rem repeat(6, minmax(3.4rem, 1fr)); min-width: 30rem; }
.o-tr.c7 span { white-space: nowrap; }
@media (max-width: 640px) {
  .o-tabs { top: .25rem; }
  .o-tabs button { padding: .5rem .6rem; font-size: .7rem; }
  .o-days { gap: 2px; height: 9rem; }
  .o-step { grid-template-columns: 1fr 2.6rem 3rem; gap: .15rem .4rem; font-size: .76rem; }
  .o-step .o-name { grid-column: 1 / -1; white-space: normal; }
}
/* Boîte à idées du créateur : non lues en haut (liseré rouge), lues en dessous. */
.o-inbox-head { display: flex; align-items: center; justify-content: space-between; gap: .6rem; margin: 1rem 0 .2rem; }
.o-inbox-head:first-child { margin-top: 0; }
.o-inbox-title { margin: 0; font-size: .74rem; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; color: var(--prose-3); }
.o-inbox-title b { margin-left: .3rem; padding: 0 .4rem; border-radius: 999px; background: var(--surface-raised); color: var(--prose-2); font: 800 .68rem/1.2rem var(--font-mono); display: inline-block; }
.o-inbox-title.unread { color: var(--prose); }
.o-inbox-title.unread b { background: #ef4444; color: #fff; }
.idea-row.unread { border-left: 3px solid #ef4444; padding-left: .7rem; background: rgba(239, 68, 68, .06); border-radius: 0 .4rem .4rem 0; }
/* Classement du casino (onglet Gamble) : trois tableaux, une ligne par joueur. */
.g-top-tabs { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: .4rem; margin: 0 0 .7rem; }
.g-top-tabs button { display: flex; align-items: center; justify-content: center; gap: .4rem; padding: .55rem .4rem; border: 1px solid var(--outline); border-radius: .6rem; background: var(--surface); color: var(--prose-2); font: 800 .74rem var(--font-sans); letter-spacing: .02em; cursor: pointer; }
.g-top-tabs button i { font-style: normal; font-size: 1rem; line-height: 1; }
.g-top-tabs button:hover { color: var(--prose); border-color: var(--outline-strong); }
.g-top-tabs button.on { color: var(--prose); border-color: transparent; background: linear-gradient(var(--surface), var(--surface)) padding-box, linear-gradient(120deg, #fbbf24, #f472b6, #818cf8) border-box; }
.g-top-row { display: grid; grid-template-columns: 2.4rem minmax(0, 1fr) 4.5rem 6rem 6rem; align-items: center; gap: .6rem; padding: .45rem .5rem; border-top: 1px solid var(--outline); font-size: .84rem; text-align: right; }
.g-top-row > :nth-child(1), .g-top-row > :nth-child(2) { text-align: left; }
.g-top-row > * { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.g-top-row.head { border-top: 0; padding-top: 0; font-size: .64rem; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; color: var(--prose-3); }
.g-top-row.me { background: color-mix(in srgb, var(--chart-accent) 9%, transparent); border-radius: .4rem; }
.g-top-rank { font-family: var(--font-mono); color: var(--prose-3); }
.g-top-row b.up { color: #34d399; } .g-top-row b.down { color: #f87171; }
@media (max-width: 560px) {
  .g-top-tabs button { flex-direction: column; gap: .15rem; font-size: .62rem; padding: .5rem .2rem; }
  .g-top-row { grid-template-columns: 1.9rem minmax(0, 1fr) 5.2rem 4.9rem; gap: .35rem; font-size: .76rem; padding: .45rem .3rem; }
  .g-top-rounds { display: none; }
}
/* Duel : interrupteur « tirage auto » sous le bouton de la manche. */
.room-auto { display: inline-flex; align-items: center; gap: .45rem; margin-top: .5rem; font-size: .76rem; font-weight: 700; color: var(--prose-2); cursor: pointer; user-select: none; }
.room-auto[hidden] { display: none; }
.room-auto input { position: absolute; opacity: 0; width: 0; height: 0; }
.room-auto i { position: relative; width: 2rem; height: 1.1rem; border-radius: 999px; background: var(--surface-raised); border: 1px solid var(--outline-mid); transition: background .15s; }
.room-auto i::after { content: ''; position: absolute; top: 1px; left: 1px; width: calc(1.1rem - 4px); height: calc(1.1rem - 4px); border-radius: 50%; background: var(--prose-3); transition: transform .15s, background .15s; }
.room-auto input:checked + i { background: linear-gradient(120deg, #6366f1, #a855f7); border-color: transparent; }
.room-auto input:checked + i::after { transform: translateX(.9rem); background: #fff; }
.room-auto input:checked ~ span { color: var(--prose); }
.room-auto input:focus-visible + i { outline: 2px solid #818cf8; outline-offset: 2px; }
/* Page Owner vue par un invité : tout est lisible, les commandes sont retirées. */
.o-guest { margin: 0 0 .8rem; padding: .55rem .8rem; border: 1px solid rgba(129, 140, 248, .5); border-radius: .6rem; background: rgba(129, 140, 248, .1); font-size: .8rem; font-weight: 600; color: var(--prose); }
.o-guest[hidden] { display: none; }
.o-readonly .o-fund-forms, .o-readonly .o-reply, .o-readonly [data-o], .o-readonly .o-pending input, .o-readonly .o-pending button { display: none !important; }
.o-readonly .o-status { pointer-events: none; opacity: .8; }
.o-guest-only { display: none; } .o-readonly .o-guest-only { display: block; }
/* Suggestions : la conversation entre le joueur et le créateur, puis la zone de réponse. */
.idea-thread { display: grid; gap: .35rem; margin: .5rem 0 0; }
.idea-msg { margin: 0; padding: .45rem .7rem; border-radius: .5rem; font-size: .82rem; line-height: 1.4; max-width: 88%; overflow-wrap: anywhere; white-space: pre-wrap; }
.idea-msg b { display: block; font-size: .62rem; letter-spacing: .06em; text-transform: uppercase; margin-bottom: .1rem; color: var(--prose-3); }
.idea-msg i { display: block; margin-top: .15rem; font-style: normal; font-size: .62rem; color: var(--prose-3); }
.idea-msg.owner { justify-self: start; border-left: 3px solid var(--ep-outline); border-radius: 0 .5rem .5rem 0; background: var(--surface-dim); }
.idea-msg.owner b { color: var(--ep-text); }
.idea-msg.player { justify-self: end; background: color-mix(in srgb, var(--chart-accent) 14%, transparent); }
.idea-answer { display: flex; gap: .4rem; margin-top: .5rem; }
.idea-answer .input { flex: 1; min-width: 0; font-size: .82rem; text-transform: none; letter-spacing: 0; text-align: left; }
.idea-new { padding: .05rem .45rem; border-radius: 999px; background: #ef4444; color: #fff; font-size: .62rem; font-weight: 800; letter-spacing: .04em; text-transform: uppercase; }
/* Tirage auto en solo : même interrupteur que dans les duels, sous le bouton */
.hero .solo-auto { margin: .2rem auto .4rem; }
.solo-auto-row { display: flex; justify-content: center; margin-top: -.2rem; }
/* Badges Top 1 / 5 / 10 du classement du mois */
.top-mark { display: inline-flex; align-items: center; gap: .2rem; margin-left: .35rem; padding: .05rem .45rem; border-radius: 999px; font-size: .68rem; font-weight: 800; letter-spacing: .02em; white-space: nowrap; vertical-align: middle; border: 1px solid transparent; }
.top-mark.gold { color: #7a4b00; background: linear-gradient(120deg, #fde68a, #f59e0b, #fde68a); border-color: #d97706; box-shadow: 0 0 10px rgba(245, 158, 11, .45); }
.top-mark.silver { color: #374151; background: linear-gradient(120deg, #f3f4f6, #cbd5e1, #f3f4f6); border-color: #94a3b8; }
.top-mark.bronze { color: #5b2c0c; background: linear-gradient(120deg, #fed7aa, #d97706 60%, #fed7aa); border-color: #b45309; }
.top-marks-row { display: flex; flex-wrap: wrap; align-items: center; gap: .3rem; margin-bottom: .4rem; }
.top-marks-row .top-mark { margin-left: 0; }
/* Vitrine des badges du mois : à droite du classement sur grand écran, au-dessus sur petit écran */
.lb-wrap { position: relative; }
.lb-aside { margin-top: 1.4rem; padding: 1rem 1.1rem; }
.lb-aside .eyebrow { margin-bottom: .4rem; }
.lb-aside-lead { margin: 0 0 .7rem; font-size: .84rem; line-height: 1.45; color: var(--prose-2); }
.lb-aside-list { list-style: none; margin: 0 0 .7rem; padding: 0; display: grid; gap: .45rem; }
.lb-aside-list li { display: flex; align-items: center; justify-content: space-between; gap: .6rem; font-size: .8rem; font-weight: 700; color: var(--prose-2); }
.lb-aside-list .top-mark { margin-left: 0; font-size: .74rem; }
.lb-aside-foot { margin: 0; font-size: .76rem; line-height: 1.45; color: var(--prose-3); }
.lb-aside-foot b { color: var(--prose); }
@media (min-width: 84rem) {
  .lb-aside { position: absolute; top: 0; left: calc(100% + 1.75rem); width: 17rem; margin-top: 0; }
}
/* Mode performance (Joueur et réglages) : plus aucune animation décorative ni flou, sauf les chiffres qui tournent
   pendant un tirage. Les particules, secousses et signatures de skin sont coupées côté JS (reducedMotion). */
html.perf *:not(.slot), html.perf *::before, html.perf *::after { animation: none !important; transition-duration: .01s !important; transition-delay: 0s !important; }
html.perf .slot:not(.spinning) { animation: none !important; }
html.perf * { backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }
html.perf .rays, html.perf .vignette, html.perf .skin-fx-in, html.perf .skin-fx-out { display: none !important; }
/* Boîte de réception (page Owner) : un onglet par statut, des cartes qui se rangent d'un clic */
.o-inbox-tabs { display: flex; flex-wrap: wrap; gap: .35rem; margin-bottom: .7rem; }
.o-inbox-tabs button { display: inline-flex; align-items: center; gap: .3rem; padding: .35rem .65rem; border: 1px solid var(--outline); border-radius: 999px; background: var(--surface); color: var(--prose-2); font: 700 .76rem/1 inherit; cursor: pointer; }
.o-inbox-tabs button b { padding: 0 .38rem; border-radius: 999px; background: var(--surface-raised); font: 800 .68rem/1.15rem var(--font-mono); }
.o-inbox-tabs button.on { border-color: var(--prose); color: var(--prose); background: var(--surface-raised); }
.o-inbox-tabs button.hot b { background: #ef4444; color: #fff; }
.o-inbox-head { flex-wrap: wrap; }
.o-inbox-hint { margin: 0; }
.o-inbox-tools { display: flex; gap: .4rem; align-items: center; flex-wrap: wrap; }
.o-inbox-tools .input { width: 14rem; max-width: 100%; font-size: .8rem; text-transform: none; letter-spacing: 0; text-align: left; }
.idea-head .o-del { margin-left: auto; padding: .25rem .5rem; }
.o-moves { display: flex; flex-wrap: wrap; gap: .35rem; margin-top: .55rem; }
.o-moves .btn { padding: .3rem .6rem; font-size: .72rem; }
.o-pill { padding: .1rem .45rem; border-radius: 999px; font-size: .68rem; font-weight: 800; background: var(--surface-raised); color: var(--prose-2); }
.o-pill.reply { background: rgba(59, 130, 246, .15); color: #3b82f6; }
.o-pill.st-new { background: rgba(239, 68, 68, .15); color: #ef4444; }
.o-pill.st-planned { background: rgba(245, 158, 11, .18); color: #d97706; }
.o-pill.st-done { background: rgba(34, 197, 94, .15); color: #16a34a; }
.o-pill.st-declined { color: var(--prose-3); }
.idea-row[data-status="planned"] { border-left: 3px solid #f59e0b; padding-left: .7rem; }
.idea-row[data-status="done"] { border-left: 3px solid #22c55e; padding-left: .7rem; }
.idea-row[data-status="declined"] .idea-body { color: var(--prose-3); }
/* Code cadeau (Joueur et réglages) */
.code-form { display: flex; gap: .4rem; }
.code-form .input { flex: 1; min-width: 0; font-family: var(--font-mono); letter-spacing: .08em; text-transform: uppercase; }

/* Très petits téléphones : les 8 jetons du Plinko (1 et 5 en plus) tiennent sur la largeur, sans faire déborder la page. */
@media (max-width: 380px) {
  .gchips { gap: .25rem; flex-wrap: wrap; }
  .gchip { width: 1.95rem; height: 1.95rem; font-size: .62rem; border-width: 2px; }
}
/* Duel sur téléphone : les émotes restent accrochées juste au-dessus de la barre « Roll », elle-même accrochée en bas.
   Sans ça la barre passait par-dessus les émotes (on ne pouvait plus les toucher sans faire défiler). --room-bar-h est
   la hauteur réelle de la barre, mise à jour par le site à chaque affichage. */
@media (max-width: 720px) {
  .room-reacts { position: sticky; bottom: calc(var(--room-bar-h, 6rem) + .9rem); z-index: 14; width: fit-content; max-width: 100%; margin-inline: auto; padding: .3rem .45rem; border-radius: .9rem; background: color-mix(in srgb, var(--site-bg) 88%, transparent); backdrop-filter: blur(8px); }
}

/* Tirage auto en solo : l'interrupteur et, à côté, la rareté qui l'arrête. Avertissement dans la fenêtre des idées. */
.solo-auto-box { display: inline-flex; align-items: center; justify-content: center; flex-wrap: wrap; gap: .3rem .7rem; }
.solo-stop { display: inline-flex; align-items: center; gap: .35rem; font-size: .72rem; font-weight: 700; color: var(--prose-3); }
.solo-stop select { padding: .2rem .4rem; border: 1px solid var(--outline-mid); border-radius: .4rem; background: var(--surface); color: var(--prose); font: 700 .72rem var(--font-sans); }
.idea-warn { display: flex; gap: .45rem; margin: 0 0 .8rem; padding: .5rem .7rem; border: 1px solid rgba(251, 191, 36, .5); border-radius: .5rem; background: rgba(251, 191, 36, .1); font-size: .78rem; line-height: 1.4; color: var(--prose); }

/* ------------------------------------------------------------------ HellBorn : basalte noir, lave dans les fissures.
