  text-shadow: 0 0 .12em rgba(255, 255, 255, .9), 0 0 .35em rgba(196, 181, 253, .7), 0 .08em .25em rgba(0, 0, 0, .5);
  animation: haunt-float 3.2s ease-in-out infinite;
}
.skin-haunted .slot:nth-child(2n) { animation-delay: -1.6s; }
@keyframes haunt-float { 0%, 100% { transform: translateY(0); opacity: .9; } 50% { transform: translateY(-.05em); opacity: .65; } }
.skin-haunted .slot.ghost { opacity: .15; animation: none; }
.skin-haunted .slot.spinning { animation: haunt-flicker .12s steps(2) infinite; }
@keyframes haunt-flicker { from { opacity: .25; filter: blur(.04em); } to { opacity: .75; filter: none; } }
/* Il apparaît : sort de la brume (flou, transparent, plus grand) puis se fige, un frisson à la fin. */
.skin-haunted .slot.revealed { animation: haunt-appear .7s ease-out backwards, haunt-float 3.2s .7s ease-in-out infinite; }
@keyframes haunt-appear { 0% { transform: scale(1.35) translateY(-.15em); filter: blur(.12em); opacity: 0; } 60% { transform: scale(.96); filter: blur(0); opacity: .95; } 75% { transform: translateX(-.02em); } 88% { transform: translateX(.02em); } 100% { transform: none; } }
