@keyframes pumpkin-candle { 0%, 100% { color: #fff3b0; text-shadow: 0 0 .1em #fde047, 0 0 .3em #f59e0b, 0 0 .6em rgba(251, 146, 60, .9); } 42% { color: #fde68a; text-shadow: 0 0 .06em #fde047, 0 0 .2em #f59e0b, 0 0 .35em rgba(251, 146, 60, .6); } 47% { color: #fff7cc; text-shadow: 0 0 .14em #fef08a, 0 0 .4em #fbbf24, 0 0 .8em rgba(251, 146, 60, 1); } }
