.skin-pumpkin .slot.spinning { animation: pumpkin-carve .14s steps(2) infinite; }
@keyframes pumpkin-carve { from { transform: rotate(-4deg); color: #431407; text-shadow: none; } to { transform: rotate(4deg); color: #fde68a; } }
/* Il se pose : le couteau finit de creuser, la bougie s'allume d'un coup. */
.skin-pumpkin .slot.revealed { animation: pumpkin-light .6s ease-out backwards, pumpkin-candle 1.6s .6s ease-in-out infinite; }
@keyframes pumpkin-light { 0% { color: #431407; text-shadow: none; transform: scale(.85); } 45% { color: #fff; text-shadow: 0 0 .3em #fff, 0 0 .9em #fbbf24, 0 0 1.4em #f97316; transform: scale(1.12); } 100% { transform: none; } }
.skin-pumpkin .slot.collapsed { width: 0; height: 0; margin: 0; box-shadow: none; background: none; }
@media (prefers-reduced-motion: reduce) { .skin-pumpkin .slot { animation: none; } }
.side-pumpkin { --side-border: #ea580c; --side-glow: 0 0 18px rgba(249, 115, 22, .45); --side-ink: #fb923c;
  --side-bg: radial-gradient(ellipse 70% 40% at 50% 110%, rgba(234, 88, 12, .35), transparent 70%), linear-gradient(180deg, rgba(23, 10, 40, .55), rgba(67, 20, 7, .3));
  --deco-a: '🦇'; --deco-b: '🎃 🕯️'; }
.side-pumpkin::before { animation: bat-flap 1.8s ease-in-out infinite; }
@keyframes bat-flap { 0%, 100% { transform: translate(0, 0) scaleX(1); } 25% { transform: translate(4px, -4px) scaleX(.6); } 50% { transform: translate(8px, 0) scaleX(1); } 75% { transform: translate(4px, 3px) scaleX(.6); } }
.room-stage.many .side-pumpkin::before { animation: none; }

/* ------------------------------------------------------------------ Witch's Brew (Halloween 2026, limité) :
   une potion verte qui bouillonne dans le chaudron, des bulles traversent les chiffres. */
.num-card.skin-brew {
  background:
    radial-gradient(circle at 18% 70%, rgba(190, 242, 100, .55) 0 3%, transparent 4%), radial-gradient(circle at 70% 82%, rgba(190, 242, 100, .45) 0 2.5%, transparent 3.5%), radial-gradient(circle at 86% 40%, rgba(190, 242, 100, .35) 0 2%, transparent 3%),
    radial-gradient(ellipse 80% 55% at 50% 0%, rgba(132, 204, 22, .55), transparent 70%),
    linear-gradient(180deg, #1a2e05, #0b1402 70%, #050801);
  background-size: 100% 200%, 100% 200%, 100% 200%, 100% 100%, 100% 100%;
  border: 3px solid #27272a; border-radius: .9rem .9rem 1.6rem 1.6rem;
  box-shadow: 0 0 0 2px #52525b, inset 0 6px 14px rgba(163, 230, 53, .35), inset 0 -10px 16px rgba(0, 0, 0, .6), 0 0 24px rgba(132, 204, 22, .45);
  animation: brew-bubbles 3.2s linear infinite;
}
@keyframes brew-bubbles { from { background-position: 0 100%, 0 100%, 0 100%, 0 0, 0 0; } to { background-position: 0 -100%, 0 -60%, 0 -140%, 0 0, 0 0; } }
.skin-brew .slot {
  font-weight: 900; color: transparent;
  background: linear-gradient(180deg, #ecfccb, #bef264 40%, #84cc16 75%, #4d7c0f); -webkit-background-clip: text; background-clip: text;
  -webkit-text-stroke: .02em #1a2e05;
  filter: drop-shadow(0 0 .08em rgba(190, 242, 100, .9)) drop-shadow(0 0 .25em rgba(132, 204, 22, .6));
  animation: brew-wobble 2.4s ease-in-out infinite;
}
.skin-brew .slot:nth-child(2n) { animation-delay: -1.2s; }
@keyframes brew-wobble { 0%, 100% { transform: translateY(0) skewX(0); } 50% { transform: translateY(-.04em) skewX(-3deg); } }
.skin-brew .slot.ghost { opacity: .2; animation: none; }
.skin-brew .slot.spinning { animation: brew-boil .18s ease-in-out infinite alternate; }
@keyframes brew-boil { from { transform: translateY(.06em) scale(1.06, .9); filter: blur(.03em) drop-shadow(0 0 .2em #a3e635); } to { transform: translateY(-.06em) scale(.94, 1.08); } }
/* Il se pose : il remonte du fond du chaudron, éclate en surface et luit. */
.skin-brew .slot.revealed { animation: brew-surface .65s cubic-bezier(.3, 1.5, .5, 1) backwards, brew-wobble 2.4s .65s ease-in-out infinite; }
@keyframes brew-surface { 0% { transform: translateY(.5em) scale(.6); opacity: .3; filter: blur(.08em) drop-shadow(0 0 .4em #bef264); } 55% { transform: translateY(-.08em) scale(1.15, .9); opacity: 1; } 100% { transform: none; } }
.skin-brew .slot.collapsed { width: 0; height: 0; margin: 0; box-shadow: none; background: none; }
@media (prefers-reduced-motion: reduce) { .num-card.skin-brew, .skin-brew .slot { animation: none; } }
.side-brew { --side-border: #65a30d; --side-glow: 0 0 18px rgba(132, 204, 22, .4); --side-ink: #a3e635;
  --side-bg: radial-gradient(ellipse 60% 35% at 50% 108%, rgba(132, 204, 22, .35), transparent 70%), linear-gradient(180deg, rgba(20, 10, 35, .5), rgba(26, 46, 5, .35));
  --deco-a: '🧙'; --deco-b: '🧪 🕸️'; }

/* Onglet Limités : bannière de l'événement. */
.limited-banner { position: relative; overflow: hidden; display: flex; align-items: center; justify-content: space-between; gap: .6rem; flex-wrap: wrap; margin: 0 0 1rem; padding: .9rem 1.1rem; border-radius: .9rem; border: 1px solid rgba(249, 115, 22, .6);
  background: radial-gradient(circle at 97% 16%, #fef9c3 0 1.3%, rgba(254, 249, 195, .22) 2%, transparent 3.2%), linear-gradient(120deg, #1e0b45, #4c1d95 55%, #c2410c); color: #fff; box-shadow: 0 0 26px rgba(124, 58, 237, .35); }
.limited-banner b { font: 900 1.15rem var(--font-sans); letter-spacing: .04em; text-shadow: 0 0 12px rgba(249, 115, 22, .8); }
.limited-banner span { font: 800 .78rem var(--font-mono); color: #fed7aa; }
.limited-banner i { position: absolute; font-style: normal; font-size: 1rem; opacity: .85; animation: banner-bat 6s linear infinite; pointer-events: none; }
.limited-banner i:nth-of-type(2) { animation-delay: -2s; top: 30%; } .limited-banner i:nth-of-type(3) { animation-delay: -4s; top: 60%; }
@keyframes banner-bat { from { left: -5%; transform: translateY(0); } 50% { transform: translateY(-8px); } to { left: 105%; transform: translateY(0); } }
@media (prefers-reduced-motion: reduce) { .limited-banner i { animation: none; display: none; } }

/* Duel : sur un grand écran, le chat passe en colonne à droite, toujours visible pendant la partie. */
@media (min-width: 1100px) {
  .page.room-page { max-width: min(1320px, 96vw); }
  .room-layout { display: grid; grid-template-columns: minmax(0, 1fr) 21rem; gap: 1.2rem; align-items: start; }
  .room-aside { position: sticky; top: 4.6rem; }
  .room-aside .chat-panel { margin-top: 0; display: flex; flex-direction: column; }
  .room-aside .chat-list { max-height: calc(100vh - 15rem); min-height: 14rem; }
}
/* Classement du duel : le pseudo passe avant le titre (le titre ne garde que son icône), pour que les noms se lisent. */
.room-board .board-who .title-fx, .room-board .board-who .title-owner { font-size: 0; gap: 0; margin-left: .15rem; flex-shrink: 0; }
.room-board .board-who .title-fx i { font-size: .8rem; margin: 0; }
.room-board .board-who .title-owner:not(.title-fx)::before { font-size: .8rem; }
.room-board .board-who > a, .room-board .board-who > .bot-name { flex: 1 1 auto; min-width: 2.5rem; }
@media (max-width: 480px) { .room-board { grid-template-columns: 1fr; gap: .25rem; } .room-board .board-row { padding: .24rem .55rem; } }
/* Classement du duel sur ordinateur et tablette : le pseudo sur sa propre ligne (en entier), le score dessous. */
@media (min-width: 481px) {
  .room-board .board-row { flex-wrap: wrap; row-gap: .1rem; }
  .room-board .board-who { flex: 1 1 calc(100% - 1.6rem); }
  .room-board .board-metric { flex: 1 1 100%; justify-content: flex-start; padding-left: 1.2rem; }
}
/* Farces du créateur : sous le chat, dans la barre de droite (2026-10-14). */
.room-aside .prank-bar { margin-top: .6rem; }
.room-aside .prank-bar .prank-btn { flex: 1 1 auto; }
/* Plinko : choix Normal / High risk (15 rangées, 16 cases, 1000× aux bords). */
.pk-risk { display: flex; justify-content: center; gap: .4rem; margin: 0 0 .5rem; flex-wrap: wrap; }
.pk-risk-btn { border: 1px solid var(--outline); background: var(--surface); color: var(--prose-2); border-radius: 999px; padding: .3rem .8rem; font: 700 .68rem var(--font-sans, inherit); cursor: pointer; }
.pk-risk-btn.on { border-color: #f59e0b; color: var(--prose-1, inherit); box-shadow: 0 0 0 2px rgba(245, 158, 11, .35); }
.pk-risk-btn[data-risk="high"].on { border-color: #ef4444; box-shadow: 0 0 0 2px rgba(239, 68, 68, .4), 0 0 14px rgba(239, 68, 68, .35); }
.pk-slots[data-risk="high"] { grid-template-columns: repeat(16, 1fr); gap: 2px; }
.pk-slots[data-risk="high"] span { font-size: .5rem; letter-spacing: -.03em; }
.pk-slots span[data-m="top"] { background: linear-gradient(160deg, #fde047, #f97316 55%, #dc2626); color: #fff; text-shadow: 0 1px 2px rgba(0, 0, 0, .5); }
@media (max-width: 560px) { .pk-slots[data-risk="high"] span { font-size: .38rem; padding: .3rem 0; } }
/* Blackjack : assurance (as visible) et rappel des bonus 7-7-7 / 21 en 5, 6, 7 cartes. */
.bj-felt-bonus { text-align: center; font: 700 .5rem var(--font-sans); letter-spacing: .14em; color: rgba(253, 230, 138, .38); margin-top: -.3rem; }
.bj-ins { display: flex; align-items: center; justify-content: center; gap: .35rem; flex-wrap: wrap; flex-basis: 100%; padding: .4rem .6rem; border: 1px dashed rgba(245, 158, 11, .6); border-radius: .6rem; background: rgba(245, 158, 11, .08); }
.bj-ins b { font-size: .72rem; }
/* Boîte à idées : choix idée / bug, capture d'écran d'un bug (aperçu côté joueur, affichage côté créateur). */
.idea-kind { display: flex; margin: 0 0 .7rem; }
.idea-kind button { flex: 1; }
.idea-shot { display: flex; align-items: center; flex-wrap: wrap; gap: .4rem .6rem; margin: .5rem 0 0; }
.idea-shot-btn { cursor: pointer; }
/* jusqu'à 3 aperçus côte à côte (idée de Phong254, 2026-10-24) */
.idea-shots { flex-basis: 100%; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: .4rem; }
.idea-shots[hidden] { display: none; }
.idea-shot-prev { position: relative; min-width: 0; }
.idea-shot-prev img { display: block; width: 100%; height: 96px; object-fit: cover; border-radius: .5rem; border: 1px solid var(--outline); }
.idea-shot-prev button { position: absolute; top: .25rem; left: .25rem; padding: .1rem .4rem; background: var(--surface); }
.idea-shot-btn.disabled { opacity: .45; pointer-events: none; }
.o-shot img + img, .im-shot img + img { margin-top: .4rem; }
.o-pill.bug { background: rgba(239, 68, 68, .14); color: #ef4444; border-color: rgba(239, 68, 68, .4); }
.o-shot { margin: .3rem 0 .5rem; }
.o-shot img { display: block; max-width: min(100%, 320px); max-height: 220px; border-radius: .5rem; border: 1px solid var(--outline); cursor: zoom-in; }
.o-shot.big img { max-width: 100%; max-height: none; cursor: zoom-out; }
.idea-shot[hidden], .idea-shot-prev[hidden] { display: none; }
/* Crash en mode Pêche (collab Canne & Dauphins) : la scène en pixel art agrandie sans flou, le multiplicateur sur le côté. */
.cr-mode { display: flex; margin: 0 0 .6rem; }
.cr-mode button { flex: 1; }
#fish-canvas { display: none; image-rendering: pixelated; image-rendering: crisp-edges; }
.crash-screen[data-mode="fish"] #cr-canvas { display: none; }
.crash-screen[data-mode="fish"] #fish-canvas { display: block; width: 100%; height: auto; aspect-ratio: 16 / 9; }
.crash-screen[data-mode="fish"] { background: #3f8fe8; }
.crash-screen[data-mode="fish"] b { left: auto; right: 7%; top: 7%; transform: none; font-size: clamp(1.5rem, 6vw, 2.6rem); text-shadow: 0 2px 0 #14182c, 0 0 14px rgba(20, 24, 44, .6); }
.crash-screen[data-mode="fish"][data-state="idle"] b { opacity: 0; }
.crash-screen[data-mode="fish"][data-state="crash"] b { color: #ff6a6a; text-shadow: 0 2px 0 #2a0408, 0 0 14px rgba(42, 4, 8, .6); }
.crash-screen[data-mode="fish"][data-state="cash"] b { color: #7dffa4; text-shadow: 0 2px 0 #0b2a14, 0 0 14px rgba(11, 42, 20, .6); }
.fish-collab { text-align: center; margin-top: .4rem; }
.fish-collab a { color: #ff9a3c; font-weight: 700; }
/* Page Owner : joueurs amenés par un lien tagué (?ref=…). */
.o-src-players { padding: .5rem 0; border-top: 1px solid var(--outline); }
.o-src-players:first-of-type { border-top: 0; }
.o-src-names { display: flex; flex-wrap: wrap; gap: .3rem; margin-top: .35rem; }
/* Page Owner : encadré de la collab Pechadophin. */
.o-collab-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr)); gap: .6rem; margin-bottom: .6rem; }
.o-collab-k { display: flex; flex-direction: column; gap: .1rem; padding: .6rem .7rem; border: 1px solid var(--outline); border-radius: .6rem; background: var(--surface); }
.o-collab-k b { font-size: 1.4rem; }
/* Vérificateur d'XP (page Badges) : un résultat qui ne ressemble pas à un tirage. */
.xc-form { display: flex; gap: .5rem; margin-bottom: .6rem; }
.xc-form .input { flex: 1; max-width: 14rem; }
.xc-result { position: relative; border: 2px dashed var(--outline); border-radius: .7rem; padding: 1rem .8rem .8rem; text-align: center; background: repeating-linear-gradient(135deg, transparent 0 10px, rgba(127, 127, 127, .06) 10px 20px); }
.xc-sim { position: absolute; top: -.7rem; left: 50%; transform: translateX(-50%); padding: .1rem .55rem; border-radius: 999px; background: var(--surface); border: 1px solid var(--outline); font-size: .62rem; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; color: var(--prose-3); white-space: nowrap; }
.xc-num { font-size: clamp(1.8rem, 8vw, 2.6rem); font-weight: 700; letter-spacing: .12em; color: var(--prose-2); }
.xc-meta { display: flex; justify-content: center; align-items: center; flex-wrap: wrap; gap: .5rem; margin: .3rem 0 .6rem; }
.xc-badges { justify-content: center; }
.xc-ghost { opacity: .3; }
/* Pile ou face : une pièce qui tourne en 3D (∞ face, 🎲 pile), l'échelle des multiplicateurs en dessous. */
.cf-stage { display: grid; place-items: center; height: 11rem; perspective: 700px; margin: .4rem 0; }
.cf-coin { position: relative; width: 8rem; height: 8rem; transform-style: preserve-3d; }
.cf-face { position: absolute; inset: 0; border-radius: 50%; display: grid; place-items: center; backface-visibility: hidden; font-size: 3.2rem; font-weight: 900;
  background: radial-gradient(circle at 35% 30%, #fff6c2, #fbbf24 45%, #b45309); color: #7c2d12; box-shadow: inset 0 0 0 .45rem #f59e0b, inset 0 0 0 .6rem #92400e, 0 .6rem 1.4rem rgba(0, 0, 0, .35); }
.cf-tails { transform: rotateY(180deg); background: radial-gradient(circle at 35% 30%, #f1f5f9, #94a3b8 45%, #475569); box-shadow: inset 0 0 0 .45rem #cbd5e1, inset 0 0 0 .6rem #334155, 0 .6rem 1.4rem rgba(0, 0, 0, .35); }
.cf-ladder { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: .25rem; margin: 0 0 .7rem; }
.cf-ladder span { text-align: center; padding: .3rem 0; border-radius: .4rem; border: 1px solid var(--outline); font: 700 .62rem var(--font-mono); color: var(--prose-3); }
.cf-ladder span.on { background: #16a34a; border-color: #16a34a; color: #fff; }
.cf-ladder span.next { border-color: #f59e0b; color: #f59e0b; box-shadow: 0 0 0 2px rgba(245, 158, 11, .3); }
.cf-actions { justify-content: center; }
@media (max-width: 480px) { .cf-ladder span { font-size: .5rem; } }
#cf-cash[hidden] { display: none; }
/* Titres d'XP à vie : Centimillionaire (cyan glacé) et Billionaire (or massif, le reflet le plus visible du jeu). */
.title-fx.tt-centimillionaire { --owner-a: #0891b2 !important; --owner-b: #22d3ee !important; --owner-shine: #ecfeff !important; }
.title-fx.tt-billionaire { --owner-a: #a16207 !important; --owner-b: #facc15 !important; --owner-shine: #fffbeb !important; filter: drop-shadow(0 0 .35em rgba(250, 204, 21, .55)); }
.dark .title-fx.tt-billionaire, :root[data-theme="dark"] .title-fx.tt-billionaire { --owner-a: #facc15 !important; --owner-b: #fde68a !important; }

/* Codes cachés : à peine visibles, il faut les chercher. */
.hidden-code { margin-top: 2.5rem; text-align: right; font: 700 .62rem var(--font-mono); letter-spacing: .2em; color: var(--prose-3); opacity: .14; user-select: all; }
.hidden-code:hover { opacity: .5; }
.xc-secret { margin: .2rem 0 .5rem; font: 700 .72rem var(--font-mono); letter-spacing: .15em; color: #facc15; }

/* Niveaux (ligne en haut des quêtes du jour) et clés de caisse. */
.quest.level .quest-emoji { filter: drop-shadow(0 0 .3em rgba(250, 204, 21, .6)); }
.case-free[hidden] { display: none; }
.case-free { margin-top: .35rem; }

/* Route des récompenses de niveau. */
.quest.level { cursor: pointer; }
.level-road-link { display: block; margin-top: .15rem; font-size: .66rem; font-weight: 700; color: #f59e0b; }
.road { display: grid; gap: .3rem; max-height: min(60vh, 28rem); overflow-y: auto; padding-right: .2rem; }
.road-step { display: grid; grid-template-columns: 2.4rem 1fr auto 1.6rem; align-items: center; gap: .5rem; padding: .45rem .6rem; border: 1px solid var(--outline); border-radius: .55rem; background: var(--surface); font-size: .78rem; }
.road-n { font: 800 .9rem var(--font-mono); text-align: center; }
.road-x { color: var(--prose-3); font-size: .66rem; }
.road-s { text-align: center; }
.road-step.paid { opacity: .5; }
.road-step.ready { border-color: #22c55e; box-shadow: 0 0 0 2px rgba(34, 197, 94, .25); }
.road-step.next { border-color: #f59e0b; box-shadow: 0 0 0 2px rgba(245, 158, 11, .3); }
.road-step.key-starter { background: linear-gradient(90deg, rgba(245, 158, 11, .12), var(--surface)); }
.road-step.key-premium { background: linear-gradient(90deg, rgba(168, 85, 247, .2), var(--surface)); border-color: #a855f7; }
@media (max-width: 420px) { .road-step { grid-template-columns: 2rem 1fr 1.4rem; } .road-x { display: none; } }

/* Onglet Profil & amis : mon profil en résumé en haut. */
.me-panel .me-title { margin: -.2rem 0 .5rem; }
.me-tiles { margin-bottom: .6rem; }

.tile.tile-btn { cursor: pointer; text-align: left; font: inherit; color: inherit; }
.tile.tile-btn:hover { border-color: #f59e0b; }
.tile.tile-btn.ready { border-color: #22c55e; box-shadow: 0 0 0 2px rgba(34, 197, 94, .3); }
.road-catchup { margin-bottom: .5rem; grid-template-columns: 2.4rem 1fr 0 1.6rem; }
.title-fx.tt-codehunter { --owner-a: #ca8a04 !important; --owner-b: #facc15 !important; --owner-shine: #fef9c3 !important; }
.dark .title-fx.tt-codehunter, :root[data-theme="dark"] .title-fx.tt-codehunter { --owner-a: #facc15 !important; --owner-b: #fde68a !important; }

/* ------------------------------------------------------------------ Fonds d'écran animés (idée de MAYO, 2026-10-16).
   #wallpaper : un calque fixe derrière tout le site. Chaque fond = un dégradé + deux couches animées (::before, ::after)
   qui ne bougent que par transform / opacity (pas de nouveau dessin de l'écran à chaque image). Les aperçus de la
   boutique (.wall-preview) utilisent les mêmes classes. Coupé en mouvement réduit et en mode performance. */
#wallpaper { position: fixed; inset: 0; z-index: -1; pointer-events: none; overflow: hidden; }
.wall-preview { position: relative; width: 100%; align-self: stretch; box-sizing: border-box; height: 6.5rem; border-radius: .6rem; overflow: hidden; border: 1px solid var(--outline); margin-bottom: .5rem; }
.wall-preview.wp-none { background: var(--site-bg); }
.wp::before, .wp::after { content: ''; position: absolute; pointer-events: none; }

/* 🌌 Ciel étoilé : deux couches d'étoiles qui scintillent à contretemps et dérivent très lentement. */
.wp-stars { background: radial-gradient(ellipse at 70% 0%, #1e3a8a 0%, transparent 60%), linear-gradient(180deg, #0b1026 0%, #050816 100%); }
.wp-stars::before, .wp-stars::after { inset: -10%; background-size: 220px 220px;
  background-image: radial-gradient(1.4px 1.4px at 20px 30px, #fff 50%, transparent 52%), radial-gradient(1px 1px at 90px 160px, #fff 50%, transparent 52%), radial-gradient(1.6px 1.6px at 170px 70px, #dbeafe 50%, transparent 52%), radial-gradient(1px 1px at 130px 200px, #fff 50%, transparent 52%), radial-gradient(1.2px 1.2px at 60px 110px, #fef9c3 50%, transparent 52%); }
.wp-stars::before { animation: wp-twinkle 4s ease-in-out infinite, wp-drift 160s linear infinite; }
.wp-stars::after { background-size: 310px 310px; transform: rotate(17deg); animation: wp-twinkle 5.5s ease-in-out -2.7s infinite; }
@keyframes wp-twinkle { 0%, 100% { opacity: .45; } 50% { opacity: 1; } }
@keyframes wp-drift { from { transform: translate3d(0, 0, 0); } to { transform: translate3d(-220px, 110px, 0); } }

/* 🌅 Coucher de soleil : le soleil palpite doucement, une bande de nuages passe devant. */
.wp-sunset { background: linear-gradient(180deg, #1e1b4b 0%, #581c87 45%, #9d174d 75%, #c2410c 100%); }
.wp-sunset::before { left: 50%; bottom: -18vmin; width: 60vmin; height: 60vmin; margin-left: -30vmin; border-radius: 50%;
  background: radial-gradient(circle, #fde68a 0%, #fb923c 35%, rgba(251, 146, 60, .35) 55%, transparent 70%); animation: wp-sun 7s ease-in-out infinite; }
.wp-sunset::after { left: -640px; right: 0; bottom: 8%; height: 140px; background: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='640' height='140'><defs><filter id='b' x='-20%' y='-50%' width='140%' height='200%'><feGaussianBlur stdDeviation='9'/></filter></defs><g filter='url(%23b)' fill='%23581c87'><ellipse cx='90' cy='80' rx='80' ry='16' opacity='.55'/><ellipse cx='140' cy='66' rx='46' ry='18' opacity='.5'/><ellipse cx='380' cy='92' rx='110' ry='14' opacity='.45'/><ellipse cx='420' cy='78' rx='54' ry='17' opacity='.45'/><ellipse cx='575' cy='60' rx='60' ry='11' opacity='.4'/></g></svg>") 0 0 / 640px 140px repeat-x; animation: wp-clouds 70s linear infinite; }
