@keyframes wp-rise { from { transform: translate3d(0, 0, 0); } to { transform: translate3d(0, -300px, 0); } }

/* 🟣 Synthwave : un soleil rayé à l'horizon et une grille néon qui défile vers nous. */
.wp-synthwave { background: linear-gradient(180deg, #12002b 0%, #2e0a4f 50%, #4c0b5e 60%, #12002b 61%); }
.wp-synthwave::after { left: 50%; top: 22%; width: 34vmin; height: 34vmin; margin-left: -17vmin; border-radius: 50%;
  background: linear-gradient(180deg, #fde047 0%, #f97316 45%, #ec4899 100%); -webkit-mask: repeating-linear-gradient(180deg, #000 0 8%, transparent 8% 11%); mask: repeating-linear-gradient(180deg, #000 0 8%, transparent 8% 11%); filter: drop-shadow(0 0 2rem rgba(236, 72, 153, .7)); }
.wp-synthwave::before { left: -50%; right: -50%; top: 60%; height: 120%; transform-origin: 50% 0;
  background: repeating-linear-gradient(90deg, rgba(236, 72, 153, .75) 0 2px, transparent 2px 70px), repeating-linear-gradient(0deg, rgba(236, 72, 153, .75) 0 2px, transparent 2px 70px);
  animation: wp-grid 1.6s linear infinite; }
@keyframes wp-grid { from { transform: perspective(300px) rotateX(70deg) translate3d(0, 0, 0); } to { transform: perspective(300px) rotateX(70deg) translate3d(0, 70px, 0); } }

/* 🌸 Sakura : des pétales qui tombent en biais. Une seule couche (deux couches animées coûtaient trop : 19 images/s). */
.wp-sakura { background: radial-gradient(ellipse at 20% 0%, rgba(244, 114, 182, .35), transparent 60%), linear-gradient(180deg, #3b0a24 0%, #24081a 60%, #12040d 100%); }
