.wp-forest::after { left: 0; right: 0; bottom: 0; height: 26vmin;
  background: conic-gradient(from 150deg at 50% 0%, transparent 0 60deg, #021007 60deg 120deg, transparent 120deg) 0 100% / 9vmin 100% repeat-x, conic-gradient(from 155deg at 50% 0%, transparent 0 50deg, #031a0b 50deg 130deg, transparent 130deg) 4vmin 100% / 13vmin 80% repeat-x; }
.wp-forest::before { inset: -10%; background-size: 360px 280px;
  background-image: radial-gradient(3px 3px at 50px 200px, #fde047 40%, rgba(253, 224, 71, .25) 60%, transparent 70%), radial-gradient(2.5px 2.5px at 230px 90px, #facc15 40%, rgba(250, 204, 21, .25) 60%, transparent 70%), radial-gradient(3px 3px at 300px 230px, #fef08a 40%, rgba(254, 240, 138, .2) 60%, transparent 70%);
