@keyframes wp-flies { from { transform: translate3d(0, 0, 0); } to { transform: translate3d(360px, -280px, 0); } }

/* 🌌 Galaxie (idée d'un joueur, 2026-10-16) : une nébuleuse violette et des étoiles qui passent, deux couches à deux
   vitesses (les proches filent, les lointaines glissent). Tuiles SVG, comme Sakura, pour rester à 60 images/s. */
.wp-galaxy { background: radial-gradient(ellipse 60% 45% at 30% 35%, rgba(168, 85, 247, .35), transparent 70%), radial-gradient(ellipse 50% 40% at 75% 70%, rgba(45, 212, 191, .2), transparent 70%), radial-gradient(ellipse 35% 25% at 60% 30%, rgba(236, 72, 153, .18), transparent 70%), linear-gradient(180deg, #0a0420 0%, #05020f 100%); }
