@keyframes wp-pass-near { from { transform: translate3d(400px, 0, 0); } to { transform: translate3d(0, 0, 0); } }

/* 🪦 Cimetière au clair de lune et 🎃 Champ de citrouilles (Halloween 2026, idée de Deadshot, onglet Limités). */
.wp-graveyard { background: radial-gradient(circle at 75% 22%, #fefce8 0 3.2vmin, rgba(254, 252, 232, .35) 3.3vmin 6vmin, transparent 9vmin), linear-gradient(180deg, #1e1b4b 0%, #3b0764 55%, #1a0b2e 100%); }
.wp-graveyard::after { left: 0; right: 0; bottom: 0; height: 120px; background: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='360' height='120'><g fill='%230b0716'><path d='M20 120V70a22 22 0 0 1 44 0v50z'/><path d='M100 120V40h8V20h10v20h8v20h-8v60z'/><path d='M160 120V80a16 16 0 0 1 32 0v40z'/><path d='M230 120V60a26 26 0 0 1 52 0v60z'/><rect x='310' y='85' width='30' height='35' rx='4'/><rect x='0' y='112' width='360' height='8'/></g></svg>") 0 100% / 360px 120px repeat-x; }
