@keyframes wp-fog { from { transform: translate3d(-12%, 0, 0); } to { transform: translate3d(12%, 0, 0); } }
/* Pumpkin Patch (2026-10-26) : de temps en temps, une chauve-souris traverse l'écran en battant des ailes (une fois
   toutes les ~26 s, le reste du temps hors champ). Pas d'animation en mouvement réduit ni en mode performance. */
#wallpaper .wpp-bat { position: absolute; left: 0; top: 18%; width: 62px; height: 35px; pointer-events: none; opacity: 0;
  animation: wpp-bat-fly 26s linear 4s infinite; will-change: transform; }
#wallpaper .wpp-bat::before { content: ''; position: absolute; inset: 0; background: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 46 26'><path fill='%23140a1c' d='M23 9c-1-2-1-4 0-5l1 2 1-2c1 1 1 3 0 5 3 0 5 2 5 4 3-5 9-9 16-8-3 3-4 7-4 11-2-2-5-2-7 0-2-2-5-2-6 1-1-1-3-1-4 2-1-3-3-3-4-2-1-3-4-3-6-1-2-2-5-2-7 0 0-4-1-8-4-11 7-1 13 3 16 8 0-2 2-4 3-4z'/><circle cx='21.5' cy='10' r='.8' fill='%23fb923c'/><circle cx='24.5' cy='10' r='.8' fill='%23fb923c'/></svg>") center / contain no-repeat;
  filter: drop-shadow(0 0 1px rgba(253, 186, 116, .9)) drop-shadow(0 0 8px rgba(249, 115, 22, .6)); animation: wpp-bat-flap .22s ease-in-out infinite alternate; transform-origin: 50% 40%; }
@keyframes wpp-bat-fly {
  0% { opacity: 1; transform: translate3d(-60px, 0, 0); }
  4% { transform: translate3d(25vw, -4vh, 0); } 8% { transform: translate3d(50vw, 3vh, 0); }
  12% { transform: translate3d(75vw, -5vh, 0); } 16% { opacity: 1; transform: translate3d(calc(100vw + 60px), 1vh, 0); }
  16.01%, 100% { opacity: 0; transform: translate3d(calc(100vw + 60px), 1vh, 0); } }
@keyframes wpp-bat-flap { from { transform: scaleY(1); } to { transform: scaleY(-.35) translateY(-4px); } }
@media (prefers-reduced-motion: reduce) { #wallpaper .wpp-bat { display: none; } }
html.perf #wallpaper .wpp-bat { display: none; }

