@keyframes wp-tumble-sm { from { transform: translate3d(0, 0, 0); } to { transform: translate3d(-440px, 0, 0); } }
@keyframes wp-tumble { 0% { transform: translate3d(0, 0, 0); } 10% { transform: translate3d(-110px, -14px, 0); } 20% { transform: translate3d(-220px, 0, 0); }
  30% { transform: translate3d(-330px, -10px, 0); } 40% { transform: translate3d(-440px, 0, 0); } 50% { transform: translate3d(-550px, -16px, 0); }
