    url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 260 70'><path d='M10 30L250 30L240 66L20 66Z' fill='%23b45309'/><path d='M18 30L242 30L236 54L24 54Z' fill='%23fcd34d'/><path d='M40 32Q80 22 130 30T220 32' fill='%23fde68a'/><path d='M150 34L170 18L186 34Z' fill='%23ef4444'/><rect x='66' y='30' width='22' height='16' rx='3' fill='%233b82f6'/><path d='M62 30H92' stroke='%231d4ed8' stroke-width='3'/></svg>") center bottom calc(var(--gy) * .3) / auto calc(var(--s) * .3) no-repeat,
