  background: linear-gradient(100deg, transparent 20%, rgba(186, 230, 253, .12) 23%, transparent 27%, transparent 44%, rgba(186, 230, 253, .1) 47%, transparent 51%, transparent 66%, rgba(186, 230, 253, .14) 69%, transparent 73%);
