.wp-submarine::after { left: 0; right: 0; top: -300px; bottom: 0;
  background: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='300' height='300'><g fill='%23e0f2fe'><circle cx='231' cy='286' r='1.3' opacity='0.45'/><circle cx='260' cy='300' r='1' opacity='0.3'/><circle cx='262' cy='243' r='1.7' opacity='0.6'/><circle cx='95' cy='48' r='1.3' opacity='0.45'/><circle cx='72' cy='46' r='1.7' opacity='0.6'/><circle cx='21' cy='202' r='1.3' opacity='0.6'/><circle cx='80' cy='7' r='1.7' opacity='0.3'/><circle cx='30' cy='18' r='1' opacity='0.3'/><circle cx='15' cy='237' r='1.3' opacity='0.45'/><circle cx='100' cy='265' r='1' opacity='0.6'/><circle cx='150' cy='255' r='1' opacity='0.6'/><circle cx='43' cy='234' r='1.7' opacity='0.45'/><circle cx='208' cy='282' r='1' opacity='0.6'/><circle cx='130' cy='161' r='1' opacity='0.6'/><circle cx='147' cy='15' r='1' opacity='0.6'/><circle cx='55' cy='205' r='1' opacity='0.45'/><circle cx='197' cy='34' r='1' opacity='0.6'/><circle cx='0' cy='109' r='1' opacity='0.3'/><circle cx='240' cy='192' r='1.7' opacity='0.45'/><circle cx='214' cy='37' r='1.7' opacity='0.6'/><circle cx='101' cy='138' r='1.3' opacity='0.3'/><circle cx='159' cy='170' r='1' opacity='0.45'/><circle cx='60' cy='68' r='1' opacity='0.6'/><circle cx='51' cy='5' r='1' opacity='0.45'/><circle cx='249' cy='90' r='1.7' opacity='0.6'/><circle cx='96' cy='229' r='1.7' opacity='0.3'/></g></svg>") 0 0 / 300px 300px;
