/* aperçu de la boutique : le sous-marin est dessiné dans le fond (pas de calques dans les aperçus) */
.wall-preview.wp-submarine { background: var(--wpd-sub) 12% 22% / 62% auto no-repeat, url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1600 900' preserveAspectRatio='xMidYMax slice'><g fill='none' stroke-linecap='round' stroke-width='10'><path d='M180 800Q160 720 190 650T170 520' stroke='%23065f46'/><path d='M215 805Q240 730 210 670T235 560' stroke='%23047857'/><path d='M1380 810Q1360 740 1395 680T1375 580' stroke='%23065f46'/><path d='M1420 812Q1440 760 1415 700' stroke='%23047857'/><path d='M640 800Q630 760 650 720' stroke='%23065f46'/></g><path d='M0 790Q200 750 420 780T860 772T1300 760T1600 784V900H0Z' fill='%231e293b'/><path d='M0 820Q260 790 520 812T1040 806T1600 812V900H0Z' fill='%23334155'/><g fill='%230f172a'><path d='M300 820Q330 760 400 770Q450 790 440 822Z'/><path d='M1080 812Q1120 740 1200 756Q1250 780 1236 816Z'/><path d='M900 828Q910 806 940 808Q960 816 958 830Z'/></g><g fill='%23f97316' opacity='.85'><path d='M520 812q-6-30 6-40q-2 20 8 28q4-18 14-22q-6 18 0 34Z'/><path d='M1500 808q-8-26 4-38q0 18 8 24q2-16 12-20q-4 18 0 32Z'/></g><g fill='%23fde68a' opacity='.5'><circle cx='760' cy='842' r='3'/><circle cx='1300' cy='850' r='2.5'/><circle cx='120' cy='856' r='2.5'/></g><g transform='translate(700 790)'><rect x='0' y='16' width='70' height='34' rx='4' fill='%2378350f'/><path d='M0 18Q35-6 70 18Z' fill='%2392400e'/><rect x='30' y='20' width='10' height='12' fill='%23facc15'/></g></svg>") center bottom / 100% 100% no-repeat, linear-gradient(180deg, #0369a1 0%, #0c4a6e 45%, #020617 100%); }

/* le sous-marin (vrai fond seulement) : il patrouille en haut (animation sur transform) ; la plongée passe par les
   propriétés translate / rotate, en transition, pour ne jamais casser la patrouille */
#wallpaper.wp-submarine i { position: absolute; pointer-events: none; }
#wallpaper .wpd-sub { --w: min(50vw, 460px); left: 6%; top: 9%; width: var(--w); aspect-ratio: 520 / 140;
  background: var(--wpd-sub) center / contain no-repeat;
  translate: 0 0; rotate: 0deg; transition: translate 3s cubic-bezier(.4, 0, .3, 1), rotate 2s ease-in-out;
  animation: wpd-patrol 16s ease-in-out infinite alternate; }
@keyframes wpd-patrol { 0% { transform: translate3d(-3vw, 0, 0) rotate(-1deg); } 50% { transform: translate3d(5vw, 1.6vh, 0) rotate(1deg); } 100% { transform: translate3d(14vw, 0, 0) rotate(-.5deg); } }
/* pendant le tirage : il pique du nez et descend lentement */
#wallpaper.wp-submarine[data-dive] .wpd-sub { translate: 0 26vh; rotate: 7deg; transition: translate 7s cubic-bezier(.45, 0, .55, 1), rotate 1.2s ease-out; }
/* Mythic+ : plongeon jusqu'au fond (bas de la coque à 88 % de l'écran), il se pose à plat */
