@media (orientation: portrait) { #wallpaper .wcm-pow { left: 1%; top: 47%; } #wallpaper .wcm-bam { right: 1%; top: 64%; } #wallpaper .wcm-dots { left: auto; right: 6%; top: 36%; } #wallpaper .wcm-boom { bottom: 6%; } }
#wallpaper.wp-comicpage:is([data-react="landwaste"], [data-react="garbage"], [data-react="trash"], [data-react="common"]) .wcm-dots { animation: wcm-pop 1.8s both; }
#wallpaper.wp-comicpage:is([data-react="uncommon"], [data-react="rare"], [data-react="epic"], [data-react="anomaly"], [data-react="mythic"], [data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wcm-pow { animation: wcm-pop 2.8s both; }
#wallpaper.wp-comicpage:is([data-react="anomaly"], [data-react="mythic"], [data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wcm-bam { animation: wcm-pop-r 2.8s .3s both; }
#wallpaper.wp-comicpage:is([data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wcm-boom { animation: wcm-boom 3.6s .55s both; }
#wallpaper.wp-comicpage:is([data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wcm-flash { animation: wcm-flash 1.4s .6s ease-out both; }
#wallpaper.wp-comicpage:is([data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wcm-page { animation: wcm-shake .5s .6s steps(1) both; }
/* élan (rapetisse), coup (gros et penché), rebond, puis il reste un moment et s'envole */
@keyframes wcm-pop { 0% { opacity: 0; transform: scale(.2) rotate(-25deg); animation-timing-function: cubic-bezier(.2, 1.5, .4, 1); } 14% { opacity: 1; transform: scale(1.18) rotate(6deg); }
  24% { transform: scale(.94) rotate(-3deg); } 34% { transform: scale(1.03) rotate(1deg); } 42%, 78% { opacity: 1; transform: scale(1) rotate(0deg); } 100% { opacity: 0; transform: scale(1.12) rotate(4deg); } }
@keyframes wcm-pop-r { 0% { opacity: 0; transform: scale(.2) rotate(25deg); animation-timing-function: cubic-bezier(.2, 1.5, .4, 1); } 14% { opacity: 1; transform: scale(1.18) rotate(-6deg); }
  24% { transform: scale(.94) rotate(3deg); } 34% { transform: scale(1.03) rotate(-1deg); } 42%, 78% { opacity: 1; transform: scale(1) rotate(0deg); } 100% { opacity: 0; transform: scale(1.12) rotate(-4deg); } }
@keyframes wcm-boom { 0% { opacity: 0; transform: scale(.1); animation-timing-function: cubic-bezier(.2, 1.4, .4, 1); } 12% { opacity: 1; transform: scale(1.12) rotate(-2deg); } 22% { transform: scale(.96) rotate(1deg); }
  32%, 80% { opacity: 1; transform: scale(1) rotate(0deg); } 100% { opacity: 0; transform: scale(1.06); } }
@keyframes wcm-flash { 0% { opacity: 0; } 12% { opacity: 1; } 100% { opacity: 0; } }
@keyframes wcm-shake { 0% { transform: translate(6px, -4px); } 20% { transform: translate(-7px, 5px); } 40% { transform: translate(5px, 6px); } 60% { transform: translate(-4px, -5px); } 80% { transform: translate(2px, 2px); } 100% { transform: none; } }
@media (prefers-reduced-motion: reduce) {
  #wallpaper.wp-comicpage :is(i, b)::before, #wallpaper.wp-comicpage i { animation: none !important; transition: opacity .6s; }
  #wallpaper.wp-comicpage:is([data-react="uncommon"], [data-react="rare"], [data-react="epic"], [data-react="anomaly"], [data-react="mythic"], [data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wcm-pow, #wallpaper.wp-comicpage:is([data-react="anomaly"], [data-react="mythic"], [data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wcm-bam, #wallpaper.wp-comicpage:is([data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wcm-boom { opacity: 1; } }
html.perf #wallpaper.wp-comicpage b::before, html.perf #wallpaper.wp-comicpage .wcm-page { animation: none !important; }

/* 🕳️ Black Hole, fond légendaire (idée de Big Sexy et jjcoolcid1, 2026-10-27), assorti au skin Singularity (id
   « accretion » : « blackhole » est déjà le skin). Un trou noir au milieu de la Voie lactée. Le fond : l'espace profond ;
   ::before, les étoiles et la bande de la Voie lactée qui tournent très lentement autour du trou ; ::after, en thème clair,
   un voile pâle en haut pour garder le texte lisible. Sur le vrai fond, dans l'ordre : la lueur, l'arc de lumière déviée
   au-dessus du trou, le disque d'accrétion (arrière), le trou et son anneau de photons, puis la moitié avant du disque
   (même disque, coupé en deux) ; le disque tourne en continu (u) et un calque (b) ajoute des tours entiers à la
   révélation : 0 pour un Common, jusqu'à 6 pour un Infinite, avec un flou de vitesse au plus fort. Après chaque tirage,
   des traînées de lumière de la couleur de la rareté s'enroulent dans le trou, et l'anneau s'allume quand elles arrivent.
   Mouvement réduit / mode performance : rien ne tourne, la réaction n'est que la lueur. */
