#wallpaper .wbh-swoop b { background: rgb(var(--wbh-c, 255, 237, 213)); -webkit-mask: var(--wbh-spiral) center / contain no-repeat; mask: var(--wbh-spiral) center / contain no-repeat; opacity: 0; }
/* réaction : la couleur des traînées (pâle pour les tirages courants), puis les tours en plus selon la rareté */
#wallpaper.wp-accretion[data-react] { --wbh-c: var(--wr); }
#wallpaper.wp-accretion:is([data-react="landwaste"], [data-react="garbage"], [data-react="trash"], [data-react="common"]) { --wbh-c: 254, 215, 170; }
#wallpaper.wp-accretion[data-react] .wbh-swoop b { animation: wbh-swoop 2.4s cubic-bezier(.5, 0, .9, .6) both; }
#wallpaper.wp-accretion:is([data-react="landwaste"], [data-react="garbage"], [data-react="trash"], [data-react="common"]) .wbh-swoop b { animation-name: wbh-swoop-soft; }
#wallpaper.wp-accretion[data-react] .wbh-flare { animation: wbh-flare 2.6s ease-out .1s both; }
@keyframes wbh-swoop { 0% { opacity: 0; transform: rotate(0deg) scale(1.5); } 25% { opacity: .85; } 85% { opacity: .7; } 100% { opacity: 0; transform: rotate(250deg) scale(.14); } }
@keyframes wbh-swoop-soft { 0% { opacity: 0; transform: rotate(0deg) scale(1.4); } 30% { opacity: .35; } 100% { opacity: 0; transform: rotate(230deg) scale(.16); } }
@keyframes wbh-flare { 0%, 70% { opacity: 0; transform: scale(1); } 82% { opacity: 1; transform: scale(1.08); } 100% { opacity: 0; transform: scale(1.02); } }
#wallpaper.wp-accretion[data-react="uncommon"] .wbh-disc b { animation: wbh-boost-1 6s cubic-bezier(.5, 0, .3, 1) both; }
#wallpaper.wp-accretion[data-react="rare"] .wbh-disc b { animation: wbh-boost-1 6s cubic-bezier(.5, 0, .3, 1) both; }
#wallpaper.wp-accretion[data-react="epic"] .wbh-disc b { animation: wbh-boost-2 6s cubic-bezier(.5, 0, .3, 1) both; }
#wallpaper.wp-accretion[data-react="anomaly"] .wbh-disc b { animation: wbh-boost-2 6s cubic-bezier(.5, 0, .3, 1) both; }
#wallpaper.wp-accretion[data-react="mythic"] .wbh-disc b { animation: wbh-boost-3 6s cubic-bezier(.5, 0, .3, 1) both; }
#wallpaper.wp-accretion[data-react="celestial"] .wbh-disc b { animation: wbh-boost-4 6s cubic-bezier(.5, 0, .3, 1) both; }
#wallpaper.wp-accretion[data-react="divine"] .wbh-disc b { animation: wbh-boost-5 6s cubic-bezier(.5, 0, .3, 1) both; }
#wallpaper.wp-accretion[data-react="godlike"] .wbh-disc b { animation: wbh-boost-5 6s cubic-bezier(.5, 0, .3, 1) both; }
#wallpaper.wp-accretion[data-react="infinite"] .wbh-disc b { animation: wbh-boost-6 6s cubic-bezier(.5, 0, .3, 1) both; }
@keyframes wbh-boost-1 { to { transform: rotate(360deg); } }
@keyframes wbh-boost-2 { to { transform: rotate(720deg); } }
@keyframes wbh-boost-3 { to { transform: rotate(1080deg); } }
@keyframes wbh-boost-4 { to { transform: rotate(1440deg); } }
@keyframes wbh-boost-5 { to { transform: rotate(1800deg); } }
@keyframes wbh-boost-6 { to { transform: rotate(2160deg); } }
#wallpaper.wp-accretion:is([data-react="epic"], [data-react="anomaly"], [data-react="mythic"], [data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wbh-disc s { animation: wbh-blur 6s ease-in-out both; }
#wallpaper.wp-accretion:is([data-react="mythic"], [data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wbh-glow { animation: wbh-glow 6s ease-out both; }
#wallpaper.wp-accretion:is([data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wbh-lens { animation: wbh-lens 6s ease-out both; }
@keyframes wbh-blur { 0%, 10% { opacity: 0; } 45% { opacity: .55; } 90%, 100% { opacity: 0; } }
@keyframes wbh-glow { 0% { opacity: .8; transform: scale(1); } 30% { opacity: 1; transform: scale(1.18); } 100% { opacity: .8; transform: scale(1); } }
@keyframes wbh-lens { 0% { transform: scale(1); } 30% { transform: scale(1.07); } 100% { transform: scale(1); } }
@media (prefers-reduced-motion: reduce) { #wallpaper.wp-accretion :is(i, b, u, s) { animation: none !important; } }
html.perf #wallpaper.wp-accretion :is(i, b, u, s) { animation: none !important; }

/* 🏙️ City Heights (idée d'ichi et JBearr12, 2026-10-27) : la ville vue depuis les toits. Le fond : le ciel (nuit étoilée
   et lune en thème sombre, crépuscule en thème clair) et les tours lointaines, pâles ; ::before, une nappe de brume qui
   passe entre elles ; ::after, deux rangées d'immeubles plus proches, fenêtres allumées (tuiles répétées en largeur,
   leur taille suit la hauteur de l'écran). Sur le vrai fond : des nuages, des fenêtres qui s'allument et s'éteignent,
