.wall-preview.wp-city { --wct-far: 80%; --wct-mid: 62%; --wct-near: 32%; }
.wall-preview.wp-city::before { right: -350px; height: 30%; background-size: 350px 100%; animation-name: wct-mist-sm; }
@keyframes wct-mist-sm { to { transform: translate3d(-350px, 0, 0); } }
/* calques du vrai fond : au-dessus des immeubles (z-index 2) sauf les nuages */
#wallpaper.wp-city i { position: absolute; pointer-events: none; z-index: 2; }
#wallpaper .wct-clouds { z-index: 0; left: 0; right: -1600px; top: 4%; height: 26%; opacity: .5; background: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='1600' height='240'><defs><filter id='b' x='-.2' y='-.6' width='1.4' height='2.2'><feGaussianBlur stdDeviation='9'/></filter></defs><g fill='%23c7d2fe' filter='url(%23b)'><ellipse cx='240' cy='90' rx='150' ry='18'/><ellipse cx='290' cy='76' rx='60' ry='18'/><ellipse cx='900' cy='140' rx='190' ry='16'/><ellipse cx='1350' cy='60' rx='120' ry='14'/></g></svg>") 0 0 / 1600px 100% repeat-x; animation: wct-clouds 160s linear infinite; }
html:not(.dark) #wallpaper .wct-clouds { opacity: .9; background-image: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='1600' height='240'><defs><filter id='b' x='-.2' y='-.6' width='1.4' height='2.2'><feGaussianBlur stdDeviation='9'/></filter></defs><g fill='%23ffffff' filter='url(%23b)'><ellipse cx='240' cy='90' rx='150' ry='18'/><ellipse cx='290' cy='76' rx='60' ry='18'/><ellipse cx='900' cy='140' rx='190' ry='16'/><ellipse cx='1350' cy='60' rx='120' ry='14'/></g></svg>"); }
@keyframes wct-clouds { to { transform: translate3d(-1600px, 0, 0); } }
#wallpaper :is(.wct-flA, .wct-flB, .wct-beacons) { inset: 0; background: 0 100% / auto var(--wct-mid) repeat-x; }
#wallpaper .wct-flA { background-image: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1000 420'><g fill='%23fde68a'><rect x='3' y='361.3' width='6' height='8'/><rect x='75' y='327.3' width='6' height='8'/><rect x='171' y='191.3' width='6' height='8'/><rect x='231' y='378.3' width='6' height='8'/><rect x='387' y='55.3' width='6' height='8'/><rect x='459' y='378.3' width='6' height='8'/><rect x='567' y='395.3' width='6' height='8'/><rect x='759' y='174.3' width='6' height='8'/><rect x='843' y='327.3' width='6' height='8'/><rect x='903' y='310.3' width='6' height='8'/></g></svg>"); animation: wct-flick 9s steps(1) infinite; }
#wallpaper .wct-flB { background-image: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1000 420'><g fill='%23bae6fd'><rect x='15' y='327.3' width='6' height='8'/><rect x='75' y='310.3' width='6' height='8'/><rect x='171' y='208.3' width='6' height='8'/><rect x='255' y='225.3' width='6' height='8'/><rect x='327' y='259.3' width='6' height='8'/><rect x='495' y='327.3' width='6' height='8'/><rect x='627' y='191.3' width='6' height='8'/><rect x='723' y='293.3' width='6' height='8'/><rect x='891' y='191.3' width='6' height='8'/></g></svg>"); animation: wct-flick 13s steps(1) -5s infinite reverse; }
@keyframes wct-flick { 0% { opacity: 0; } 18% { opacity: 1; } 31% { opacity: 0; } 52% { opacity: .8; } 60% { opacity: 0; } 77% { opacity: 1; } 92% { opacity: 0; } }
#wallpaper .wct-beacons { background-image: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1000 420'><g fill='%23ef4444'><circle cx='174.5' cy='100' r='6' opacity='.35'/><circle cx='174.5' cy='100' r='2.6'/><circle cx='526.5' cy='206' r='6' opacity='.35'/><circle cx='526.5' cy='206' r='2.6'/><circle cx='991.5' cy='184' r='6' opacity='.35'/><circle cx='991.5' cy='184' r='2.6'/></g></svg>"); animation: wct-blink 2.4s ease-in-out infinite; }
@keyframes wct-blink { 0%, 100% { opacity: .15; } 50% { opacity: 1; } }
/* l'avion : traverse en haut de droite à gauche en montant un peu, feux qui clignotent */
#wallpaper .wct-plane { left: 0; top: 8%; width: min(8vmin, 64px); aspect-ratio: 3; background: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 120 40'><path fill='%231e1b4b' d='M4 20q0-4 8-4h70l18-14h8l-10 14h14q6 0 6 4t-6 4H98l10 14h-8L82 24H12q-8 0-8-4z'/><path fill='%231e1b4b' d='M40 16l10-12h6l-6 12zM40 24l10 12h6l-6-12z'/></svg>") center / contain no-repeat; translate: 110vw 0; animation: wct-plane 58s linear -20s infinite; }
html:not(.dark) #wallpaper .wct-plane { filter: brightness(1.6); }
#wallpaper .wct-plane::before, #wallpaper .wct-plane::after { content: ''; position: absolute; width: 4px; height: 4px; border-radius: 50%; }
#wallpaper .wct-plane::before { left: 4%; top: 42%; background: #fff; box-shadow: 0 0 6px 2px rgba(255, 255, 255, .8); animation: wct-strobe 1.2s steps(1) infinite; }
#wallpaper .wct-plane::after { left: 62%; top: 4%; background: #ef4444; box-shadow: 0 0 6px 2px rgba(239, 68, 68, .7); animation: wct-strobe 1.2s steps(1) -.6s infinite; }
@keyframes wct-strobe { 0% { opacity: 1; } 15% { opacity: 0; } }
@keyframes wct-plane { 0% { translate: 110vw 3vh; } 55%, 100% { translate: -15vw -2vh; } }
/* l'hélicoptère : traverse plus bas de gauche à droite en se balançant, rotor flou et projecteur qui balaie */
#wallpaper .wct-heli { left: 0; top: 30%; width: min(14vmin, 120px); aspect-ratio: 140 / 60; translate: -20vw 0; animation: wct-heli 76s linear -6s infinite; }
#wallpaper .wct-heli b { position: absolute; inset: 0; background: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 140 60'><g fill='%23111827'><path d='M30 30q0-16 22-16h22q14 0 18 14l2 8q0 6-8 6H42q-12 0-12-12z'/><path d='M90 26h40l6-8h4l-4 14H92z'/><rect x='56' y='6' width='4' height='8'/><path d='M40 46h50v3H40zM48 42h3v5h-3zM78 42h3v5h-3z'/></g><path fill='%2393c5fd' opacity='.6' d='M36 28q2-10 14-10h8v12H36z'/></svg>") center / contain no-repeat; animation: wct-bob 3s ease-in-out infinite alternate; }
#wallpaper .wct-heli b::before { content: ''; position: absolute; left: 12%; top: 6%; width: 76%; height: 5%; border-radius: 50%; background: rgba(148, 163, 184, .8); animation: wct-rotor .12s linear infinite alternate; }
#wallpaper .wct-heli u { position: absolute; left: 30%; top: 70%; width: 300%; height: 600%; margin-left: -100%; transform-origin: 50% 0;
  background: linear-gradient(180deg, rgba(254, 249, 195, .4), rgba(254, 249, 195, .12) 50%, transparent 85%); clip-path: polygon(46% 0, 54% 0, 100% 100%, 0 100%); animation: wct-sweep 5s ease-in-out infinite alternate; }
html:not(.dark) #wallpaper .wct-heli u { opacity: .55; }
@keyframes wct-heli { 0% { translate: -20vw 0; } 45%, 100% { translate: 115vw -4vh; } }
@keyframes wct-bob { from { transform: translateY(-4px) rotate(-3deg); } to { transform: translateY(4px) rotate(2deg); } }
@keyframes wct-rotor { from { transform: scaleX(1); } to { transform: scaleX(.35); } }
@keyframes wct-sweep { from { transform: rotate(-16deg); } to { transform: rotate(14deg); } }
@media (prefers-reduced-motion: reduce) { #wallpaper.wp-city :is(i, b, u), #wallpaper.wp-city :is(i, b)::before, #wallpaper.wp-city i::after { animation: none !important; } #wallpaper :is(.wct-plane, .wct-heli) { display: none; } }
html.perf #wallpaper.wp-city :is(i, b, u), html.perf #wallpaper.wp-city :is(i, b)::before { animation: none !important; }
html.perf #wallpaper :is(.wct-plane, .wct-heli) { display: none; }

/* 🌴 Jungle (idée d'ichi, 2026-10-27) : la forêt tropicale en couches. Le fond : la lumière qui perce la brume (douce
   le soir en thème sombre, claire le jour en thème clair) et deux rangées de feuillage lointain ; ::before, des rayons
   de soleil qui se balancent ; ::after, des poussières de lumière qui montent. Sur le vrai fond : de grandes feuilles
   dans les quatre coins qui bougent au vent (rotation autour de leur tige), trois lianes, et de temps en temps un
