/* calques du vrai fond */
#wallpaper.wp-jungle i { position: absolute; pointer-events: none; background-position: center; background-size: contain; background-repeat: no-repeat; }
#wallpaper .wjg-tl { left: -2%; top: -2%; width: min(46vw, 620px); aspect-ratio: 600 / 520; background-image: var(--wjg-tl); transform-origin: 0 0; animation: wjg-sway 8s ease-in-out infinite alternate; }
