#wallpaper .wjg-bl { left: -3%; bottom: -3%; width: min(40vw, 520px); aspect-ratio: 520 / 420; background-image: var(--wjg-bl); transform-origin: 0 100%; animation: wjg-sway-up 7s ease-in-out -2s infinite alternate; }
