#wallpaper :is(.wjg-tr, .wjg-br) b { position: absolute; inset: 0; background: var(--wjg-tl) center / contain no-repeat; transform: scaleX(-1); }
#wallpaper .wjg-br b { background-image: var(--wjg-bl); }
@media (orientation: portrait) { #wallpaper .wjg-tl { width: 74vw; top: 2%; } #wallpaper .wjg-tr { width: 58vw; top: 1%; } #wallpaper .wjg-bl { width: 72vw; } #wallpaper .wjg-br { width: 76vw; } }
