@keyframes wrb-fall { from { transform: translate3d(0, 0, 0); } to { transform: translate3d(-104px, 520px, 0); } }
/* réactions (la pluie garde sa chute : on n'ajoute que des animations sur d'autres propriétés) */
#wallpaper.wp-rainrainbow:is([data-react="uncommon"]) .wrb-sky { animation: wrb-peek 5s ease-in-out both; }
#wallpaper.wp-rainrainbow:is([data-react="uncommon"]) .wrb-sun { animation: wrb-peek 5s ease-in-out both; }
#wallpaper.wp-rainrainbow:is([data-react="uncommon"]) .wrb-rain { animation: wrb-fall 1s linear infinite, wrb-lighter 5s ease-in-out both; }
@keyframes wrb-peek { 0% { opacity: 0; } 35% { opacity: .45; } 60% { opacity: .45; } 100% { opacity: 0; } }
@keyframes wrb-lighter { 0% { opacity: 1; } 35% { opacity: .35; } 60% { opacity: .35; } 100% { opacity: 1; } }
#wallpaper.wp-rainrainbow:is([data-react="rare"], [data-react="epic"], [data-react="anomaly"], [data-react="mythic"], [data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) :is(.wrb-sky, .wrb-lit) { animation: wrb-clear var(--wrb-d) ease-in-out both; }
#wallpaper.wp-rainrainbow:is([data-react="rare"], [data-react="epic"], [data-react="anomaly"], [data-react="mythic"], [data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wrb-sun { animation: wrb-sun var(--wrb-d) ease-in-out both; }
#wallpaper.wp-rainrainbow:is([data-react="rare"], [data-react="epic"], [data-react="anomaly"], [data-react="mythic"], [data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wrb-bow { animation: wrb-bow var(--wrb-d) ease-in-out both; }
#wallpaper.wp-rainrainbow:is([data-react="anomaly"], [data-react="mythic"], [data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wrb-bow2 { animation: wrb-bow2 var(--wrb-d) ease-in-out both; }
#wallpaper.wp-rainrainbow:is([data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wrb-rays { animation: wrb-rays var(--wrb-d) ease-in-out both; }
#wallpaper.wp-rainrainbow:is([data-react="rare"], [data-react="epic"], [data-react="anomaly"], [data-react="mythic"], [data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wrb-cl { animation: wrb-drift 24s ease-in-out infinite alternate, wrb-part var(--wrb-d) both; }
#wallpaper.wp-rainrainbow:is([data-react="rare"], [data-react="epic"], [data-react="anomaly"], [data-react="mythic"], [data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wrb-cl + .wrb-cl { animation: wrb-drift 31s ease-in-out infinite alternate-reverse, wrb-part-r var(--wrb-d) both; }
#wallpaper.wp-rainrainbow:is([data-react="rare"], [data-react="epic"], [data-react="anomaly"], [data-react="mythic"], [data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wrb-rain { animation: wrb-fall 1s linear infinite, wrb-stop var(--wrb-d) ease-in-out both; }
#wallpaper.wp-rainrainbow:is([data-react="rare"], [data-react="epic"], [data-react="anomaly"], [data-react="mythic"], [data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"])::before { animation: wrb-fall-far 1.1s linear infinite, wrb-stop var(--wrb-d) ease-in-out both; }
#wallpaper.wp-rainrainbow { --wrb-d: 10s; }
#wallpaper.wp-rainrainbow:is([data-react="anomaly"], [data-react="mythic"]) { --wrb-d: 13s; }
#wallpaper.wp-rainrainbow:is([data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) { --wrb-d: 15s; }
@keyframes wrb-clear { 0% { opacity: 0; } 20% { opacity: 1; } 68% { opacity: 1; } 100% { opacity: 0; } }
@keyframes wrb-sun { 0%, 8% { opacity: 0; transform: scale(.8); } 26% { opacity: 1; transform: scale(1); } 66% { opacity: 1; transform: scale(1.04); } 92%, 100% { opacity: 0; transform: scale(.9); } }
@keyframes wrb-rays { 0%, 12% { opacity: 0; transform: rotate(0deg); } 30% { opacity: 1; } 70% { opacity: .8; } 95%, 100% { opacity: 0; transform: rotate(20deg); } }
@keyframes wrb-bow { 0%, 12% { opacity: 0; transform: scale(.94); } 32% { opacity: .9; transform: scale(1); } 66% { opacity: .9; } 90%, 100% { opacity: 0; transform: scale(1.01); } }
@keyframes wrb-bow2 { 0%, 22% { opacity: 0; } 40% { opacity: .65; } 64% { opacity: .65; } 86%, 100% { opacity: 0; } }
@keyframes wrb-part { 0% { transform: translate3d(0, 0, 0); opacity: 1; animation-timing-function: cubic-bezier(.3, 0, .2, 1); } 18% { transform: translate3d(-70%, -18%, 0); opacity: .25; }
  60% { transform: translate3d(-70%, -18%, 0); opacity: .25; animation-timing-function: cubic-bezier(.5, 0, .5, 1); } 100% { transform: translate3d(0, 0, 0); opacity: 1; } }
@keyframes wrb-part-r { 0% { transform: translate3d(0, 0, 0); opacity: 1; animation-timing-function: cubic-bezier(.3, 0, .2, 1); } 18% { transform: translate3d(70%, -18%, 0); opacity: .25; }
  60% { transform: translate3d(70%, -18%, 0); opacity: .25; animation-timing-function: cubic-bezier(.5, 0, .5, 1); } 100% { transform: translate3d(0, 0, 0); opacity: 1; } }
@keyframes wrb-stop { 0% { opacity: 1; } 14% { opacity: 0; } 76% { opacity: 0; } 100% { opacity: 1; } }
@media (prefers-reduced-motion: reduce) {
  #wallpaper.wp-rainrainbow i { animation: none !important; transition: opacity 1.5s; }
  #wallpaper.wp-rainrainbow:is([data-react="rare"], [data-react="epic"], [data-react="anomaly"], [data-react="mythic"], [data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) :is(.wrb-sky, .wrb-bow) { opacity: .85; } }
html.perf #wallpaper.wp-rainrainbow :is(.wrb-rain, .wrb-cl, .wrb-rays) { animation: none !important; }
html.perf #wallpaper.wp-rainrainbow:is([data-react="rare"], [data-react="epic"], [data-react="anomaly"], [data-react="mythic"], [data-react="celestial"], [data-react="divine"], [data-react="godlike"], [data-react="infinite"]) .wrb-rain { opacity: 0; transition: opacity 1.5s; }

/* 💎 Crystal Cave (idée de finnnnn, 2026-10-27) : une grotte aux cristaux lumineux, avec l'entrée d'une vieille galerie
   de mine (boisage, rails, un wagonnet plein de cristaux, une lanterne). Le fond : la roche (plafond à stalactites dans
   les deux coins du haut, sol, la galerie à gauche, un grand amas de cristaux à droite ; leurs tailles suivent la
   hauteur de l'écran) ; en haut au centre, une ouverture : un rayon de lune (thème sombre) ou de jour (thème clair,
   pour que le texte reste lisible) ; ::before, la lueur des cristaux qui respire ; ::after, des éclats qui scintillent.
