.wall-preview.wp-crystalcave { --wcc-c: 34%; --wcc-m: 82%; --wcc-k: 76%; --wcc-f: 18%; --wcc-w: 18%; }
/* calques du vrai fond */
#wallpaper.wp-crystalcave i { position: absolute; pointer-events: none; }
/* la flamme de la lanterne (dans la galerie : x 330, y 351 sur 600 x 700, à l'échelle de --wcc-m) */
#wallpaper .wcc-lamp { left: calc(var(--wcc-m) * 330 / 700); bottom: calc(var(--wcc-m) * 349 / 700); width: calc(var(--wcc-m) * .2); height: calc(var(--wcc-m) * .2); margin: 0 0 calc(var(--wcc-m) * -.1) calc(var(--wcc-m) * -.1); border-radius: 50%;
  background: radial-gradient(circle closest-side, rgba(254, 243, 199, .9), rgba(251, 191, 36, .35) 30%, transparent); animation: wcc-flame 2.3s steps(1) infinite; }
@keyframes wcc-flame { 0% { opacity: 1; transform: scale(1); } 23% { opacity: .78; transform: scale(.94); } 41% { opacity: .95; transform: scale(1.03); } 58% { opacity: .7; transform: scale(.92); } 77% { opacity: 1; transform: scale(1.02); } }
/* les gouttes : elles se forment au bout d'une stalactite, tombent, et font un petit rond au sol */
#wallpaper .wcc-drip { left: var(--x); top: var(--y); width: 4px; height: 7px; border-radius: 50% 50% 50% 50% / 30% 30% 70% 70%; background: #a5f3fc; box-shadow: 0 0 6px rgba(165, 243, 252, .9); opacity: 0;
  animation: wcc-drip 6s cubic-bezier(.55, 0, 1, .45) infinite; }
#wallpaper .wcc-drip:nth-of-type(2) { --x: calc(var(--wcc-c) * 1.2 - 2px); --y: calc(var(--wcc-c) * 0.491 - 4px); }
#wallpaper .wcc-drip:nth-of-type(3) { --x: calc(100% - var(--wcc-c) * .85 * 1.1 - 2px); --y: calc(var(--wcc-c) * .85 * 0.760 - 4px); animation-duration: 8.5s; animation-delay: -3s; }
@keyframes wcc-drip { 0%, 30% { opacity: 0; transform: translateY(0) scale(.3); } 45% { opacity: 1; transform: translateY(0) scale(1); } 46% { transform: translateY(0); } 70% { opacity: 1; transform: translateY(calc(100vh - var(--y) - var(--wcc-f) * .6)); } 70.1%, 100% { opacity: 0; transform: translateY(calc(100vh - var(--y) - var(--wcc-f) * .6)); } }
/* la chauve-souris : une traversée toutes les 33 s environ */
#wallpaper .wcc-bat { left: 0; top: 20%; width: min(7vmin, 54px); aspect-ratio: 46 / 26; opacity: 0; animation: wcc-bat 33s linear -9s infinite; }
#wallpaper .wcc-bat b { position: absolute; inset: 0; background: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 46 26'><path fill='%23110a1a' d='M23 9c-1-2-1-4 0-5l1 2 1-2c1 1 1 3 0 5 3 0 5 2 5 4 3-5 9-9 16-8-3 3-4 7-4 11-2-2-5-2-7 0-2-2-5-2-6 1-1-1-3-1-4 2-1-3-3-3-4-2-1-3-4-3-6-1-2-2-5-2-7 0 0-4-1-8-4-11 7-1 13 3 16 8 0-2 2-4 3-4z'/><circle cx='21.5' cy='10' r='.8' fill='%23e879f9'/><circle cx='24.5' cy='10' r='.8' fill='%23e879f9'/></svg>") center / contain no-repeat; filter: drop-shadow(0 0 4px rgba(232, 121, 249, .5)); animation: wcc-flap .2s ease-in-out infinite alternate; transform-origin: 50% 40%; }
@keyframes wcc-bat { 0% { opacity: 1; transform: translate3d(105vw, 6vh, 0); } 4% { transform: translate3d(76vw, -2vh, 0); } 8% { transform: translate3d(52vw, 5vh, 0); } 12% { transform: translate3d(26vw, -4vh, 0); }
  17% { opacity: 1; transform: translate3d(-12vw, 3vh, 0); } 17.01%, 100% { opacity: 0; transform: translate3d(-12vw, 3vh, 0); } }
@keyframes wcc-flap { from { transform: scaleY(1); } to { transform: scaleY(-.35) translateY(-3px); } }
@media (prefers-reduced-motion: reduce) { #wallpaper.wp-crystalcave :is(i, b) { animation: none !important; } #wallpaper :is(.wcc-bat, .wcc-drip) { display: none; } }
html.perf #wallpaper.wp-crystalcave :is(i, b) { animation: none !important; }
html.perf #wallpaper :is(.wcc-bat, .wcc-drip) { display: none; }

/* 🏞️ Lake (idée de randomguy, 2026-10-27) : un lac calme. Le fond : le ciel, le soleil bas (soir, thème sombre) ou haut
   (jour, thème clair), les collines et la rive boisée qui se reflètent dans l'eau (un SVG recadré « slice », horizon un
   peu sous le milieu), des roseaux et un ponton dans les coins. ::before, les reflets de lumière qui glissent sur l'eau ;
   ::after, les nuages. Sur le vrai fond, deux poissons sautent de temps en temps (arc : x linéaire, y qui ralentit en
   haut, rond dans l'eau au départ et à l'arrivée), des gouttes font des ronds, et plus rarement un dauphin saute.
   Mouvement réduit / mode performance : tout est arrêté, les sauteurs restent sous l'eau. */
