@keyframes wlk-jy { 0%, 87.9% { opacity: 0; transform: translateY(0) rotate(-55deg); }
  88% { opacity: 1; transform: translateY(0) rotate(-55deg); animation-timing-function: cubic-bezier(.25, .7, .45, 1); }
  92% { transform: translateY(calc(var(--h) * -1)) rotate(0deg); animation-timing-function: cubic-bezier(.55, 0, .75, .3); }
  96% { opacity: 1; transform: translateY(0) rotate(60deg); } 96.1%, 100% { opacity: 0; transform: translateY(0) rotate(60deg); } }
@keyframes wlk-ring-a { 0%, 87.9% { opacity: 0; transform: scale(.3); } 88% { opacity: .9; transform: scale(.4); } 94%, 100% { opacity: 0; transform: scale(1.4); } }
@keyframes wlk-ring-b { 0%, 95.9% { opacity: 0; transform: scale(.3); } 96% { opacity: 1; transform: scale(.5); } 100% { opacity: 0; transform: scale(1.6); } }
/* le dauphin : 5 % d'un cycle de 53 s (2,7 s), plus haut et plus lent */
@keyframes wlk-jx-rare { 0%, 94% { translate: 0 0; } 99%, 100% { translate: var(--dx) 0; } }
@keyframes wlk-jy-rare { 0%, 93.9% { opacity: 0; transform: translateY(0) rotate(-50deg); }
  94% { opacity: 1; transform: translateY(0) rotate(-50deg); animation-timing-function: cubic-bezier(.25, .7, .45, 1); }
  96.5% { transform: translateY(calc(var(--h) * -1)) rotate(0deg); animation-timing-function: cubic-bezier(.55, 0, .75, .3); }
  99% { opacity: 1; transform: translateY(0) rotate(55deg); } 99.1%, 100% { opacity: 0; transform: translateY(0) rotate(55deg); } }
@keyframes wlk-ring-a-rare { 0%, 93.9% { opacity: 0; transform: scale(.3); } 94% { opacity: 1; transform: scale(.4); } 97.5%, 100% { opacity: 0; transform: scale(1.5); } }
@keyframes wlk-ring-b-rare { 0%, 98.9% { opacity: 0; transform: scale(.3); } 99% { opacity: 1; transform: scale(.6); } 100% { opacity: .2; transform: scale(1.3); } }
/* une goutte qui fait des ronds, de temps en temps */
#wallpaper .wlk-drop { --x: 12%; --y: 80%; --s: min(9vmin, 70px); width: var(--s); height: calc(var(--s) * .25); margin: calc(var(--s) * -.125) 0 0 calc(var(--s) * -.5);
  border: 1.5px solid rgba(248, 250, 252, .7); border-radius: 50%; opacity: 0; animation: wlk-drop 7s ease-out infinite; }
#wallpaper .wlk-drop + .wlk-drop { --x: 84%; --y: 66%; animation-duration: 11s; animation-delay: -5s; }
@keyframes wlk-drop { 0%, 70% { opacity: 0; transform: scale(.1); } 72% { opacity: .9; } 100% { opacity: 0; transform: scale(1.5); } }
@media (prefers-reduced-motion: reduce) { #wallpaper.wp-lake :is(i, b, u, s) { animation: none !important; } }
html.perf #wallpaper.wp-lake :is(i, b, u, s) { animation: none !important; }
/* fin des sept fonds du 2026-10-27 */

/* Aperçu d'un fond d'écran : le contenu du site s'efface pour montrer le fond en plein écran, une barre reste en bas. */
html.wall-trying body > *:not(#wallpaper):not(.wall-try-bar) { opacity: 0; pointer-events: none; transition: opacity .35s; }
.wall-try-bar { position: fixed; left: 50%; bottom: 1.5rem; transform: translateX(-50%); z-index: 1000; display: flex; align-items: center; gap: .75rem;
  padding: .6rem .8rem .6rem 1.1rem; border-radius: 999px; background: rgba(10, 10, 14, .82); border: 1px solid rgba(255, 255, 255, .15); color: #fff;
  backdrop-filter: blur(8px); box-shadow: 0 10px 30px rgba(0, 0, 0, .45); max-width: calc(100vw - 32px); white-space: nowrap; }
