/* ------------------------------------------------------------------ Heavenly (idée de Gunnar, 2026-10-16) : marbre
   blanc veiné d'or, chiffres en feuille d'or. Matière dure : le chiffre descend du ciel, s'illumine d'un éclat, pas
   d'écrasement ; pendant le tirage, les chiffres montent comme de la lumière. */
.num-card.skin-heavenly {
  background:
    linear-gradient(115deg, transparent 30%, rgba(234, 179, 8, .2) 31%, transparent 32.5%, transparent 62%, rgba(234, 179, 8, .13) 63%, transparent 64%),
    linear-gradient(70deg, transparent 45%, rgba(148, 163, 184, .14) 46%, transparent 48%),
    radial-gradient(ellipse 70% 60% at 50% 0%, #ffffff, transparent 75%),
    linear-gradient(180deg, #fffdf7 0%, #f5f0e6 60%, #e9e1d0 100%);
  border: 2px solid #eab308; border-radius: 1rem;
  box-shadow: inset 0 0 0 3px #fffbeb, inset 0 0 0 4px rgba(202, 138, 4, .55), 0 0 22px rgba(253, 224, 71, .35), 0 8px 18px rgba(120, 90, 20, .25);
}
/* Lisibilité (signalé par casmictechthing, 2026-10-20) : l'or clair se perdait sur le marbre blanc. Feuille d'or plus
   profonde (bronze → or → bronze), contour brun plus épais et une ombre portée sombre qui détache le chiffre du marbre ;
   le reflet blanc reste en haut pour garder l'éclat. */
.skin-heavenly .slot {
  font-weight: 900; color: transparent;
  background: linear-gradient(180deg, #b45309 0%, #eab308 32%, #a16207 50%, #f59e0b 68%, #854d0e 100%);
  -webkit-background-clip: text; background-clip: text;
  -webkit-text-stroke: .04em #4a2205;
  filter: drop-shadow(0 -.03em 0 rgba(255, 255, 255, .95)) drop-shadow(0 .05em .02em rgba(69, 26, 3, .55)) drop-shadow(0 0 .12em rgba(253, 224, 71, .55));
}
.skin-heavenly .slot.ghost { opacity: .18; }
.skin-heavenly .slot.spinning { animation: heavenly-rise .24s linear infinite; }
@keyframes heavenly-rise { 0% { transform: translateY(.14em); opacity: .9; } 100% { transform: translateY(-.14em); opacity: 1; } }
.skin-heavenly .slot.revealed { animation: heavenly-land .6s cubic-bezier(.2, .9, .3, 1) backwards, heavenly-glow 1.1s .25s ease-out backwards; }
@keyframes heavenly-land { 0% { transform: translateY(-.6em) scale(.9); } 55% { transform: translateY(.04em) scale(1.04); } 100% { transform: none; } }
@keyframes heavenly-glow { 0% { filter: drop-shadow(0 -.03em 0 #fff) drop-shadow(0 .05em .02em rgba(69, 26, 3, .55)) drop-shadow(0 0 .35em #facc15) brightness(1.15); } 100% { filter: drop-shadow(0 -.03em 0 rgba(255, 255, 255, .95)) drop-shadow(0 .05em .02em rgba(69, 26, 3, .55)) drop-shadow(0 0 .12em rgba(253, 224, 71, .55)); } }
.skin-heavenly .slot.collapsed { width: 0; height: 0; margin: 0; box-shadow: none; background: none; }
@media (prefers-reduced-motion: reduce) { .skin-heavenly .slot { animation: none; } }
.side-heavenly { --side-border: #eab308; --side-glow: 0 0 18px rgba(253, 224, 71, .4); --side-ink: #a16207;
  --side-bg: radial-gradient(ellipse 80% 60% at 50% 0%, rgba(254, 243, 199, .35), transparent 70%), linear-gradient(180deg, rgba(255, 251, 235, .12), rgba(234, 179, 8, .08));
  --deco-a: '🪽'; --deco-b: '✨'; }

/* ------------------------------------------------------------------ Bloodlust (idée d'un joueur, 2026-10-16) : un
   liquide rouge sombre et brillant, stylisé. Carte noire veloutée, coulures figées au bord haut ; chiffres en gouttes
   laquées. Matière molle : pendant le tirage les chiffres coulent vers le bas, à la révélation ils tombent et s'étalent. */
.num-card.skin-bloodlust {
  background:
    radial-gradient(4px 14px at 12% 0%, #7f1d1d 90%, transparent 100%), radial-gradient(5px 22px at 31% 0%, #991b1b 90%, transparent 100%),
    radial-gradient(3px 10px at 52% 0%, #7f1d1d 90%, transparent 100%), radial-gradient(6px 26px at 74% 0%, #991b1b 90%, transparent 100%),
    radial-gradient(4px 12px at 90% 0%, #7f1d1d 90%, transparent 100%),
    linear-gradient(180deg, #991b1b 0, #7f1d1d 6%, transparent 6.5%),
    radial-gradient(ellipse 80% 70% at 50% 60%, #2a0707, #120202 75%);
  border: 2px solid #450a0a; border-radius: .9rem;
  box-shadow: inset 0 0 0 1px rgba(220, 38, 38, .25), inset 0 -10px 18px rgba(0, 0, 0, .6), 0 0 18px rgba(185, 28, 28, .3), 0 8px 18px rgba(0, 0, 0, .45);
}
.skin-bloodlust .slot {
  font-weight: 900; color: transparent;
  background: radial-gradient(ellipse 40% 30% at 35% 25%, rgba(254, 202, 202, .9), transparent 60%), linear-gradient(180deg, #ef4444 0%, #b91c1c 45%, #7f1d1d 100%);
  -webkit-background-clip: text; background-clip: text;
  -webkit-text-stroke: .02em #450a0a;
  filter: drop-shadow(0 .06em 0 #3b0505) drop-shadow(0 0 .12em rgba(239, 68, 68, .35));
}
.skin-bloodlust .slot.ghost { opacity: .2; }
.skin-bloodlust .slot.spinning { transform-origin: 50% 0; animation: blood-ooze .3s ease-in infinite; }
@keyframes blood-ooze { 0% { transform: translateY(-.12em) scale(1, .92); } 70% { transform: translateY(.08em) scale(.94, 1.12); } 100% { transform: translateY(.12em) scale(1, 1); } }
.skin-bloodlust .slot.revealed { transform-origin: 50% 100%; animation: blood-drop .62s cubic-bezier(.3, 1.5, .5, 1) backwards, blood-gloss 1.1s .45s ease-out backwards; }
@keyframes blood-drop { 0% { transform: translateY(-.5em) scale(.7, 1.35); } 42% { transform: translateY(.03em) scale(1.25, .72); } 72% { transform: scale(.95, 1.06); } 100% { transform: none; } }
@keyframes blood-gloss { 0% { filter: drop-shadow(0 .06em 0 #3b0505) drop-shadow(0 0 .3em rgba(239, 68, 68, .8)) brightness(1.4); } 100% { filter: drop-shadow(0 .06em 0 #3b0505) drop-shadow(0 0 .12em rgba(239, 68, 68, .35)); } }
.skin-bloodlust .slot.collapsed { width: 0; height: 0; margin: 0; box-shadow: none; background: none; }
@media (prefers-reduced-motion: reduce) { .skin-bloodlust .slot { animation: none; } }
.side-bloodlust { --side-border: #991b1b; --side-glow: 0 0 16px rgba(185, 28, 28, .35); --side-ink: #b91c1c;
  --side-bg: linear-gradient(180deg, rgba(127, 29, 29, .35), rgba(18, 2, 2, .2));
  --deco-a: '🩸'; --deco-b: '🦇'; }

/* ------------------------------------------------------------------ Trick or Treat (idée de Deadshot, 2026-10-16) :
   une rue de maisons la nuit d'Halloween. Chaque chiffre est une porte éclairée ; pendant le tirage, la porte est fermée
   et on y frappe ; à la révélation elle s'ouvre sur un bonbon en forme de chiffre. Derrière un zéro de tête : une
   maison vide, porte ouverte sur le noir. */
.num-card.skin-trickortreat {
  background:
    conic-gradient(from 135deg at 50% 0%, #1e1033 0 90deg, transparent 90deg) 0 0 / 2.2em 1.1em repeat-x,
    radial-gradient(circle at 88% 18%, #fef3c7 0 .35em, rgba(254, 243, 199, .25) .36em .6em, transparent .62em),
    linear-gradient(180deg, transparent 82%, #14532d 82% 86%, #0b2a17 86%),
    linear-gradient(180deg, #4c1d95 0%, #2e1065 45%, #3b0764 100%);
  border: 2px solid #f97316; border-radius: .8rem;
  box-shadow: inset 0 0 0 1px rgba(251, 146, 60, .35), 0 0 18px rgba(249, 115, 22, .3), 0 8px 18px rgba(0, 0, 0, .4);
}
.skin-trickortreat .slot { position: relative; isolation: isolate; width: .72em; margin: 0 .03em; font-weight: 900; color: #fb7185;
  -webkit-text-stroke: .025em #fff1f2; text-shadow: 0 .04em 0 #9d174d, 0 0 .2em rgba(251, 113, 133, .55); }
.skin-trickortreat .slot:nth-child(3n+2) { color: #fbbf24; text-shadow: 0 .04em 0 #92400e, 0 0 .2em rgba(251, 191, 36, .55); }
.skin-trickortreat .slot:nth-child(3n) { color: #a78bfa; text-shadow: 0 .04em 0 #4c1d95, 0 0 .2em rgba(167, 139, 250, .55); }
/* l'encadrement de porte, éclairé de l'intérieur */
.skin-trickortreat .slot::after { content: ''; position: absolute; left: 0; right: 0; top: .1em; bottom: -.04em; z-index: -1;
  border: .05em solid #3b1d0e; border-bottom: 0; border-radius: .34em .34em 0 0;
  background: radial-gradient(ellipse 80% 70% at 50% 60%, #fde68a, #f59e0b 70%, #b45309); }
/* la porte en bois : ouverte au repos, fermée pendant le tirage */
.skin-trickortreat .slot::before { content: ''; position: absolute; left: 0; right: 0; top: .1em; bottom: -.04em; z-index: 2;
  border-radius: .34em .34em 0 0; transform-origin: 0 50%; transform: perspective(14em) rotateY(-105deg); opacity: 0;
  background: radial-gradient(circle at 78% 58%, #fbbf24 0 .045em, transparent .055em), repeating-linear-gradient(90deg, #7c2d12 0 .12em, #9a3412 .12em .24em); box-shadow: inset 0 0 0 .04em #431407; }
.skin-trickortreat .slot.spinning { opacity: 1; color: transparent; }
.skin-trickortreat .slot.spinning::before { opacity: 1; transform: none; animation: tot-knock .32s ease-in-out infinite; }
@keyframes tot-knock { 0%, 100% { transform: none; } 30% { transform: translateX(.02em) rotate(.6deg); } 60% { transform: translateX(-.02em) rotate(-.6deg); } }
.skin-trickortreat .slot.revealed::before { animation: tot-open .6s cubic-bezier(.3, 1.4, .5, 1) backwards; }
@keyframes tot-open { 0% { opacity: 1; transform: none; } 25% { opacity: 1; transform: perspective(14em) rotateY(8deg); } 100% { opacity: 0; transform: perspective(14em) rotateY(-105deg); } }
.skin-trickortreat .slot.revealed { animation: tot-candy .6s .1s cubic-bezier(.3, 1.6, .5, 1) backwards; }
@keyframes tot-candy { 0% { transform: scale(.82); } 60% { transform: scale(1.07); } 100% { transform: none; } }
/* zéro de tête : une maison vide, porte ouverte sur le noir */
.skin-trickortreat .slot.ghost { opacity: 1; color: transparent; -webkit-text-stroke: 0; text-shadow: none; }
.skin-trickortreat .slot.ghost::after { background: linear-gradient(180deg, #0c0a16, #1c1530); border-color: #241225; }
.skin-trickortreat .slot.collapsed { width: 0; margin: 0; }
.skin-trickortreat .slot.collapsed::before, .skin-trickortreat .slot.collapsed::after { display: none; }
@media (prefers-reduced-motion: reduce) { .skin-trickortreat .slot, .skin-trickortreat .slot::before { animation: none; } }
.side-trickortreat { --side-border: #f97316; --side-glow: 0 0 16px rgba(249, 115, 22, .35); --side-ink: #ea580c;
  --side-bg: linear-gradient(180deg, rgba(76, 29, 149, .35), rgba(249, 115, 22, .1));
  --deco-a: '🏚️'; --deco-b: '🍬'; }

/* Inventaire sur le profil (idée de kaz, 2026-10-17) : les skins et fonds d'écran du joueur, en pastilles. */
.inv-list { display: flex; flex-wrap: wrap; gap: .4rem; }
.inv-item { cursor: default; }

/* ------------------------------------------------------------------ Western (idée de JBearr12, 2026-10-17) : une
   palissade au coucher de soleil dans le désert. Pendant le tirage, des bouteilles de verre vert sont posées sur la
   planche et vacillent ; quand un chiffre se pose, la bouteille éclate (le revolver du canevas tire) et laisse un
   chiffre en laiton. Matière dure : éclat et recul, pas d'écrasement. */
.num-card.skin-western {
  background:
    linear-gradient(180deg, transparent 72%, #78350f 72% 74%, #92400e 74% 90%, #78350f 90%),
    repeating-linear-gradient(90deg, transparent 0 2.2em, rgba(69, 26, 3, .55) 2.2em 2.3em),
    radial-gradient(circle at 80% 70%, #fde68a 0 .5em, rgba(253, 186, 116, .4) .55em 1.1em, transparent 1.2em),
    linear-gradient(180deg, #7c2d12 0%, #c2410c 38%, #f59e0b 68%, #fcd34d 72%);
  border: 2px solid #451a03; border-radius: .6rem;
  box-shadow: inset 0 0 0 2px rgba(254, 215, 170, .25), inset 0 -8px 14px rgba(69, 26, 3, .5), 0 8px 18px rgba(69, 26, 3, .4);
}
.skin-western .slot { position: relative; font-weight: 900; color: transparent;
  background: linear-gradient(180deg, #fef3c7 0%, #fbbf24 35%, #b45309 60%, #fcd34d 80%, #92400e 100%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-stroke: .02em #451a03;
  filter: drop-shadow(0 .05em 0 #451a03) drop-shadow(0 0 .08em rgba(251, 191, 36, .4)); }
.skin-western .slot.ghost { opacity: .22; }
/* la bouteille de verre vert, posée sur la planche (visible pendant le tirage) */
.skin-western .slot::before { content: ''; position: absolute; left: 22%; right: 22%; top: .05em; bottom: .12em; opacity: 0; pointer-events: none;
  background: radial-gradient(ellipse 30% 20% at 35% 55%, rgba(255, 255, 255, .5), transparent 70%), linear-gradient(90deg, #14532d, #22c55e 45%, #15803d);
  clip-path: polygon(40% 0, 60% 0, 60% 22%, 80% 38%, 82% 100%, 18% 100%, 20% 38%, 40% 22%); }
.skin-western .slot.spinning { opacity: 1; }
.skin-western .slot.spinning::before { opacity: 1; transform-origin: 50% 100%; animation: west-wobble .3s ease-in-out infinite; }
@keyframes west-wobble { 0%, 100% { transform: rotate(-4deg); } 50% { transform: rotate(4deg); } }
.skin-western .slot.spinning { -webkit-text-fill-color: transparent; background: none; -webkit-text-stroke: 0; }
/* la bouteille éclate, le chiffre en laiton apparaît avec un petit recul */
.skin-western .slot.revealed::before { animation: west-burst .28s ease-out both; }
@keyframes west-burst { 0% { opacity: 1; transform: scale(1); filter: brightness(1.8); } 100% { opacity: 0; transform: scale(1.6); filter: brightness(2.5); } }
.skin-western .slot.revealed { animation: west-hit .5s cubic-bezier(.2, .9, .3, 1) backwards, west-flash .8s .05s ease-out backwards; }
@keyframes west-hit { 0% { transform: translateX(-.08em) scale(.85); } 40% { transform: translateX(.04em) scale(1.06); } 100% { transform: none; } }
@keyframes west-flash { 0% { filter: drop-shadow(0 0 .3em #fde047) brightness(1.7); } 100% { filter: drop-shadow(0 .05em 0 #451a03) drop-shadow(0 0 .08em rgba(251, 191, 36, .4)); } }
.skin-western .slot.collapsed { width: 0; height: 0; margin: 0; box-shadow: none; background: none; }
.skin-western .slot.collapsed::before { display: none; }
@media (prefers-reduced-motion: reduce) { .skin-western .slot, .skin-western .slot::before { animation: none; } }
.side-western { --side-border: #b45309; --side-glow: 0 0 16px rgba(245, 158, 11, .35); --side-ink: #b45309;
  --side-bg: linear-gradient(180deg, rgba(194, 65, 12, .3), rgba(253, 211, 77, .12));
  --deco-a: '🌵'; --deco-b: '🤠'; }

/* Bouton Discord (serveur RNG∞, 2026-10-17) : au-dessus des nouveautés, à gauche ; violet Discord au survol. */
@media (min-width: 901px) { .gh-corner.discord-corner { bottom: 106px; } } /* téléphone : rangé en bas de page avec les autres */
.gh-corner.discord-corner:hover, .gh-corner.discord-corner:focus-visible { color: #5865f2; }

/* Corrections d'affichage sur téléphone (audit du 2026-10-17). Boutique : 7 onglets, libellés longs (WALLPAPERS,
   UPGRADES) qui débordaient ; ils passent sous l'icône, en plus petit. Profil : les deux boutons de « My profile » se
   chevauchaient ; ils passent à la ligne. Badges : le champ du vérificateur poussait « Check » hors de l'écran. */
.shop-tabs { grid-template-columns: repeat(auto-fit, minmax(6.4rem, 1fr)); }
@media (max-width: 900px) {
  .shop-tabs { grid-template-columns: repeat(auto-fit, minmax(4.6rem, 1fr)); }
  .shop-tabs button { flex-direction: column; gap: .25rem; font-size: .62rem; letter-spacing: 0; padding: .55rem .2rem; }
}
.me-panel .actions { display: flex; flex-wrap: wrap; gap: .5rem; }
.xc-form .input { min-width: 0; }

/* Lier son Discord (Profil & amis → Mon profil, 2026-10-17). */
.discord-link { display: flex; flex-wrap: wrap; align-items: center; gap: .5rem; margin: .4rem 0 .7rem; font-size: .85rem; color: var(--prose-2); }
.discord-link .dl-btn { background: #5865f2; border-color: #5865f2; color: #fff; }
.discord-link .dl-on b { color: var(--prose); }

/* ------------------------------------------------------------------ Profil (refait le 2026-10-17) : une carte
   d'en-tête (identité, meilleur tirage dans le skin du joueur, 4 chiffres clés) puis des onglets. */
.pf-hero { display: grid; grid-template-columns: 1fr auto; grid-template-areas: "id best" "stats best" "more more"; gap: 1rem 1.5rem; padding: 1.4rem 1.5rem; margin: .4rem 0 1rem;
  border: 1px solid var(--outline); border-radius: 1.1rem; background: radial-gradient(ellipse 60% 90% at 100% 0%, color-mix(in srgb, #a855f7 14%, transparent), transparent 70%), var(--surface); box-shadow: 0 10px 30px rgba(0, 0, 0, .12); }
.pf-id { grid-area: id; min-width: 0; }
.pf-name { font: 900 clamp(1.6rem, 4vw, 2.4rem)/1.1 var(--font-sans); letter-spacing: -.02em; overflow-wrap: anywhere; }
.pf-name .muted { font-size: .5em; font-weight: 600; }
.pf-tags { display: flex; flex-wrap: wrap; align-items: center; gap: .35rem; margin-top: .45rem; }
.pf-tags:empty { display: none; }
.pf-discord { font-size: .75rem; font-weight: 700; color: #5865f2; background: color-mix(in srgb, #5865f2 12%, transparent); border-radius: 999px; padding: .15rem .55rem; }
.pf-since { margin-top: .5rem; font-size: .82rem; color: var(--prose-3); }
.pf-actions { margin-top: .8rem; }
.pf-best { grid-area: best; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: .55rem; min-width: 15rem; padding: .9rem 1.1rem; border-radius: .9rem; background: color-mix(in srgb, var(--site-bg) 55%, transparent); }
.pf-best-label { font: 800 .7rem var(--font-sans); letter-spacing: .12em; text-transform: uppercase; color: var(--prose-3); }
.pf-best-meta { display: flex; align-items: center; gap: .5rem; font-size: .85rem; }
.pf-stats { grid-area: stats; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: .6rem; align-self: end; }
.pf-stat { padding: .6rem .7rem; border-radius: .7rem; border: 1px solid var(--outline); background: var(--site-bg); min-width: 0; }
.pf-stat span { display: block; font: 700 .66rem var(--font-sans); letter-spacing: .08em; text-transform: uppercase; color: var(--prose-3); }
.pf-stat b { display: block; margin-top: .2rem; font: 800 1.25rem var(--font-mono, monospace); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pf-stat b small { font-size: .7em; color: var(--prose-3); }
.pf-more { grid-area: more; font-size: .82rem; color: var(--prose-2); border-top: 1px dashed var(--outline); padding-top: .7rem; }
.pf-tabs { margin: 0 0 1rem; }
.pf-tabs button small { opacity: .6; font-size: .8em; margin-left: .15rem; }
.pf-tabs button i { font-style: normal; }
.pf-rarities { display: grid; grid-template-columns: repeat(8, minmax(0, 1fr)); gap: .5rem; }
.pf-rar { text-align: center; padding: .55rem .2rem; border-radius: .6rem; border: 1px solid var(--t-border, var(--outline)); background: linear-gradient(160deg, var(--t-from, var(--surface)), var(--t-to, var(--surface))); color: var(--t-text, var(--prose)); }
.pf-rar b { display: block; font: 900 1.25rem var(--font-mono, monospace); }
.pf-rar span { font: 800 .62rem var(--font-sans); letter-spacing: .06em; text-transform: uppercase; }
.pf-rar.none { opacity: .35; filter: grayscale(.6); }
.pf-rolls .panel { margin: 0; }
.pf-inv { display: grid; grid-template-columns: repeat(auto-fill, minmax(9.5rem, 1fr)); gap: .6rem; }
.pf-inv-item { display: flex; flex-direction: column; align-items: center; gap: .45rem; padding: .7rem .5rem; border: 1px solid var(--outline); border-radius: .8rem; text-align: center; font-size: .8rem; }
.pf-inv-item.on { border-color: #a855f7; box-shadow: 0 0 0 1px #a855f7 inset; }
.pf-inv-item .wall-preview { width: 100%; height: 4.2rem; margin: 0; }
@media (max-width: 760px) {
  .pf-hero { grid-template-columns: 1fr; grid-template-areas: "id" "best" "stats" "more"; padding: 1.1rem; }
  .pf-best { min-width: 0; }
  .pf-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .pf-rarities { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .pf-tabs { display: flex; overflow-x: auto; scrollbar-width: none; }
  .pf-tabs button { flex: 0 0 auto; padding-left: .8rem; padding-right: .8rem; white-space: nowrap; }
}
.pf-best .num-card { font-size: 2.7rem; padding: .35em .55em; }
@media (max-width: 760px) { .pf-best .num-card { font-size: 2.2rem; } }

/* Événement de la semaine (2026-10-17), en tête des quêtes : liseré doré et mini-podium. */
.quest.event-quest { border: 1px solid color-mix(in srgb, #f59e0b 55%, transparent); background: linear-gradient(120deg, color-mix(in srgb, #f59e0b 12%, transparent), transparent 70%); border-radius: .7rem; padding: .55rem .6rem; margin-bottom: .35rem; }
