.g-tabs { grid-template-columns: repeat(5, minmax(0, 1fr)); }
@media (max-width: 560px) { .g-tabs { grid-template-columns: repeat(5, minmax(0, 1fr)); gap: .3rem; } .g-tab { padding-inline: .1rem; } }
