.kn-board { display: grid; grid-template-columns: repeat(8, minmax(0, 1fr)); gap: .35rem; }
.kn-cell { aspect-ratio: 1; min-width: 0; border-radius: 50%; border: 1px solid rgba(255, 255, 255, .1); background: radial-gradient(circle at 35% 30%, #3b4a63, #1b2335 70%); box-shadow: 0 2px 0 #070b14, inset 0 1px 0 rgba(255, 255, 255, .15); color: #cbd5e1; font-size: .82rem; font-weight: 700; cursor: pointer; transition: transform .12s var(--ease-snap), filter .15s ease, opacity .2s ease, box-shadow .2s ease; }
.kn-cell:hover { filter: brightness(1.25); transform: translateY(-1px); }
.kn-cell:focus-visible { outline: 2px solid #38bdf8; outline-offset: 2px; }
