/* « ? » des règles de chaque jeu du casino (idée d'Ann joe, 2026-10-27), à côté du titre ; la fenêtre des règles. */
.g-game .panel-head .g-help { display: inline-grid; place-items: center; flex: none; width: 1.6rem; height: 1.6rem; margin-right: auto; padding: 0; align-self: center; border-radius: 50%; border: 1px solid var(--outline); background: var(--surface-raised); color: var(--prose); font: 800 .8rem/1 inherit; cursor: pointer; transition: transform .12s ease, border-color .12s ease; }
.g-game .panel-head .g-help:hover { transform: scale(1.08); border-color: var(--prose-3); }
.g-howto { max-width: 30rem; }
.g-howto h2 { margin: 0 2rem .2rem 0; font-size: 1.15rem; }
.g-howto-goal { margin: .2rem 0 .6rem; font-weight: 700; }
.g-howto h4 { margin: .75rem 0 .3rem; font-size: .7rem; letter-spacing: .07em; text-transform: uppercase; color: var(--prose-3); }
.g-howto ul { display: grid; gap: .3rem; margin: 0; padding-left: 1.15rem; font-size: .9rem; line-height: 1.4; }
.g-howto p { margin: 0; font-size: .9rem; }
.g-howto .g-howto-foot { margin-top: .95rem; font-size: .74rem; color: var(--prose-3); }

/* ------------------------------------------------------------------ Cursed Energy (idée d'Edward, 2026-10-20) : les
   chiffres sont de l'énergie condensée, bleu-violet, cernée d'encre noire ; derrière, un sceau original (cercles,
   huit traits, triangle) et une aura qui ondule. Pendant le tirage l'énergie vacille comme une flamme froide ; au
   moment où le chiffre se pose, elle se contracte (anticipation) puis éclate en crépitant et retombe. */
.num-card.skin-cursed {
  background:
    url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='120' height='120' viewBox='0 0 120 120'><g fill='none' stroke='%23a78bfa' stroke-opacity='.3'><circle cx='60' cy='60' r='52' stroke-width='1.5'/><circle cx='60' cy='60' r='44' stroke-dasharray='3 5'/><circle cx='60' cy='60' r='20'/><path d='M60 22 L93 79 L27 79 Z' stroke-width='1.2'/><path d='M60 8v10M60 102v10M8 60h10M102 60h10M23 23l7 7M90 90l7 7M97 23l-7 7M30 90l-7 7' stroke-width='2'/></g></svg>") 50% 50% / 3.6em 3.6em no-repeat,
    url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='200' height='60'><g fill='none' stroke='%2393c5fd' stroke-opacity='.35' stroke-width='.8'><path d='M0 44 l12 -6 l6 5 l14 -9 l8 4'/><path d='M128 10 l10 7 l9 -4 l12 8 l7 -3'/><path d='M170 50 l9 -5 l5 4 l12 -7'/></g></svg>") 0 0 / 7em 100% repeat-x,
    radial-gradient(ellipse 70% 70% at 50% 120%, rgba(79, 70, 229, .55), transparent 70%),
    radial-gradient(ellipse 45% 70% at 10% -10%, rgba(147, 51, 234, .35), transparent 70%),
    linear-gradient(180deg, #07051a 0%, #0f0a2e 55%, #030210 100%);
  border: 2px solid #312e81; border-radius: .7rem; position: relative;
  box-shadow: inset 0 0 0 1px rgba(167, 139, 250, .3), inset 0 0 1.2em rgba(76, 29, 149, .6), 0 0 18px rgba(124, 58, 237, .35), 0 10px 20px rgba(0, 0, 0, .5);
}
/* l'aura : des langues d'énergie qui montent du bas, en boucle lente (coupée en duel à 3+) */
.num-card.skin-cursed::before { content: ''; position: absolute; inset: 35% -5% 0; pointer-events: none; z-index: 0;
  background: radial-gradient(ellipse 12% 40% at 12% 100%, rgba(129, 140, 248, .5), transparent 70%), radial-gradient(ellipse 10% 55% at 34% 100%, rgba(167, 139, 250, .45), transparent 70%),
    radial-gradient(ellipse 13% 45% at 58% 100%, rgba(99, 102, 241, .5), transparent 70%), radial-gradient(ellipse 10% 60% at 82% 100%, rgba(192, 132, 252, .45), transparent 70%);
  filter: blur(2px); mix-blend-mode: screen; opacity: .75; animation: cur-aura 2.4s ease-in-out infinite alternate; }
@keyframes cur-aura { 0% { transform: translateY(10%) scaleY(.8); opacity: .5; } 50% { transform: translateY(0) scaleY(1.1) skewX(-4deg); opacity: .85; } 100% { transform: translateY(5%) scaleY(.95) skewX(4deg); opacity: .6; } }
.room-stage.many .num-card.skin-cursed::before { animation: none; }
.skin-cursed .slot { position: relative; z-index: 1; font-weight: 900; color: transparent;
  background: linear-gradient(180deg, #312e81 0%, #1e1048 45%, #05020f 100%); -webkit-background-clip: text; background-clip: text;
  -webkit-text-stroke: .045em #c4b5fd; filter: drop-shadow(0 0 .06em #a78bfa) drop-shadow(0 0 .16em #7c3aed) drop-shadow(0 -.06em .2em rgba(59, 130, 246, .7)); }
.skin-cursed .slot.ghost { opacity: .2; }
/* en cours : l'énergie vacille, se tord et change de teinte, comme une flamme froide */
.skin-cursed .slot.spinning { opacity: .85; animation: cur-flicker .24s steps(4) infinite; }
@keyframes cur-flicker {
  0% { transform: translate(-.03em, .02em) skewX(-6deg) scaleY(1.06); filter: blur(.5px) drop-shadow(0 -.12em .12em #6366f1) drop-shadow(0 -.3em .2em rgba(124, 58, 237, .8)); }
  50% { transform: translate(.03em, -.04em) skewX(5deg) scaleY(.96); filter: blur(1px) hue-rotate(18deg) drop-shadow(0 -.2em .15em #a855f7) drop-shadow(0 -.4em .25em rgba(59, 130, 246, .7)); }
  100% { transform: translate(-.01em, -.02em) skewX(-2deg) scaleY(1.1); filter: blur(.3px) hue-rotate(-14deg) drop-shadow(0 -.15em .1em #818cf8) drop-shadow(0 -.32em .2em rgba(147, 51, 234, .8)); } }
/* il se pose : l'énergie se contracte, éclate en blanc-violet, puis retombe dans son aura */
.skin-cursed .slot.revealed { animation: cur-seal .62s cubic-bezier(.3, 1.5, .5, 1) backwards, cur-burst .75s ease-out backwards; }
@keyframes cur-seal { 0% { transform: scale(1.35); } 22% { transform: scale(.78); } 45% { transform: scale(1.14); } 100% { transform: none; } }
@keyframes cur-burst {
  0% { filter: blur(3px) brightness(.6) drop-shadow(0 0 .1em #4c1d95); }
  22% { filter: blur(1px) brightness(.8) drop-shadow(0 0 .05em #312e81); }
  32% { filter: brightness(3) drop-shadow(0 0 .2em #e0e7ff) drop-shadow(0 0 .55em #a855f7) drop-shadow(0 0 1em #3b82f6); }
  100% { filter: drop-shadow(0 0 .06em #a78bfa) drop-shadow(0 0 .16em #7c3aed) drop-shadow(0 -.06em .2em rgba(59, 130, 246, .7)); } }
.skin-cursed .slot.collapsed { width: 0; height: 0; margin: 0; box-shadow: none; background: none; }
@media (prefers-reduced-motion: reduce) { .skin-cursed .slot, .num-card.skin-cursed::before { animation: none; } }
.side-cursed { --side-border: #7c3aed; --side-glow: 0 0 18px rgba(124, 58, 237, .45); --side-ink: #7c3aed;
  --side-bg: radial-gradient(ellipse 80% 60% at 50% 100%, rgba(99, 102, 241, .25), transparent 70%), linear-gradient(180deg, rgba(20, 11, 51, .6), rgba(124, 58, 237, .12));
  --deco-a: '🌀'; --deco-b: '🔮'; }
/* ------------------------------------------------------------------ Marshmallow (idée de DandoriNinja, 2026-10-21) : un ciel
   pastel rose-lilas, des nuages de sucre. Les chiffres sont des guimauves gonflées, mates et poudrées (blanches et
   roses en alternance). Matière molle : en cours, ils gigotent en s'écrasant ; à la pose, ils tombent, s'aplatissent
   (« plof ») et rebondissent. Les guimauves qui tombent et les canons à confettis sont dans js/skinfx.js. */
.num-card.skin-marsh {
  background:
    radial-gradient(circle at 18% 30%, rgba(255, 255, 255, .55) 0 .05em, transparent .06em) 0 0 / 1.3em 1.1em,
    radial-gradient(ellipse 30% 26% at 10% 104%, #fff 60%, transparent 62%), radial-gradient(ellipse 26% 30% at 34% 106%, #fff7fb 60%, transparent 62%),
    radial-gradient(ellipse 30% 24% at 64% 104%, #fff 60%, transparent 62%), radial-gradient(ellipse 26% 28% at 92% 104%, #fff7fb 60%, transparent 62%),
    linear-gradient(180deg, #f9c9df 0%, #e7c6f5 55%, #cdbdf3 100%);
  border: 2px solid #f3a9c8; border-radius: 1rem;
  box-shadow: inset 0 .25em .5em rgba(255, 255, 255, .6), inset 0 -.2em .4em rgba(167, 139, 250, .25), 0 0 16px rgba(244, 114, 182, .3), 0 8px 18px rgba(124, 58, 237, .18);
}
.skin-marsh .slot { position: relative; z-index: 1; font-weight: 900; transform-origin: 50% 88%; color: transparent;
  background: radial-gradient(ellipse 60% 30% at 40% 22%, #fff 40%, transparent 75%), linear-gradient(180deg, #ffffff 0%, #fff4f9 45%, #f6d6e6 100%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-stroke: .055em #dc7aa6; paint-order: stroke fill;
  filter: drop-shadow(0 .05em 0 #d9799f) drop-shadow(0 .08em .06em rgba(157, 23, 77, .35)); }
.skin-marsh .slot:nth-child(even) { background: radial-gradient(ellipse 60% 30% at 40% 22%, #fff 30%, transparent 75%), linear-gradient(180deg, #ffe4ef 0%, #ffc4dc 50%, #f6a5c6 100%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-stroke-color: #d66d9a; }
.skin-marsh .slot.ghost { opacity: .22; }
/* en cours : la guimauve gigote, s'écrase et s'étire */
.skin-marsh .slot.spinning { opacity: .9; animation: mal-jiggle .22s cubic-bezier(.45, 0, .55, 1) infinite alternate; }
@keyframes mal-jiggle { 0% { transform: translateY(.03em) scale(1.1, .88); filter: blur(.4px); } 100% { transform: translateY(-.05em) scale(.92, 1.08); filter: blur(.2px); } }
/* elle se pose : tombe étirée, s'écrase au sol (plof), rebondit et se calme */
.skin-marsh .slot.revealed { animation: mal-plop .72s cubic-bezier(.3, 1.2, .5, 1) backwards; }
@keyframes mal-plop {
  0% { transform: translateY(-.28em) scale(.86, 1.16); }
  28% { transform: translateY(0) scale(1.24, .74); }
  48% { transform: translateY(-.06em) scale(.88, 1.13); }
  66% { transform: scale(1.07, .94); }
  84% { transform: scale(.98, 1.02); }
  100% { transform: none; } }
.skin-marsh .slot.collapsed { width: 0; height: 0; margin: 0; box-shadow: none; background: none; }
@media (prefers-reduced-motion: reduce) { .skin-marsh .slot { animation: none; } }
/* cadre de duel : un auvent de confiserie à rayures pastel, un canon à confettis qui sursaute, un nuage qui flotte */
.side-marsh { --side-border: #f472b6; --side-glow: 0 0 14px rgba(244, 114, 182, .4); --side-ink: #db2777;
  --side-bg: radial-gradient(circle at 50% 0, rgba(249, 168, 212, .75) 0 9px, transparent 10px) 0 0 / 20px 14px repeat-x,
    repeating-linear-gradient(90deg, rgba(249, 168, 212, .7) 0 10px, rgba(255, 241, 247, .7) 10px 20px) 0 0 / 100% 7px no-repeat,
    radial-gradient(ellipse 60% 40% at 50% 105%, rgba(255, 255, 255, .22), transparent 70%),
    linear-gradient(180deg, rgba(251, 207, 232, .3), rgba(196, 181, 253, .24));
  --deco-a: '🎉'; --deco-b: '☁️ 🍡'; }
.side-marsh::before { font-size: 1.15rem; transform-origin: 20% 90%; animation: mal-pop 2.2s cubic-bezier(.3, 1.6, .5, 1) infinite; }
.side-marsh::after { animation: mal-float 3s ease-in-out infinite alternate; }
@keyframes mal-pop { 0%, 60%, 100% { transform: none; } 68% { transform: rotate(-14deg) scale(1.25, .85); } 80% { transform: rotate(4deg) scale(.95, 1.08); } }
@keyframes mal-float { 0% { transform: translateY(0); } 100% { transform: translateY(-4px); } }
/* ------------------------------------------------------------------ Lab (idée de costoroll, 2026-10-21) : six tubes à
   essai remplis aux deux tiers (rouge, violet, bleu, orange, blanc, vert), posés dans un portoir en bois devant un mur de
   labo carrelé. Chaque chiffre est une silhouette sombre qui flotte dans le liquide pendant le tirage ; quand il se pose,
   le tube tinte contre le portoir (secousse rigide, pas d'écrasement : c'est du verre) et le chiffre s'illumine de la
   couleur de son liquide. Les bulles de la fin sont dessinées par js/skinfx.js (SCENES.lab), plus fortes dès Mythic. */
.num-card.skin-lab {
  background:
    /* étagère du fond : fioles et ballons en ombre chinoise */
    url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='40' viewBox='0 0 160 40'><g fill='%2394f2e4' fill-opacity='.13'><path d='M10 38h12l-4-12v-10h-4v10z'/><circle cx='48' cy='31' r='7'/><rect x='46' y='16' width='4' height='10'/><rect x='70' y='18' width='5' height='20' rx='2'/><rect x='78' y='22' width='5' height='16' rx='2'/><path d='M104 38h16l-5-14v-8h-6v8z'/><circle cx='140' cy='32' r='6'/><rect x='138' y='20' width='4' height='8'/></g><rect y='38' width='160' height='2' fill='%23cbd5e1' fill-opacity='.16'/></svg>") 0 0 / 6.4em 1.6em repeat-x,
    /* carrelage blanc du labo, joints fins */
    repeating-linear-gradient(0deg, rgba(148, 163, 184, .14) 0 1px, transparent 1px .5em),
    repeating-linear-gradient(90deg, rgba(148, 163, 184, .14) 0 1px, transparent 1px .5em),
    radial-gradient(ellipse 70% 60% at 50% 40%, rgba(94, 234, 212, .16), transparent 70%),
    linear-gradient(180deg, #16303a 0%, #0f2129 62%, #3a2614 62.5%, #2a1a0c 100%);
  border: 2px solid #64748b; border-radius: .7rem;
  box-shadow: inset 0 0 0 1px rgba(226, 232, 240, .18), inset 0 -.3em .6em rgba(0, 0, 0, .45), 0 0 14px rgba(45, 212, 191, .2), 0 10px 18px rgba(0, 0, 0, .4);
  padding-top: .25rem; padding-bottom: .45rem;
}
.skin-lab .slot {
  --liq: #f97316; --liq-d: #9a3412; --liq-hi: #fdba74; --glow: #ffedd5;
  position: relative; box-sizing: border-box; font-size: .56em; font-weight: 900; line-height: 1;
  width: 1.08em; height: 2.45em; margin: 0 .09em; padding-bottom: .24em;
  display: inline-flex; align-items: flex-end; justify-content: center; vertical-align: bottom;
  border: 1px solid rgba(226, 232, 240, .55); border-top-color: rgba(255, 255, 255, .8); border-radius: .14em .14em .56em .56em;
  /* le chiffre s'est allumé : clair, auréolé de la couleur du liquide, cerné de sombre pour rester lisible */
  color: var(--glow); -webkit-text-stroke: .022em var(--liq-d);
  text-shadow: 0 0 .1em var(--liq-hi), 0 0 .26em var(--liq), 0 .04em .02em rgba(0, 0, 0, .55);
  background:
    /* reflets du verre : une bande vive à gauche, une plus discrète à droite */
    linear-gradient(90deg, transparent 12%, rgba(255, 255, 255, .5) 17%, rgba(255, 255, 255, .12) 26%, transparent 32%, transparent 72%, rgba(255, 255, 255, .2) 80%, transparent 86%),
    /* ménisque : un fin trait clair à la surface du liquide */
    linear-gradient(180deg, transparent 37%, rgba(255, 255, 255, .6) 37.5%, var(--liq-hi) 39%, transparent 42%),
    /* le liquide, aux deux tiers */
    linear-gradient(180deg, transparent 38%, var(--liq) 44%, var(--liq-d) 100%),
    rgba(226, 232, 240, .07);
  background-size: 100% 100%, 100% 100%, 100% 100%, auto;
  box-shadow: inset 0 .08em 0 rgba(255, 255, 255, .35), inset -.1em 0 .14em rgba(0, 0, 0, .35), 0 .05em .14em rgba(0, 0, 0, .5);
  transform-origin: 50% 20%;
}
/* Six liquides dans l'ordre de costoroll (nth-of-type : le canvas des effets se glisse en tête de la carte). */
.skin-lab .slot:nth-of-type(6n+2) { --liq: #2563eb; --liq-d: #1e3a8a; --liq-hi: #93c5fd; --glow: #dbeafe; }
.skin-lab .slot:nth-of-type(6n+3) { --liq: #e2e8f0; --liq-d: #64748b; --liq-hi: #ffffff; --glow: #ffffff; }
.skin-lab .slot:nth-of-type(6n+4) { --liq: #9333ea; --liq-d: #4c1d95; --liq-hi: #d8b4fe; --glow: #f3e8ff; }
.skin-lab .slot:nth-of-type(6n+5) { --liq: #16a34a; --liq-d: #14532d; --liq-hi: #86efac; --glow: #dcfce7; }
.skin-lab .slot:nth-of-type(6n+6) { --liq: #dc2626; --liq-d: #7f1d1d; --liq-hi: #fca5a5; --glow: #fee2e2; }
/* le liquide blanc est clair : le chiffre y garde une ombre plus franche */
.skin-lab .slot:nth-of-type(6n+3) { -webkit-text-stroke-width: .04em; text-shadow: 0 0 .12em #fff, 0 0 .3em #bae6fd, 0 .04em .03em rgba(15, 23, 42, .8); }
/* le portoir : une barre de bois qui passe devant chaque tube (les morceaux se rejoignent d'un tube à l'autre) */
.skin-lab .slot::before { content: ''; position: absolute; left: -.2em; right: -.2em; top: 15%; height: .3em; pointer-events: none; z-index: 2;
  background: radial-gradient(ellipse 34% 60% at 50% 50%, rgba(0, 0, 0, .45), transparent 75%), linear-gradient(180deg, #d4a373, #a0703f 55%, #6b4423);
  box-shadow: 0 .05em .06em rgba(0, 0, 0, .45); }
/* les bulles : invisibles au repos, elles montent pendant le tirage et jaillissent quand le chiffre se pose */
.skin-lab .slot::after { content: ''; position: absolute; left: 6%; right: 6%; top: 42%; bottom: 8%; pointer-events: none; opacity: 0;
  background:
    radial-gradient(circle, rgba(255, 255, 255, .85) 0 .035em, transparent .05em) 0% 80% / .2em .2em no-repeat,
    radial-gradient(circle, rgba(255, 255, 255, .75) 0 .025em, transparent .04em) 100% 55% / .2em .2em no-repeat,
    radial-gradient(circle, rgba(255, 255, 255, .8) 0 .04em, transparent .055em) 4% 25% / .2em .2em no-repeat,
    radial-gradient(circle, rgba(255, 255, 255, .7) 0 .03em, transparent .045em) 96% 6% / .2em .2em no-repeat,
    radial-gradient(circle, rgba(255, 255, 255, .6) 0 .025em, transparent .04em) 50% 0% / .2em .2em no-repeat; }
.skin-lab .slot.ghost { opacity: .22; }
.skin-lab .slot.collapsed { width: 0; height: 0; margin: 0; border: 0; padding: 0; box-shadow: none; background: none; }
.skin-lab .slot.collapsed::before, .skin-lab .slot.collapsed::after { display: none; }
/* Pendant le tirage : le chiffre n'est qu'une silhouette sombre qui flotte (il monte et descend dans le liquide), le
   liquide clapote, des bulles montent. */
.skin-lab .slot.spinning { opacity: .95; color: rgba(8, 10, 20, .6); -webkit-text-stroke-color: transparent; text-shadow: 0 0 .05em rgba(8, 10, 20, .6), 0 .14em .12em rgba(8, 10, 20, .3);
  animation: lab-float .3s ease-in-out infinite alternate; }
.skin-lab .slot.spinning::after { animation: lab-rise .5s linear infinite; }
@keyframes lab-float {
  from { padding-bottom: .18em; background-position: 0 0, 0 .03em, 0 .03em, 0 0; }
  to { padding-bottom: .36em; background-position: 0 0, 0 -.03em, 0 -.03em, 0 0; }
}
@keyframes lab-rise { 0% { opacity: .9; transform: translateY(.2em); } 100% { opacity: .5; transform: translateY(-.35em); } }
/* Il se pose : le tube recule un peu (élan), tinte contre le portoir (secousse rigide qui s'amortit) ; le chiffre passe
   de l'ombre à un éclair blanc, puis garde la lueur de son liquide ; une gerbe de bulles part vers la surface. */
.skin-lab .slot.revealed { animation: lab-clink .62s cubic-bezier(.25, .9, .35, 1) backwards, lab-light .7s ease-out backwards; }
.skin-lab .slot.revealed::after { animation: lab-burst .7s ease-out backwards; }
@keyframes lab-clink {
  0% { transform: rotate(0); }
  12% { transform: translateY(-.1em) rotate(3deg); }
  24% { transform: rotate(-6deg); }
  40% { transform: rotate(4deg); }
  58% { transform: rotate(-2deg); }
  78% { transform: rotate(.8deg); }
  100% { transform: none; }
}
@keyframes lab-light {
  0%, 14% { color: rgba(8, 10, 20, .6); -webkit-text-stroke-color: transparent; text-shadow: 0 0 .05em rgba(8, 10, 20, .6); }
  26% { color: #fff; text-shadow: 0 0 .1em #fff, 0 0 .35em var(--liq-hi), 0 0 .8em var(--liq); }
}
@keyframes lab-burst {
  0%, 18% { opacity: 0; transform: translateY(.25em) scale(.8); }
  30% { opacity: 1; }
  100% { opacity: 0; transform: translateY(-.45em) scale(1.15); }
}
@media (prefers-reduced-motion: reduce) { .skin-lab .slot, .skin-lab .slot::after { animation: none; } }
/* Cadre de duel : la paillasse d'un labo, carrelage clair et lueur turquoise ; le tube à essai bouillonne, le ballon tangue. */
.side-lab { --side-border: #2dd4bf; --side-glow: 0 0 16px rgba(45, 212, 191, .35); --side-ink: #0d9488;
  --side-bg: linear-gradient(180deg, transparent 72%, rgba(120, 72, 32, .22) 72.5%), repeating-linear-gradient(0deg, rgba(148, 163, 184, .1) 0 1px, transparent 1px 14px), repeating-linear-gradient(90deg, rgba(148, 163, 184, .1) 0 1px, transparent 1px 14px), radial-gradient(ellipse 80% 60% at 50% 30%, rgba(45, 212, 191, .14), transparent 70%);
  --deco-a: '🧪'; --deco-b: '⚗️ 🔬'; }
.side-lab::before { font-size: 1.15rem; transform-origin: 50% 90%; animation: lab-bubble 1.6s ease-in-out infinite; }
.side-lab::after { transform-origin: 30% 100%; animation: lab-tilt 2.4s ease-in-out infinite; }
@keyframes lab-bubble { 0%, 100% { transform: none; } 40% { transform: rotate(-8deg) translateY(-1px); } 60% { transform: rotate(6deg); } }
@keyframes lab-tilt { 0%, 100% { transform: rotate(0); } 50% { transform: rotate(-6deg); } }
.room-stage.many .side-lab::before, .room-stage.many .side-lab::after { animation: none; }
@media (prefers-reduced-motion: reduce) { .side-lab::before, .side-lab::after { animation: none; } }
/* ------------------------------------------------------------------ Burger (idée de jaxoncool43, 2026-10-23) : un burger
   de diner vu de profil. Pain brioché doré et brillant, graines de sésame ; la garniture se lit de gauche à droite, un
   ingrédient par chiffre (salade, cheddar, steak grillé, tomate, oignon, cornichon) et le chiffre imprimé dessus.
   Pendant le tirage, le pain du dessus est soulevé (hors de la carte) et les chiffres grésillent sur la plaque ; chaque
