/* ------------------------------------------------------------------ Polygon Donut (idée de PongonLOLZFan, 2026-10-21) :
   un donut 3D en low poly, tout en facettes plates. Fond pastel en maillage de triangles (rose, lilas, menthe) semé de
   vermicelles. Les chiffres sont taillés en facettes : glaçage rose et chocolat en alternance, arêtes nettes, épaisseur
   en dessous. Matière rigide (des polygones) : pas d'écrasement. En cours, les facettes miroitent et pivotent par
   crans ; à la pose, le chiffre bascule d'un coup sec sur sa face, dépasse et se cale. Le donut qui tourne derrière les
   chiffres et les vermicelles qui rebondissent sont dans js/skinfx.js (SCENES.polydonut). */
.num-card.skin-polydonut {
  background:
    /* vermicelles */
    linear-gradient(35deg, transparent 46%, #f472b6 46% 54%, transparent 54%) 4% 8% / .28em .28em no-repeat,
    linear-gradient(-50deg, transparent 46%, #38bdf8 46% 54%, transparent 54%) 31% 96% / .28em .28em no-repeat,
    linear-gradient(80deg, transparent 46%, #facc15 46% 54%, transparent 54%) 58% 4% / .28em .28em no-repeat,
    linear-gradient(-20deg, transparent 46%, #4ade80 46% 54%, transparent 54%) 84% 97% / .28em .28em no-repeat,
    linear-gradient(60deg, transparent 46%, #a78bfa 46% 54%, transparent 54%) 97% 10% / .28em .28em no-repeat,
    /* voile clair au centre : le maillage reste derrière les chiffres sans les brouiller */
    radial-gradient(ellipse 70% 60% at 50% 50%, rgba(255, 245, 250, .45), transparent 80%),
    /* maillage low poly : triangles pastel de teintes voisines */
    url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='120' height='60' viewBox='0 0 120 60'><path d='M0 0h30L0 30z' fill='%23fbcfe8'/><path d='M30 0L0 30h34z' fill='%23f9a8d4'/><path d='M30 0h35L34 30z' fill='%23fce7f3'/><path d='M65 0L34 30h40z' fill='%23f5d0fe'/><path d='M65 0h30L74 30z' fill='%23e9d5ff'/><path d='M95 0L74 30h46z' fill='%23fbcfe8'/><path d='M95 0h25v30z' fill='%23f9a8d4'/><path d='M0 30h34L0 60z' fill='%23ddd6fe'/><path d='M34 30L0 60h30z' fill='%23f5d0fe'/><path d='M34 30h40L30 60z' fill='%23fbcfe8'/><path d='M74 30L30 60h48z' fill='%23fce7f3'/><path d='M74 30h46L78 60z' fill='%23f9a8d4'/><path d='M120 30v30H78z' fill='%23ccfbf1'/></svg>") 0 0 / 3.6em 1.8em,
    #fbcfe8;
  border: 2px solid #db2777; border-radius: .7rem;
  box-shadow: inset 0 .2em 0 rgba(255, 255, 255, .45), inset 0 -.25em 0 rgba(190, 24, 93, .18), 0 0 0 1px rgba(255, 255, 255, .4), 0 0 16px rgba(244, 114, 182, .35), 0 10px 18px rgba(157, 23, 77, .25);
}
.skin-polydonut .slot { position: relative; z-index: 1; font-weight: 900; color: transparent;
  /* facettes du glaçage : des aplats séparés par des arêtes nettes, éclairés d'en haut à gauche */
  background: linear-gradient(155deg, #ffffff 0 24%, #fdf2f8 24% 38%, #f9a8d4 38% 55%, #ec4899 55% 72%, #be185d 72%);
  background-size: 100% 100%;
  -webkit-background-clip: text; background-clip: text; -webkit-text-stroke: .03em #831843; paint-order: stroke fill;
  filter: drop-shadow(.03em .07em 0 #9d174d) drop-shadow(0 .1em .08em rgba(80, 7, 36, .4)); }
/* un chiffre sur deux : glaçage chocolat */
.skin-polydonut .slot:nth-of-type(even) { background: linear-gradient(155deg, #fde68a 0 20%, #d97706 20% 36%, #92400e 36% 58%, #78350f 58% 76%, #451a03 76%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-stroke-color: #2a1003; filter: drop-shadow(.03em .07em 0 #451a03) drop-shadow(0 .1em .08em rgba(42, 16, 3, .45)); }
.skin-polydonut .slot.ghost { opacity: .2; }
/* en cours : les facettes pivotent par crans (comme un objet 3D en peu de polygones) et la lumière glisse dessus */
.skin-polydonut .slot.spinning { opacity: .92; animation: pd-facet .3s steps(3, end) infinite alternate; }
.skin-polydonut .slot.spinning:nth-of-type(odd) { animation-delay: -.15s; }
@keyframes pd-facet {
  0% { transform: perspective(2em) rotateY(-40deg); filter: brightness(1.15) drop-shadow(.03em .07em 0 #9d174d); }
  50% { transform: perspective(2em) rotateY(0) translateY(-.04em); filter: brightness(.9) drop-shadow(.03em .07em 0 #9d174d); }
  100% { transform: perspective(2em) rotateY(40deg); filter: brightness(1.2) drop-shadow(.03em .07em 0 #9d174d); } }
/* il se pose : bascule d'un coup sec de la tranche à la face, dépasse, se cale ; un éclair sur les arêtes */
.skin-polydonut .slot.revealed { animation: pd-flip .6s cubic-bezier(.2, 1.4, .4, 1) backwards; }
@keyframes pd-flip {
  0% { transform: perspective(2em) rotateX(-85deg) scale(.85); filter: brightness(1.5) drop-shadow(.03em .07em 0 #9d174d); }
  14% { transform: perspective(2em) rotateX(-85deg) scale(.85); }
  40% { transform: perspective(2em) rotateX(14deg) scale(1.14); filter: brightness(1.35) drop-shadow(.03em .07em 0 #9d174d) drop-shadow(0 0 .2em #fff); }
  60% { transform: perspective(2em) rotateX(-6deg) scale(.98); }
  80% { transform: perspective(2em) rotateX(2deg) scale(1.01); }
  100% { transform: none; } }
.skin-polydonut .slot.collapsed { width: 0; height: 0; margin: 0; box-shadow: none; background: none; }
@media (prefers-reduced-motion: reduce) { .skin-polydonut .slot { animation: none; } }
/* cadre de duel : une vitrine de pâtisserie pastel en maillage de triangles, un donut qui tourne, des vermicelles */
.side-polydonut { --side-border: #ec4899; --side-glow: 0 0 14px rgba(236, 72, 153, .38); --side-ink: #db2777;
  --side-bg: linear-gradient(135deg, rgba(244, 114, 182, .22) 25%, transparent 25%) 0 0 / 22px 22px,
    linear-gradient(225deg, rgba(167, 139, 250, .2) 25%, transparent 25%) 0 0 / 22px 22px,
    linear-gradient(315deg, rgba(45, 212, 191, .14) 25%, transparent 25%) 0 0 / 22px 22px,
    linear-gradient(180deg, rgba(236, 72, 153, .22), rgba(139, 92, 246, .18));
  --deco-a: '🍩'; --deco-b: '✨'; }
.side-polydonut::before { font-size: 1.2rem; animation: pd-turn 2.4s steps(8, end) infinite; }
.side-polydonut::after { animation: pd-twinkle 1.8s steps(3, end) infinite alternate; }
@keyframes pd-turn { 0% { transform: rotateY(0) rotate(0); } 100% { transform: rotateY(360deg) rotate(45deg); } }
@keyframes pd-twinkle { 0% { transform: rotate(0) scale(1); opacity: .9; } 100% { transform: rotate(30deg) scale(1.2); opacity: .5; } }
/* ------------------------------------------------------------------ Sonic Wave (idée de Matthew, 2026-10-21) : l'écran
   d'un oscilloscope. Grille fine, onde qui court au milieu, barres d'égaliseur en bas ; les chiffres sont des traces
   lumineuses cyan, dédoublées en rose et bleu comme un signal saturé. En tirage ils vibrent sur la fréquence ; quand
   ils se posent, une onde de choc part du chiffre (le « boum » du son). L'onde vivante et les grands anneaux de la fin
   sont dessinés par js/skinfx.js (SCENES.sonic), plus forts dès Mythic. Matière : de la lumière, pas d'écrasement. */
.num-card.skin-sonic {
  background:
    /* égaliseur en bas : des barres de hauteurs différentes */
    url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='96' height='40'><g fill='%2322d3ee' fill-opacity='.2'><rect x='1' y='24' width='6' height='16'/><rect x='9' y='12' width='6' height='28'/><rect x='17' y='30' width='6' height='10'/><rect x='25' y='18' width='6' height='22'/><rect x='33' y='6' width='6' height='34'/><rect x='41' y='26' width='6' height='14'/><rect x='49' y='16' width='6' height='24'/><rect x='57' y='32' width='6' height='8'/><rect x='65' y='10' width='6' height='30'/><rect x='73' y='22' width='6' height='18'/><rect x='81' y='28' width='6' height='12'/><rect x='89' y='14' width='6' height='26'/></g></svg>") 0 100% / 2.4em 1em repeat-x,
    /* deux ondes au repos, rose et cyan, décalées */
    url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='200' height='40'><path d='M0 20 Q12.5 4 25 20 T50 20 T75 20 T100 20 T125 20 T150 20 T175 20 T200 20' fill='none' stroke='%23e879f9' stroke-opacity='.3' stroke-width='1.4'/><path d='M0 20 Q25 34 50 20 T100 20 T150 20 T200 20' fill='none' stroke='%2367e8f9' stroke-opacity='.38' stroke-width='1.6'/></svg>") 0 50% / 5em 1em repeat-x,
    /* grille de l'oscilloscope */
    repeating-linear-gradient(0deg, rgba(34, 211, 238, .08) 0 1px, transparent 1px .45em),
    repeating-linear-gradient(90deg, rgba(34, 211, 238, .08) 0 1px, transparent 1px .45em),
    radial-gradient(ellipse 70% 60% at 50% 50%, rgba(56, 189, 248, .2), transparent 70%),
    linear-gradient(180deg, #050816 0%, #0a1033 55%, #150a2e 100%);
  border: 2px solid #155e75; border-radius: .7rem;
  box-shadow: inset 0 0 0 1px rgba(34, 211, 238, .28), inset 0 0 1.2em rgba(2, 6, 23, .8), 0 0 16px rgba(34, 211, 238, .28), 0 10px 20px rgba(0, 0, 0, .5);
}
.skin-sonic .slot { position: relative; z-index: 1; font-weight: 900; color: #ecfeff;
  text-shadow: -.035em 0 0 rgba(236, 72, 153, .8), .035em 0 0 rgba(34, 211, 238, .9), 0 0 .2em #22d3ee, 0 0 .5em rgba(34, 211, 238, .35), 0 .05em .04em #020617; }
.skin-sonic .slot.ghost { opacity: .2; }
/* l'onde de choc : un anneau invisible au repos, il part du chiffre quand celui-ci se pose */
.skin-sonic .slot::after { content: ''; position: absolute; left: 50%; top: 52%; width: 1em; height: 1em; margin: -.5em 0 0 -.5em; border-radius: 50%; pointer-events: none; opacity: 0;
  border: .07em solid #a5f3fc; box-shadow: 0 0 .18em #22d3ee, inset 0 0 .16em #e879f9; }
.skin-sonic .slot.ghost::after { display: none; }
/* en tirage : le chiffre vibre sur la fréquence, le signal se dédouble davantage */
.skin-sonic .slot.spinning { opacity: .85; animation: son-buzz .08s linear infinite alternate; }
@keyframes son-buzz {
  0% { transform: translate(-.04em, .01em) scale(1, .93); text-shadow: -.12em 0 0 rgba(236, 72, 153, .75), .12em 0 0 rgba(34, 211, 238, .85), 0 0 .3em #22d3ee; }
  100% { transform: translate(.04em, -.02em) scale(1, 1.08); text-shadow: -.05em 0 0 rgba(236, 72, 153, .75), .05em 0 0 rgba(34, 211, 238, .85), 0 0 .2em #22d3ee; }
}
/* il se pose : le signal se tasse (élan), claque en blanc, puis la vibration s'amortit ; l'anneau part en même temps */
.skin-sonic .slot.revealed { animation: son-boom .66s cubic-bezier(.2, .8, .3, 1) backwards; }
.skin-sonic .slot.revealed::after { animation: son-ring .66s cubic-bezier(.1, .7, .3, 1) backwards; }
@keyframes son-boom {
  0% { transform: scale(.8, .6); filter: brightness(.6); }
  16% { transform: scale(1.2); filter: brightness(1.7); }
  30% { transform: translateY(-.05em) scale(1.02); }
  44% { transform: translateY(.04em); filter: brightness(1.3); }
  58% { transform: translateY(-.025em); }
  74% { transform: translateY(.012em); }
  100% { transform: none; filter: none; }
}
@keyframes son-ring { 0%, 10% { opacity: 0; transform: scale(.3); } 18% { opacity: 1; transform: scale(.55); } 100% { opacity: 0; transform: scale(2.8); border-width: .01em; } }
.skin-sonic .slot.collapsed { width: 0; height: 0; margin: 0; box-shadow: none; background: none; }
.skin-sonic .slot.collapsed::after { display: none; }
@media (prefers-reduced-motion: reduce) { .skin-sonic .slot, .skin-sonic .slot::after { animation: none; } }
/* Cadre de duel : un écran d'oscilloscope ; le haut-parleur bat la mesure, le casque oscille. */
.side-sonic { --side-border: #22d3ee; --side-glow: 0 0 16px rgba(34, 211, 238, .38); --side-ink: #0891b2;
  --side-bg: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='200' height='40'><path d='M0 20 Q12.5 4 25 20 T50 20 T75 20 T100 20 T125 20 T150 20 T175 20 T200 20' fill='none' stroke='%2322d3ee' stroke-opacity='.22' stroke-width='1.4'/></svg>") 0 85% / 120px 24px repeat-x, repeating-linear-gradient(0deg, rgba(34, 211, 238, .07) 0 1px, transparent 1px 12px), repeating-linear-gradient(90deg, rgba(34, 211, 238, .07) 0 1px, transparent 1px 12px), radial-gradient(ellipse 80% 60% at 50% 35%, rgba(168, 85, 247, .14), transparent 70%);
  --deco-a: '🔊'; --deco-b: '🎧 〰️'; }
.side-sonic::before { font-size: 1.15rem; animation: son-thump 1.6s ease-out infinite; }
.side-sonic::after { transform-origin: 50% 80%; animation: son-sway 2.4s ease-in-out infinite; }
@keyframes son-thump { 0%, 30%, 60%, 100% { transform: none; } 8% { transform: scale(1.22); } 38% { transform: scale(1.14); } }
@keyframes son-sway { 0%, 100% { transform: rotate(-5deg); } 50% { transform: rotate(5deg); } }
