  38% { transform: scale(1.12); color: #fff; text-shadow: 0 0 .08em #1e1b4b, 0 0 .2em #1e1b4b, 0 0 .5em #22d3ee, 0 0 .9em #e879f9; }
  70% { transform: scale(.96); }
