}
.room-stage.many .num-card.skin-dna::before, .num-card.sm.skin-dna::before { animation: none; }
@media (prefers-reduced-motion: reduce) { .num-card.skin-dna::before, .skin-dna .slot { animation: none; } }
/* Cadre de duel : un labo sombre, la lueur d'une hélice ; 🧬 tourne, 🔬 se penche. */
.side-dna { --side-border: #6366f1; --side-glow: 0 0 16px rgba(34, 211, 238, .3); --side-ink: #6366f1;
  --side-bg: radial-gradient(ellipse 50% 70% at 50% 45%, rgba(34, 211, 238, .16), transparent 70%), radial-gradient(ellipse 40% 50% at 15% 90%, rgba(232, 121, 249, .16), transparent 70%), radial-gradient(ellipse 40% 50% at 85% 10%, rgba(99, 102, 241, .18), transparent 70%);
  --deco-a: '🧬'; --deco-b: '🔬'; }
.side-dna::before { animation: dna-spin 3s ease-in-out infinite; }
.side-dna::after { transform-origin: 50% 100%; animation: dna-peek 2.2s ease-in-out infinite; }
@keyframes dna-spin { 0%, 100% { transform: scaleX(1); } 50% { transform: scaleX(-1); } }
@keyframes dna-peek { 0%, 100% { transform: rotate(-5deg); } 50% { transform: rotate(5deg); } }
.room-stage.many .side-dna::before, .room-stage.many .side-dna::after { animation: none; }
@media (prefers-reduced-motion: reduce) { .side-dna::before, .side-dna::after { animation: none; } }
/* ------------------------------------------------------------------ Waterfall (idée de JBearr12 et jjcoolcid1,
   2026-10-24) : une cascade dans une vallée verte. En haut, le rebord de la falaise (herbe et mousse) ; derrière les
   chiffres, un rideau d'eau qui tombe sans fin (::before, stries qui défilent) ; en bas, le bassin et son écume ; des
   rochers sombres sur les côtés. Chiffres blancs cernés de bleu nuit, lisibles sur l'eau claire. Pendant le tirage le
   courant les emporte vers le bas ; ils tombent d'en haut et touchent le bassin ; l'éclaboussure, la brume et l'arc-en-
   ciel (dès Epic) sont dans js/skinfx.js (SCENES.waterfall). */
.num-card.skin-waterfall {
  background:
    /* le rebord de la falaise : des buissons ronds de trois verts, la roche moussue dessous */
    url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 80 16' preserveAspectRatio='none'><path d='M0 16V9Q40 6 80 9V16Z' fill='%23365314'/><g fill='%2315803d'><circle cx='4' cy='7' r='6'/><circle cx='15' cy='5' r='5'/><circle cx='64' cy='5' r='5'/><circle cx='76' cy='7' r='6'/></g><g fill='%2322c55e'><circle cx='9' cy='4' r='4'/><circle cx='70' cy='4' r='4'/><circle cx='30' cy='8' r='3'/><circle cx='50' cy='8' r='3'/></g><g fill='%2386efac'><circle cx='8' cy='2.5' r='1.6'/><circle cx='69' cy='2.5' r='1.6'/></g><path d='M20 9Q40 7.5 60 9' stroke='%23e0f2fe' stroke-width='1.6' fill='none'/></svg>") 0 0 / 100% .5em no-repeat,
    /* fougères sur les rochers, à gauche et à droite */
