    /* le bassin : des bouillons d'écume, puis l'eau profonde */
    url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 8' preserveAspectRatio='none'><g fill='%23f0f9ff'><circle cx='3' cy='5' r='3'/><circle cx='9' cy='4' r='3.6'/><circle cx='16' cy='5' r='3'/><circle cx='22' cy='3.6' r='3.8'/><circle cx='29' cy='5' r='3.2'/><circle cx='35' cy='4' r='3.4'/></g></svg>") 50% calc(100% - .3em) / 86% .2em no-repeat,
    linear-gradient(180deg, transparent calc(100% - .36em), #a5f3fc calc(100% - .36em), #0e7490 calc(100% - .12em), #164e63) 0 0 / 100% 100% no-repeat,
    /* rochers sombres de chaque côté, de la mousse dessus */
    radial-gradient(ellipse 12% 30% at 3% 30%, #3f6212 50%, transparent 54%), radial-gradient(ellipse 12% 30% at 97% 30%, #3f6212 50%, transparent 54%),
    radial-gradient(ellipse 14% 70% at 0% 60%, #292524 60%, transparent 62%), radial-gradient(ellipse 14% 70% at 100% 60%, #292524 60%, transparent 62%),
