  68% { transform: scale(.97); filter: brightness(1.2) drop-shadow(0 .04em 0 #4c1d95) drop-shadow(0 0 .3em rgba(253, 224, 71, .8)); }
  100% { transform: none; }
}
.room-stage.many .num-card.skin-fairydust::before, .num-card.sm.skin-fairydust::before { animation: none; }
@media (prefers-reduced-motion: reduce) { .num-card.skin-fairydust::before, .skin-fairydust .slot { animation: none; } }
/* Cadre de duel : une clairière au crépuscule ; 🧚 volette, ✨ scintille. */
.side-fairydust { --side-border: #c084fc; --side-glow: 0 0 16px rgba(232, 121, 249, .35); --side-ink: #7e22ce;
  --side-bg: radial-gradient(ellipse 50% 60% at 50% 30%, rgba(253, 224, 71, .16), transparent 70%), radial-gradient(ellipse 60% 40% at 15% 100%, rgba(34, 197, 94, .2), transparent 70%), radial-gradient(ellipse 60% 40% at 85% 100%, rgba(34, 197, 94, .2), transparent 70%), linear-gradient(180deg, rgba(126, 34, 206, .18), rgba(76, 29, 149, .08));
  --deco-a: '🧚'; --deco-b: '✨'; }
.side-fairydust::before { animation: fdu-flit 2.8s ease-in-out infinite; }
.side-fairydust::after { animation: fdu-spark 1.6s ease-in-out infinite; }
@keyframes fdu-flit { 0%, 100% { transform: translate(0, 0) rotate(-4deg); } 50% { transform: translate(3px, -5px) rotate(4deg); } }
@keyframes fdu-spark { 0%, 100% { transform: scale(.8); opacity: .5; } 50% { transform: scale(1.15); opacity: 1; } }
.room-stage.many .side-fairydust::before, .room-stage.many .side-fairydust::after { animation: none; }
@media (prefers-reduced-motion: reduce) { .side-fairydust::before, .side-fairydust::after { animation: none; } }

/* ------------------------------------------------------------------ UFO (idée de JBearr12, 2026-10-21) : un champ la
   nuit, ciel étoilé, lune, herbe au premier plan. Une petite soucoupe (dessinée par js/skinfx.js, SCENES.ufo) survole
   la carte : pendant le tirage son rayon tracteur clignote sur chaque chiffre, qui flotte dedans, flou et pâle ; quand
   il se pose, le rayon s'allume en grand, le chiffre descend et atterrit dans l'herbe (petit rebond rigide, nuage de
   poussière). À la fin, la soucoupe file. Sans canevas (classements, profils), une soucoupe fixe reste dans le coin. */
.num-card.skin-ufo {
  background:
    /* herbe : des brins en dents de scie, deux verts */
    url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='60' height='20'><path d='M0 20 L3 8 L5 20 L8 4 L11 20 L13 10 L16 20 L19 6 L22 20 L25 11 L27 20 L30 3 L33 20 L36 9 L38 20 L41 5 L44 20 L47 10 L49 20 L52 6 L55 20 L57 9 L60 20 Z' fill='%2316a34a'/><path d='M1 20 L5 12 L7 20 L12 13 L14 20 L20 11 L23 20 L28 14 L31 20 L37 12 L40 20 L45 13 L48 20 L53 11 L56 20 Z' fill='%2322c55e'/></svg>") 0 100% / 2.4em .55em repeat-x,
    linear-gradient(0deg, #14532d 0 .3em, transparent .3em),
    /* lune et étoiles */
    radial-gradient(circle at 90% 20%, #fefce8 0 .16em, rgba(254, 249, 195, .28) .2em, transparent .55em),
    radial-gradient(1px 1px at 12% 18%, #fff, transparent), radial-gradient(1px 1px at 30% 34%, #e0f2fe, transparent), radial-gradient(1.2px 1.2px at 52% 12%, #fff, transparent),
    radial-gradient(1px 1px at 68% 30%, #fff, transparent), radial-gradient(1px 1px at 78% 8%, #bbf7d0, transparent), radial-gradient(1px 1px at 6% 46%, #fff, transparent),
    /* lueur verte au-dessus du champ */
    radial-gradient(ellipse 70% 50% at 50% 100%, rgba(163, 230, 53, .22), transparent 70%),
    linear-gradient(180deg, #060a1f 0%, #121a45 58%, #1d3a3a 100%);
  border: 2px solid #1e293b; border-radius: .7rem;
  box-shadow: inset 0 0 0 1px rgba(190, 242, 100, .22), 0 0 16px rgba(132, 204, 22, .22), 0 10px 20px rgba(0, 0, 0, .5);
}
/* la soucoupe fixe du coin, seulement quand aucune scène ne la dessine */
.num-card.skin-ufo:not(.has-fx)::before { content: ''; position: absolute; left: 3%; top: 5%; width: .62em; height: .34em; pointer-events: none; z-index: 0;
  background: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='44' height='24'><ellipse cx='22' cy='9' rx='8' ry='7' fill='%2367e8f9' fill-opacity='.75'/><ellipse cx='22' cy='14' rx='21' ry='6' fill='%23cbd5e1'/><ellipse cx='22' cy='13' rx='21' ry='3' fill='%23f8fafc'/><circle cx='10' cy='15' r='1.6' fill='%23a3e635'/><circle cx='22' cy='17' r='1.6' fill='%23facc15'/><circle cx='34' cy='15' r='1.6' fill='%23a3e635'/></svg>") center / contain no-repeat; opacity: .8; }
.skin-ufo .slot { position: relative; z-index: 1; font-weight: 900; color: #f7fee7;
  -webkit-text-stroke: .025em #14532d; text-shadow: 0 0 .14em rgba(190, 242, 100, .85), 0 0 .4em rgba(132, 204, 22, .35), 0 .06em .03em #052e16; }
.skin-ufo .slot.ghost { opacity: .22; }
/* le rayon tracteur : un cône de lumière verte qui descend du haut de la carte jusqu'au chiffre, éteint au repos */
.skin-ufo .slot::before { content: ''; position: absolute; left: -.22em; right: -.22em; top: -1.2em; bottom: -.05em; z-index: -1; pointer-events: none; opacity: 0;
  clip-path: polygon(36% 0, 64% 0, 100% 100%, 0 100%);
  background: linear-gradient(90deg, transparent 8%, rgba(217, 249, 157, .25) 50%, transparent 92%), linear-gradient(180deg, rgba(132, 204, 22, .08), rgba(132, 204, 22, .4) 75%, rgba(163, 230, 53, .55)); }
/* la poussière de l'atterrissage, au pied du chiffre */
.skin-ufo .slot::after { content: ''; position: absolute; left: -.25em; right: -.25em; bottom: -.08em; height: .35em; pointer-events: none; opacity: 0;
  background: radial-gradient(ellipse 50% 50% at 50% 60%, rgba(236, 252, 203, .85), rgba(134, 239, 172, .4) 55%, transparent 72%); }
.skin-ufo .slot.ghost::before, .skin-ufo .slot.ghost::after { display: none; }
/* en tirage : le chiffre flotte dans le rayon qui grésille, pâle et flou, comme pas encore matérialisé */
.skin-ufo .slot.spinning { color: #d9f99d; animation: ufo-float .5s ease-in-out infinite alternate; }
.skin-ufo .slot.spinning::before { animation: ufo-flicker .18s steps(2) infinite; }
@keyframes ufo-float {
  from { transform: translateY(-.14em) rotate(-4deg); opacity: .7; filter: blur(.5px); }
  to { transform: translateY(-.26em) rotate(4deg); opacity: .92; filter: blur(.1px); }
}
@keyframes ufo-flicker { 0% { opacity: .25; } 50% { opacity: .55; } 100% { opacity: .35; } }
/* il est déposé : le rayon s'allume en grand, le chiffre descend du haut, touche l'herbe, rebondit un peu ; le rayon
   s'éteint et un petit nuage de poussière se soulève */
.skin-ufo .slot.revealed { animation: ufo-drop .7s cubic-bezier(.3, .7, .4, 1) backwards; }
.skin-ufo .slot.revealed::before { animation: ufo-beam .7s ease-out backwards; }
.skin-ufo .slot.revealed::after { animation: ufo-dust .7s ease-out backwards; }
@keyframes ufo-drop {
  0% { transform: translateY(-.6em) scale(.7); filter: brightness(1.8) blur(.8px); }
  42% { transform: translateY(.05em) scale(1); filter: brightness(1.6); animation-timing-function: ease-out; }
  58% { transform: translateY(-.12em); }
  74% { transform: translateY(0); animation-timing-function: ease-out; }
  86% { transform: translateY(-.03em); }
