@keyframes mth-write {
  0% { clip-path: inset(0 100% 0 0); transform: translateY(-.04em); animation-timing-function: cubic-bezier(.4, 0, .6, 1); }
  45% { clip-path: inset(0 0 0 0); transform: translateY(-.04em); }
  58% { clip-path: inset(0 0 0 0); transform: translateY(.03em) scale(1.06); }
  76% { clip-path: inset(0 0 0 0); transform: scale(.98); }
  100% { clip-path: inset(0 0 0 0); transform: none; }
