@media (prefers-reduced-motion: reduce) { .skin-math .slot { animation: none; } }
/* Cadre de duel : une salle de classe, un tableau vert en fond ; ➗ tourne, 📐 se balance. */
.side-math { --side-border: #4ade80; --side-glow: 0 0 16px rgba(74, 222, 128, .25); --side-ink: #15803d;
  --side-bg: radial-gradient(ellipse 80% 60% at 50% 45%, rgba(31, 74, 55, .35), transparent 75%), linear-gradient(180deg, transparent 88%, rgba(139, 90, 43, .35) 88%);
  --deco-a: '➗'; --deco-b: '📐'; }
.side-math::before { animation: mth-turn 3s linear infinite; }
.side-math::after { transform-origin: 50% 0; animation: mth-swing 2s ease-in-out infinite; }
