  background:
    /* la frise à méandres (grecque) en haut, dorée sur fond bleu nuit, filet d'or dessous */
    url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 20 10'><rect width='20' height='10' fill='%231e3a5f'/><path d='M1 9V1h8v6H5V4h2' fill='none' stroke='%23e9c46a' stroke-width='1.3'/><path d='M11 9V1h8v6h-4V4h2' fill='none' stroke='%23e9c46a' stroke-width='1.3'/></svg>") 0 0 / 1em .5em repeat-x,
    linear-gradient(180deg, transparent .5em, #c9a227 .5em, #c9a227 .56em, transparent .56em),
    /* la base : moulures de marbre plus sombres */
    linear-gradient(180deg, transparent calc(100% - .34em), #a8a29e calc(100% - .34em), #e7e5e4 calc(100% - .28em), #d6d3d1 calc(100% - .2em), #78716c calc(100% - .17em), #e7e5e4 calc(100% - .14em), #a8a29e),
    /* les cannelures : ombre au creux, lumière sur l'arête */
    repeating-linear-gradient(90deg, rgba(120, 113, 108, .22) 0, rgba(255, 255, 255, 0) .14em, rgba(255, 255, 255, .55) .3em, rgba(120, 113, 108, .1) .4em, rgba(120, 113, 108, .22) .42em),
    /* les veines grises du marbre */
    url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 120 60'><g fill='none' stroke='%2378716c' stroke-linecap='round'><path d='M-5 12C20 18 30 4 55 14S90 30 125 20' stroke-width='.7' stroke-opacity='.45'/><path d='M10 60C25 40 40 46 52 30S80 20 90 -2' stroke-width='.5' stroke-opacity='.35'/><path d='M60 62C70 50 95 52 125 40' stroke-width='.9' stroke-opacity='.3'/><path d='M30 30C34 34 40 33 46 38' stroke-width='.4' stroke-opacity='.4'/></g></svg>") 0 0 / 6em 3em,
    /* volume du fût : sombre aux bords, clair au centre */
    linear-gradient(90deg, #a8a29e, #e7e5e4 18%, #fafaf9 45%, #f5f5f4 60%, #d6d3d1 85%, #a8a29e);
  border: 2px solid #b08d2a; border-radius: .25rem;
  box-shadow: inset 0 0 0 1px rgba(255, 251, 235, .6), inset 0 -.2em .4em rgba(68, 64, 60, .2), 0 0 14px rgba(233, 196, 106, .25), 0 10px 18px rgba(0, 0, 0, .35);
  padding: .62em .5em .5em;
}
/* les chiffres : gravés en V dans le marbre (ombre en haut du creux, lumière en bas), empattements classiques */
.skin-greek .slot { position: relative; z-index: 1; font-family: 'Times New Roman', Times, 'Liberation Serif', serif; font-weight: 700; font-variant-numeric: lining-nums; color: #3b3632;
  text-shadow: 0 -.025em 0 rgba(28, 25, 23, .55), 0 .035em 0 rgba(255, 255, 255, .95), 0 0 .2em rgba(255, 255, 255, .6); }
.skin-greek .slot.ghost { opacity: .18; }
/* Le tambour tourne : le chiffre romain arrive de la droite, plein face au centre, s'aplatit et pâlit en partant. */
.skin-greek .slot.spinning { color: #57534e; opacity: 1; animation: grk-drum .26s linear infinite; }
.skin-greek .slot.spinning:nth-of-type(2n) { animation-delay: -.09s; }
.skin-greek .slot.spinning:nth-of-type(3n) { animation-delay: -.17s; }
@keyframes grk-drum {
