  100% { transform: translateX(-.2em) scale(.12, .66); opacity: .1; }
}
/* La pose : le tambour finit son quart de tour (élan), le ciseau frappe (coup sec, éclat clair), petit rebond rigide. */
.skin-greek .slot.revealed { animation: grk-chisel .6s backwards; }
@keyframes grk-chisel {
