    radial-gradient(circle at 16% 74%, rgba(251, 191, 36, .16) 0 .2em, transparent .42em),
    radial-gradient(circle at 82% 30%, rgba(244, 114, 182, .14) 0 .18em, transparent .38em),
    radial-gradient(circle at 58% 84%, rgba(56, 189, 248, .12) 0 .2em, transparent .4em),
    linear-gradient(180deg, #0a0f24, #121a3a 58%, #1a1442);
  border: 2px solid #2a1a0c; border-radius: .5rem; color: #e2e8f0;
  box-shadow: inset 0 0 0 .1em #6b4423, inset 0 0 0 .14em #2a1a0c, inset 0 0 .9em rgba(0, 0, 0, .55), 0 0 18px rgba(251, 191, 36, .2), 0 10px 18px rgba(0, 0, 0, .45);
}
.skin-fairylights .slot { --fl: #fbbf24; position: relative; z-index: 1; font-weight: 800;
  color: color-mix(in srgb, var(--fl) 42%, #fff);
  text-shadow: 0 0 .05em #fff, 0 0 .14em var(--fl), 0 0 .34em var(--fl), 0 0 .7em color-mix(in srgb, var(--fl) 55%, transparent); }
.skin-fairylights .slot:nth-of-type(6n+1) { --fl: #f87171; }
