.skin-tornpaper .slot:nth-of-type(2n) { --tear: polygon(0 3%, 14% 7%, 28% 0, 42% 5%, 56% 0, 70% 6%, 84% 1%, 98% 6%, 100% 20%, 95% 36%, 100% 52%, 96% 68%, 100% 84%, 97% 98%, 82% 100%, 68% 94%, 54% 99%, 40% 95%, 26% 100%, 12% 94%, 2% 100%, 0 84%, 5% 68%, 0 52%, 6% 36%, 1% 20%); }
.skin-tornpaper .slot::before { content: ''; position: absolute; inset: .07em; z-index: -1; clip-path: var(--tear);
  background: radial-gradient(circle, rgba(236, 72, 153, .32) 0 .03em, transparent .04em) 0 0 / .12em .12em, linear-gradient(160deg, #fde047, #facc15 60%, #f59e0b); }
/* le kraft qui couvre la fenêtre (seulement pendant le tirage et pendant la déchirure) */
.skin-tornpaper .slot::after { content: ''; position: absolute; inset: 0; z-index: 2; pointer-events: none; opacity: 0;
  background: radial-gradient(ellipse 60% 50% at 50% 45%, rgba(255, 237, 213, .35), transparent 70%), repeating-linear-gradient(8deg, rgba(120, 72, 30, .1) 0 1px, transparent 1px 4px), linear-gradient(180deg, #d4ad74, #c49a5f 60%, #b5874d); }
.skin-tornpaper .slot.ghost { opacity: .2; }
.skin-tornpaper .slot.collapsed { width: 0; height: 0; margin: 0; background: none; }
.skin-tornpaper .slot.collapsed::before, .skin-tornpaper .slot.collapsed::after { display: none; }
/* Pendant le tirage : le kraft couvre la fenêtre, le chiffre se devine à travers, le papier bombe. */
.skin-tornpaper .slot.spinning { opacity: 1; }
.skin-tornpaper .slot.spinning::after { opacity: .9; animation: torn-bulge .5s ease-in-out infinite alternate; }
.skin-tornpaper .slot.spinning:nth-of-type(2n)::after { animation-delay: -.25s; }
@keyframes torn-bulge { from { transform: scale(1); filter: brightness(1); } to { transform: scale(1.04, 1.06); filter: brightness(1.12); } }
/* La déchirure : tiré vers le bas (l'élan), puis arraché en diagonale du coin haut droit vers le coin bas gauche. */
