@keyframes dmn-rock { from { transform: rotate(-2deg); } to { transform: rotate(2deg); } }
@keyframes dmn-shuffle { from { -webkit-mask-position: 0 0; mask-position: 0 0; } to { -webkit-mask-position: .05em .05em; mask-position: .05em .05em; } }
.skin-domino .slot.revealed { animation: dmn-flip .6s backwards; }
@keyframes dmn-flip {
  0% { transform: perspective(3em) translateY(-.45em) rotateX(85deg) rotate(-20deg); animation-timing-function: cubic-bezier(.5, 0, 1, .6); }
  28% { transform: perspective(3em) translateY(.03em) rotateX(0) rotate(0); filter: brightness(1.5) drop-shadow(0 0 .08em #fff); animation-timing-function: cubic-bezier(.2, .8, .3, 1); }
  42% { transform: translateY(-.07em) rotate(-3deg); filter: none; }
