.skin-battleship .slot.ghost { text-shadow: none; }
/* Tirage : à demi noyés dans la brume, ils tanguent avec la houle. */
.skin-battleship .slot.spinning { opacity: .6; color: #94a3b8; filter: blur(.6px); text-shadow: 0 0 .15em rgba(15, 23, 42, .8); animation: bsh-swell .6s ease-in-out infinite alternate; }
.skin-battleship .slot.spinning:nth-of-type(2n) { animation-delay: -.3s; }
@keyframes bsh-swell { from { transform: translateY(.05em) rotate(-3deg); } to { transform: translateY(-.04em) rotate(3deg); } }
/* L'obus vole (chiffre caché), la gerbe le fait jaillir, il retombe et flotte. */
.skin-battleship .slot.revealed { animation: bsh-rise .8s backwards; }
@keyframes bsh-rise {
  0%, 46% { transform: translateY(.3em) scale(.8); filter: opacity(0); }
  50% { transform: translateY(-.14em) scale(1.12); filter: opacity(1) brightness(2.2) drop-shadow(0 0 .1em #fff); animation-timing-function: cubic-bezier(.3, .7, .4, 1); }
  66% { transform: translateY(.05em) scale(.98); filter: brightness(1.2); }
  80% { transform: translateY(-.02em) rotate(-1deg); filter: none; }
  100% { transform: none; }
}
@media (prefers-reduced-motion: reduce) { .skin-battleship .slot { animation: none; } }
/* Cadre de duel : le couchant sur la mer, deux lignes de vagues ; ⚓ se balance, 💥 pulse. */
.side-battleship { --side-border: #ea580c; --side-glow: 0 0 16px rgba(251, 146, 60, .3); --side-ink: #c2410c;
  --side-bg: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='60' height='30'><g fill='none' stroke='%2364748b' stroke-opacity='.35' stroke-width='1.4' stroke-linecap='round'><path d='M4 10q6-5 12 0'/><path d='M34 22q6-5 12 0'/></g></svg>") 0 100% / 60px 30px repeat-x, linear-gradient(180deg, rgba(92, 49, 102, .2), rgba(196, 97, 94, .18) 55%, rgba(28, 43, 79, .22) 56%);
  --deco-a: '⚓'; --deco-b: '💥'; }
.side-battleship::before { transform-origin: 50% 0; animation: bsh-sway 2.6s ease-in-out infinite; }
.side-battleship::after { animation: bsh-pulse 1.8s ease-in-out infinite; }
@keyframes bsh-sway { 0%, 100% { transform: rotate(-10deg); } 50% { transform: rotate(10deg); } }
@keyframes bsh-pulse { 0%, 70%, 100% { transform: scale(.85); } 80% { transform: scale(1.25); } }
.room-stage.many .side-battleship::before, .room-stage.many .side-battleship::after { animation: none; }
@media (prefers-reduced-motion: reduce) { .side-battleship::before, .side-battleship::after { animation: none; } }
/* ------------------------------------------------------------------ Cone of Destiny (idée de Gray alt, 2026-10-28) : la
   matière d'un cône de chantier. Plastique orange brillant (un reflet en biais), deux bandes blanches rétroréfléchissantes
   en haut et en bas (fines hachures qui brillent) ; chiffres noirs, gras et serrés comme au pochoir. Tirage : ils
   culbutent, flous, comme le cône qui tourne en l'air. Un chiffre qui se pose : il tombe et fait « bonk » (écrasé un
   instant, c'est du dessin animé), rebondit et se pose. Le cône, l'explosion démesurée et le cône impassible :
   js/skinfx.js (SCENES.cone). */
.num-card.skin-cone {
  background:
    linear-gradient(100deg, transparent 28%, rgba(255, 255, 255, .26) 36%, transparent 44%),
    repeating-linear-gradient(135deg, rgba(148, 163, 184, .55) 0 1px, transparent 1px 4px) 0 10% / 100% 10% no-repeat,
    repeating-linear-gradient(135deg, rgba(148, 163, 184, .55) 0 1px, transparent 1px 4px) 0 90% / 100% 10% no-repeat,
    linear-gradient(#f8fafc, #e2e8f0) 0 10% / 100% 10% no-repeat,
    linear-gradient(#f8fafc, #e2e8f0) 0 90% / 100% 10% no-repeat,
    linear-gradient(180deg, #ff8f33, #f26a0f 55%, #d4530a);
  border: 2px solid #9a3412; border-radius: .55rem; color: #1c1917;
  box-shadow: inset 0 2px 0 rgba(255, 255, 255, .35), inset 0 -3px 0 rgba(124, 45, 18, .35), 0 0 14px rgba(249, 115, 22, .3), 0 10px 18px rgba(0, 0, 0, .35);
}
.skin-cone .slot { position: relative; z-index: 1; font-family: Impact, Haettenschweiler, 'Arial Narrow Bold', 'Arial Black', sans-serif; font-weight: 900; color: #1c1917;
  text-shadow: 0 .04em 0 rgba(255, 237, 213, .45); }
.skin-cone .slot.ghost { opacity: .22; }
/* Tirage : ils culbutent et tournent un peu, comme le cône en l'air. */
.skin-cone .slot.spinning { opacity: .65; color: #7c2d12; filter: blur(.5px); animation: cone-tumble .3s linear infinite; }
.skin-cone .slot.spinning:nth-of-type(2n) { animation-direction: reverse; }
@keyframes cone-tumble { 0% { transform: rotate(-14deg) translateY(-.04em); } 50% { transform: rotate(14deg) translateY(.04em); } 100% { transform: rotate(-14deg) translateY(-.04em); } }
/* Bonk : il tombe d'en haut, s'écrase, rebondit, se pose. */
.skin-cone .slot.revealed { animation: cone-bonk .6s backwards; }
@keyframes cone-bonk {
  0% { transform: translateY(-.4em) rotate(-25deg) scale(.9); animation-timing-function: cubic-bezier(.5, 0, 1, .6); }
  28% { transform: translateY(.06em) scale(1.22, .78); animation-timing-function: cubic-bezier(.2, .8, .3, 1); }
  48% { transform: translateY(-.12em) scale(.94, 1.08) rotate(3deg); animation-timing-function: cubic-bezier(.5, 0, 1, .6); }
  66% { transform: translateY(0) scale(1.06, .94); }
  82% { transform: scale(.98, 1.02); }
  100% { transform: none; }
}
@media (prefers-reduced-motion: reduce) { .skin-cone .slot { animation: none; } }
/* Cadre de duel : des bandes de chantier orange et blanches en bas ; 🚧 se dandine, 💥 pulse. */
.side-cone { --side-border: #f97316; --side-glow: 0 0 14px rgba(249, 115, 22, .3); --side-ink: #c2410c;
  --side-bg: repeating-linear-gradient(135deg, rgba(249, 115, 22, .3) 0 10px, rgba(248, 250, 252, .25) 10px 20px) 0 100% / 100% 10px no-repeat, linear-gradient(180deg, rgba(249, 115, 22, .08), rgba(249, 115, 22, .16));
  --deco-a: '🚧'; --deco-b: '💥'; }
.side-cone::before { transform-origin: 50% 100%; animation: cone-waddle 1.4s ease-in-out infinite; }
.side-cone::after { animation: cone-pop 2.2s ease-in-out infinite; }
@keyframes cone-waddle { 0%, 100% { transform: rotate(-8deg); } 50% { transform: rotate(8deg); } }
@keyframes cone-pop { 0%, 70%, 100% { transform: scale(.8); } 78% { transform: scale(1.4); } }
.room-stage.many .side-cone::before, .room-stage.many .side-cone::after { animation: none; }
@media (prefers-reduced-motion: reduce) { .side-cone::before, .side-cone::after { animation: none; } }
